class SQLiteFSMStorage(BaseStorage):
    """Persistent aiogram FSM storage backed by the same SQLite database file."""
    def __init__(self, database_path):
        self.connection = sqlite3.connect(
            str(database_path), timeout=30, check_same_thread=False, isolation_level=None
        )
        self.connection.execute("PRAGMA journal_mode=WAL")
        self.connection.execute("PRAGMA busy_timeout=30000")
        self.connection.execute(
            "CREATE TABLE IF NOT EXISTS fsm_storage (storage_key TEXT PRIMARY KEY, state TEXT, data TEXT NOT NULL DEFAULT '{}')"
        )

    @staticmethod
    def _storage_key(key):
        values = [
            getattr(key, "bot_id", 0), getattr(key, "chat_id", 0),
            getattr(key, "user_id", 0), getattr(key, "thread_id", 0),
            getattr(key, "business_connection_id", ""), getattr(key, "destiny", "default")
        ]
        return json.dumps(values, ensure_ascii=False, separators=(",", ":"))

    async def set_state(self, key, state=None):
        value = state.state if hasattr(state, "state") else state
        self.connection.execute(
            "INSERT INTO fsm_storage(storage_key,state,data) VALUES(?,?, '{}') "
            "ON CONFLICT(storage_key) DO UPDATE SET state=excluded.state",
            (self._storage_key(key), value)
        )

    async def get_state(self, key):
        row = self.connection.execute(
            "SELECT state FROM fsm_storage WHERE storage_key=?", (self._storage_key(key),)
        ).fetchone()
        return row[0] if row else None

    async def set_data(self, key, data):
        encoded = json.dumps(data or {}, ensure_ascii=False, separators=(",", ":"), default=str)
        self.connection.execute(
            "INSERT INTO fsm_storage(storage_key,state,data) VALUES(?,NULL,?) "
            "ON CONFLICT(storage_key) DO UPDATE SET data=excluded.data",
            (self._storage_key(key), encoded)
        )

    async def get_data(self, key):
        row = self.connection.execute(
            "SELECT data FROM fsm_storage WHERE storage_key=?", (self._storage_key(key),)
        ).fetchone()
        if not row or not row[0]:
            return {}
        try:
            value = json.loads(row[0])
            return value if isinstance(value, dict) else {}
        except (TypeError, json.JSONDecodeError):
            log.exception("Повреждены данные FSM для ключа %s", self._storage_key(key))
            return {}

    async def close(self):
        if self.connection is not None:
            self.connection.close()
            self.connection = None


fsm_storage = SQLiteFSMStorage(DB_PATH)
