class PunishmentMiddleware(BaseMiddleware):
    async def __call__(self, handler, event, data):
        if isinstance(event, Message) and getattr(event, "successful_payment", None):
            return await handler(event, data)  # оплаченный заказ нельзя терять из-за бана или заключения
        user = getattr(event, "from_user", None)
        if user and user.id not in ADMIN_IDS:
            # Срок временной блокировки проверяется до чтения флага players.banned.
            # Это также снимает бан при первом действии игрока после истечения срока.
            try:
                expire_temporary_bans(user.id)
            except TransactionConflict:
                log.debug("Проверка временного бана отложена: база занята другой операцией")
            except Exception:
                log.exception("Не удалось проверить срок блокировки пользователя %s", user.id)
            player = db.execute(
                "SELECT banned FROM players WHERE user_id = ?",
                (user.id,)
            ).fetchone()
            if player and player["banned"]:
                if isinstance(event, Message):
                    await event.answer("⛔ Твой аккаунт заблокирован. Обратись к администрации.")
                elif isinstance(event, CallbackQuery):
                    await event.answer("⛔ Аккаунт заблокирован.", show_alert=True)
                return

            active_jail = refresh_jail_state(user.id)
            if active_jail:
                is_parole_command = bool(isinstance(event, Message) and event.text and event.text.split(maxsplit=1)[0].split("@")[0] == "/parole")
                if not is_parole_command:
                    notice = "🚔 Ты находишься в игровом заключении. Дождись окончания срока или подай заявление на УДО командой /parole причина."
                    if isinstance(event, Message):
                        await event.answer(notice)
                    elif isinstance(event, CallbackQuery):
                        await event.answer(notice, show_alert=True)
                    return
        if user:
            try:
                db.execute(
                    "INSERT INTO activity(user_id,last_active) VALUES(?,?) "
                    "ON CONFLICT(user_id) DO UPDATE SET last_active=excluded.last_active",
                    (int(user.id), datetime.now().isoformat(timespec="seconds"))
                )
                db.commit()
            except Exception:
                log.debug("Не удалось обновить активность пользователя %s", user.id, exc_info=True)
        return await handler(event, data)


dp.message.outer_middleware(PunishmentMiddleware())
dp.callback_query.outer_middleware(PunishmentMiddleware())


