try:
    db.execute("BEGIN IMMEDIATE")
    _seen_game_ids = set()
    _next_game_id = 1
    for _game_row in db.execute("SELECT user_id, game_id FROM players ORDER BY user_id").fetchall():
        _current_game_id = _game_row["game_id"]
        try:
            _current_game_id = int(_current_game_id) if _current_game_id is not None else None
        except (TypeError, ValueError):
            _current_game_id = None
        if _current_game_id is not None and _current_game_id > 0 and _current_game_id not in _seen_game_ids:
            _seen_game_ids.add(_current_game_id)
            _next_game_id = max(_next_game_id, _current_game_id + 1)
        else:
            while _next_game_id in _seen_game_ids:
                _next_game_id += 1
            db.execute("UPDATE players SET game_id=? WHERE user_id=?", (_next_game_id, _game_row["user_id"]))
            _seen_game_ids.add(_next_game_id)
            _next_game_id += 1
    db.execute("CREATE UNIQUE INDEX IF NOT EXISTS idx_players_game_id ON players(game_id)")
    db.commit()
except Exception:
    if db.in_transaction:
        db.rollback()
    log.exception("Не удалось выполнить миграцию игровых ID")
    raise RuntimeError("RPM WEST остановлен: не удалось безопасно назначить уникальные игровые ID.")
