def faction_entry_fee_range(info):
    """Возвращает допустимый диапазон платы за вступление во фракцию."""
    minimum = max(0, int(info.get("price", 0) or 0))
    maximum = max(minimum, int(info.get("price_max", minimum) or minimum))
    return minimum, maximum


def new_faction_entry_fee(info):
    """Выбирает точную плату для заявки; сумма сохраняется и не меняется при решении."""
    minimum, maximum = faction_entry_fee_range(info)
    return random.randint(minimum, maximum) if maximum > minimum else minimum


def faction_entry_fee_label(info):
    minimum, maximum = faction_entry_fee_range(info)
    if minimum == maximum:
        return f"${minimum:,}"
    return f"${minimum:,}–${maximum:,}"


