# NPC roster persistence and promotion-request queue.
db.executescript("""
CREATE TABLE IF NOT EXISTS faction_npcs (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    faction TEXT NOT NULL,
    name TEXT NOT NULL,
    rank TEXT NOT NULL,
    active INTEGER NOT NULL DEFAULT 1,
    last_activity_at TEXT DEFAULT '',
    last_promotion_at TEXT DEFAULT '',
    UNIQUE(faction, name)
);
CREATE TABLE IF NOT EXISTS faction_npc_requests (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    npc_id INTEGER NOT NULL,
    faction TEXT NOT NULL,
    old_rank TEXT NOT NULL,
    requested_rank TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'Ожидает решения',
    created_at TEXT NOT NULL,
    decided_at TEXT DEFAULT '',
    decided_by INTEGER DEFAULT 0
);
""")
# Individual asset slots and document registry for every NPC.
add_column_if_missing("faction_npcs", "photo_file", "TEXT DEFAULT ''")
add_column_if_missing("faction_npcs", "skin_file", "TEXT DEFAULT ''")
add_column_if_missing("faction_npcs", "passport_valid", "INTEGER NOT NULL DEFAULT 1")
add_column_if_missing("faction_npcs", "medcard_valid", "INTEGER NOT NULL DEFAULT 1")
db.execute("UPDATE faction_npcs SET photo_file='npc_photos/' || id || '.png' WHERE COALESCE(photo_file,'')=''")
db.execute("UPDATE faction_npcs SET skin_file='npc_skins/' || id || '.png' WHERE COALESCE(skin_file,'')=''")
db.commit()
# Safe rank-name migration: preserve existing players, membership history and NPC roster.
_RANK_RENAMES = {
    ("The Crips", "Старший"): "Старший участник",
    ("The Crips", "Заместитель лидера"): "Гангстер",
    ("The Crips", "Капитан района"): "Гангстер",
    ("The Crips", "OG"): "Главарь",
    ("The Crips", "Лидер"): "Главарь",
    ("Русская мафия", "Боец"): "Проверенный",
    ("Русская мафия", "Авторитет"): "Сборщик",
    ("Русская мафия", "Капо"): "Бригадир",
    ("Русская мафия", "Консильери"): "Правая рука",
    ("Русская мафия", "Дон"): "Крёстный отец",
    ("Русская мафия", "Заместитель"): "Правая рука",
    ("Русская мафия", "Лидер"): "Крёстный отец",
    ("Бар", "Работник"): "Грузчик",
    ("Бар", "Работник зала"): "Грузчик",
    ("Бар", "Старший бармен"): "Змей",
    ("Бар", "Администратор"): "Старший смены",
    ("Бар", "Менеджер"): "Администратор",
    ("Бар", "Заместитель"): "Заместитель владельца",
}
for (_faction_name, _old_rank), _new_rank in _RANK_RENAMES.items():
    db.execute("UPDATE players SET rank=? WHERE faction=? AND rank=?", (_new_rank, _faction_name, _old_rank))
    db.execute("UPDATE faction_membership SET rank=? WHERE faction=? AND rank=?", (_new_rank, _faction_name, _old_rank))
    db.execute("UPDATE faction_npcs SET rank=? WHERE faction=? AND rank=?", (_new_rank, _faction_name, _old_rank))
db.commit()
# Disable obsolete city-hall NPCs so only the user-provided roster remains active.
_cityhall_names = [name for names in FACTION_NPC_ROSTER.get("Мэрия", {}).values() for name in names]
if _cityhall_names:
    db.execute("UPDATE faction_npcs SET active=0 WHERE faction=?", ("Мэрия",))
for _npc_faction, _rank_map in FACTION_NPC_ROSTER.items():
    _valid_ranks = UNIVERSITY_RANKS if _npc_faction == "Университет" else FACTIONS.get(_npc_faction, {}).get("ranks", [])
    for _npc_rank, _npc_names in _rank_map.items():
        if _npc_rank not in _valid_ranks:
            continue
        for _npc_name in _npc_names:
            db.execute(
                """INSERT INTO faction_npcs(faction,name,rank,active)
                   VALUES(?,?,?,1)
                   ON CONFLICT(faction,name) DO UPDATE SET
                       rank=excluded.rank,
                       active=1""",
                (_npc_faction, _npc_name, _npc_rank)
            )
db.commit()


def get_active_faction_npcs(faction):
    """Возвращает NPC фракции; при рассинхронизации восстанавливает штатный состав из roster."""
    faction_name = str(faction or "").strip()
    rows = db.execute(
        "SELECT * FROM faction_npcs WHERE TRIM(faction)=? AND active=1 ORDER BY name",
        (faction_name,)
    ).fetchall()
    if rows:
        return rows

    # Восстанавливаем только NPC из заданного штатного состава этой фракции.
    roster = FACTION_NPC_ROSTER.get(faction_name, {})
    valid_ranks = UNIVERSITY_RANKS if faction_name == "Университет" else FACTIONS.get(faction_name, {}).get("ranks", [])
    for rank, names in roster.items():
        if rank not in valid_ranks:
            continue
        for npc_name in names:
            db.execute(
                """INSERT INTO faction_npcs(faction,name,rank,active) VALUES(?,?,?,1)
                   ON CONFLICT(faction,name) DO UPDATE SET rank=excluded.rank, active=1""",
                (faction_name, npc_name, rank)
            )
    db.commit()
    return db.execute(
        "SELECT * FROM faction_npcs WHERE TRIM(faction)=? AND active=1 ORDER BY name",
        (faction_name,)
    ).fetchall()


# Отдельная память каждой пары «игрок — NPC» и выбранный собеседник.
# Таблицы не меняют игровые должности, ранги, зарплаты или фракции.
db.executescript("""
CREATE TABLE IF NOT EXISTS npc_ai_dialogue (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    npc_id INTEGER NOT NULL,
    role TEXT NOT NULL CHECK(role IN ('user','assistant')),
    content TEXT NOT NULL,
    created_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_npc_ai_dialogue_pair
    ON npc_ai_dialogue(user_id, npc_id, id);
CREATE TABLE IF NOT EXISTS npc_ai_memory (
    user_id INTEGER NOT NULL,
    npc_id INTEGER NOT NULL,
    summary TEXT NOT NULL DEFAULT '',
    updated_at TEXT NOT NULL,
    source_dialogue_id INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY(user_id, npc_id)
);
CREATE INDEX IF NOT EXISTS idx_npc_ai_memory_updated ON npc_ai_memory(updated_at);
CREATE TABLE IF NOT EXISTS npc_ai_active_chat (
    user_id INTEGER PRIMARY KEY,
    npc_id INTEGER NOT NULL,
    started_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS npc_ai_documents (
    user_id INTEGER NOT NULL,
    npc_id INTEGER NOT NULL,
    passport_json TEXT DEFAULT '',
    serviceid_json TEXT DEFAULT '',
    updated_at TEXT NOT NULL,
    PRIMARY KEY(user_id, npc_id)
);
CREATE TABLE IF NOT EXISTS faction_inspections (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    faction TEXT NOT NULL,
    organizer_id INTEGER NOT NULL,
    scheduled_at TEXT NOT NULL,
    location TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'Запланирована',
    created_at TEXT NOT NULL,
    completed_at TEXT DEFAULT ''
);
CREATE TABLE IF NOT EXISTS faction_inspection_people (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    inspection_id INTEGER NOT NULL,
    user_id INTEGER NOT NULL,
    passport_status TEXT NOT NULL DEFAULT 'Ожидает',
    medcard_status TEXT NOT NULL DEFAULT 'Ожидает',
    checked_by INTEGER DEFAULT 0,
    checked_at TEXT DEFAULT '',
    UNIQUE(inspection_id,user_id)
);
CREATE INDEX IF NOT EXISTS idx_faction_inspections_status ON faction_inspections(status,scheduled_at);
""")
add_column_if_missing("faction_inspection_people", "npc_id", "INTEGER NOT NULL DEFAULT 0")
db.execute("CREATE INDEX IF NOT EXISTS idx_inspection_people_npc ON faction_inspection_people(inspection_id,npc_id)")
db.commit()

# Постоянный автономный распорядок NPC и журнал событий игрового мира.
# Записи не меняют должности/экономику игроков и не требуют присутствия игроков в локации.
db.executescript("""
CREATE TABLE IF NOT EXISTS npc_autonomy_schedule (
    npc_id INTEGER PRIMARY KEY,
    weekday_plan TEXT NOT NULL DEFAULT '{}',
    updated_at TEXT NOT NULL DEFAULT ''
);
CREATE TABLE IF NOT EXISTS npc_autonomy_events (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    npc_id INTEGER NOT NULL DEFAULT 0,
    faction TEXT NOT NULL DEFAULT '',
    event_type TEXT NOT NULL,
    title TEXT NOT NULL,
    details TEXT NOT NULL DEFAULT '',
    location TEXT NOT NULL DEFAULT '',
    event_slot TEXT NOT NULL,
    created_at TEXT NOT NULL,
    UNIQUE(npc_id,event_slot,event_type,faction)
);
CREATE INDEX IF NOT EXISTS idx_npc_autonomy_events_recent
    ON npc_autonomy_events(created_at DESC,id DESC);
CREATE INDEX IF NOT EXISTS idx_npc_autonomy_events_faction
    ON npc_autonomy_events(faction,created_at DESC);
""")
# Расписания формируются по роли, а не случайным образом при каждом запуске.
for _schedule_npc in db.execute("SELECT id,faction,rank FROM faction_npcs WHERE active=1").fetchall():
    _plan = {
        "06-09": "Подготовка к смене и проверка рабочих материалов",
        "09-12": "Рабочая смена и выполнение должностных обязанностей",
        "12-14": "Перерыв и обмен текущими докладами",
        "14-18": "Рабочая смена, поручения и взаимодействие с коллегами",
        "18-21": "Передача итогов смены и служебные записи",
        "21-06": "Отдых вне рабочего места; экстренный вызов возможен по RP"
    }
    if _schedule_npc["faction"] == "Университет":
        _plan["09-12"] = "Подготовка и проведение учебных занятий"
        _plan["14-18"] = "Консультации студентов и проверка учебных работ"
    elif _schedule_npc["rank"] in ("Главарь", "Гангстер", "Крёстный отец", "Правая рука", "Бригадир", "Декан", "Владелец", "Заместитель владельца", "Управляющий", "Шеф", "Директор", "Генерал", "Командир"):
        _plan["09-12"] = "Рассмотрение докладов и распределение поручений"
        _plan["14-18"] = "Совещания, контроль подразделений и кадровые вопросы"
    elif _schedule_npc["faction"] in ("Больница",):
        _plan["09-12"] = "Приём пациентов и медицинские RP-процедуры"
        _plan["14-18"] = "Лечение, дежурство и оформление медицинских записей"
    db.execute(
        "INSERT OR IGNORE INTO npc_autonomy_schedule(npc_id,weekday_plan,updated_at) VALUES(?,?,?)",
        (int(_schedule_npc["id"]), json.dumps(_plan, ensure_ascii=False), datetime.now().isoformat(timespec="seconds"))
    )
db.commit()


