def _reload_university_quizzes():
    """Seed default questions once, then load the active admin-managed bank."""
    for _subject, _questions in QUIZZES.items():
        _count = db.execute("SELECT COUNT(*) FROM university_exam_questions WHERE subject=? AND active=1", (_subject,)).fetchone()[0]
        if not _count:
            for _question, _options, _correct in _questions:
                db.execute(
                    "INSERT INTO university_exam_questions(subject,question,options_json,correct_index,active,created_by,created_at) VALUES(?,?,?,?,1,0,?)",
                    (_subject, _question, json.dumps(_options, ensure_ascii=False), int(_correct), datetime.now().isoformat(timespec="seconds"))
                )
    db.commit()
    _loaded = {subject: [] for subject in SUBJECTS}
    for _row in db.execute("SELECT subject,question,options_json,correct_index FROM university_exam_questions WHERE active=1 ORDER BY id").fetchall():
        try:
            _options = json.loads(_row["options_json"])
            _correct = int(_row["correct_index"])
            if _row["subject"] in _loaded and isinstance(_options, list) and len(_options) == 4 and 0 <= _correct < 4:
                _loaded[_row["subject"]].append((_row["question"], _options, _correct))
        except (ValueError, TypeError, json.JSONDecodeError):
            log.exception("Пропущен повреждённый вопрос университета ID=%s", _row["id"] if "id" in _row.keys() else "?")
    for _subject in SUBJECTS:
        if _loaded[_subject]:
            QUIZZES[_subject] = _loaded[_subject]


_reload_university_quizzes()


@dp.message(Command("uni_exam_admin"))
async def university_exam_admin_command(message: Message):
    if not is_admin(message.from_user.id):
        await message.answer("Управление банком экзамена доступно только администрации.")
        return
    raw = (message.text or "").partition(" ")[2].strip()
    if not raw or raw.lower() == "list":
        rows = db.execute(
            "SELECT id,subject,question FROM university_exam_questions WHERE active=1 ORDER BY subject,id LIMIT 60"
        ).fetchall()
        counts = db.execute("SELECT subject,COUNT(*) AS n FROM university_exam_questions WHERE active=1 GROUP BY subject ORDER BY subject").fetchall()
        summary = "\n".join(f"• {row['subject']}: {row['n']} вопросов" for row in counts)
        examples = "\n".join(f"#{row['id']} · {row['subject']} — {row['question'][:90]}" for row in rows)
        await message.answer(
            "🎓 БАНК ЕДИНОГО ЭКЗАМЕНА\n" + (summary or "Нет активных вопросов.") +
            "\n\n" + (examples or "") +
            "\n\nДобавить: /uni_exam_admin add|Предмет|Вопрос|Вариант 1|Вариант 2|Вариант 3|Вариант 4|Номер правильного (1-4)" +
            "\nУдалить: /uni_exam_admin remove|ID"
        )
        return
    parts = raw.split("|")
    action = parts[0].strip().lower()
    if action == "add":
        if len(parts) != 8:
            await message.answer("Формат: /uni_exam_admin add|Предмет|Вопрос|Вариант 1|Вариант 2|Вариант 3|Вариант 4|Правильный вариант 1-4")
            return
        subject, question = parts[1].strip(), parts[2].strip()
        options = [part.strip() for part in parts[3:7]]
        try:
            correct = int(parts[7].strip()) - 1
        except ValueError:
            correct = -1
        if subject not in SUBJECTS or len(question) < 10 or len(question) > 350 or any(not option or len(option) > 180 for option in options) or not 0 <= correct < 4:
            await message.answer("Проверь предмет, длину вопроса, четыре варианта и номер правильного ответа от 1 до 4.")
            return
        try:
            begin_immediate()
            if not claim_operation("university_exam_question_add"):
                db.rollback(); await message.answer("Этот вопрос уже добавлен."); return
            cur = db.execute(
                "INSERT INTO university_exam_questions(subject,question,options_json,correct_index,active,created_by,created_at) VALUES(?,?,?,?,1,?,?)",
                (subject, question, json.dumps(options, ensure_ascii=False), correct, message.from_user.id, now_text())
            )
            question_id = cur.lastrowid
            db.commit()
            _reload_university_quizzes()
        except sqlite3.Error:
            if db.in_transaction: db.rollback()
            log.exception("Не удалось добавить вопрос университета")
            await message.answer("Не удалось сохранить вопрос.")
            return
        await message.answer(f"Вопрос №{question_id} добавлен в предмет «{subject}».")
        return
    if action == "remove" and len(parts) == 2 and parts[1].strip().isdigit():
        question_id = int(parts[1].strip())
        try:
            begin_immediate()
            if not claim_operation("university_exam_question_remove"):
                db.rollback(); await message.answer("Эта операция уже обработана."); return
            row = db.execute("SELECT subject FROM university_exam_questions WHERE id=? AND active=1", (question_id,)).fetchone()
            if not row:
                db.rollback(); await message.answer("Активный вопрос с таким ID не найден."); return
            remaining = db.execute("SELECT COUNT(*) FROM university_exam_questions WHERE subject=? AND active=1", (row["subject"],)).fetchone()[0]
            if remaining <= 1:
                db.rollback(); await message.answer("Нельзя удалить последний вопрос предмета: единый экзамен должен охватывать все семь предметов."); return
            db.execute("UPDATE university_exam_questions SET active=0 WHERE id=?", (question_id,))
            db.commit()
            _reload_university_quizzes()
        except sqlite3.Error:
            if db.in_transaction: db.rollback()
            log.exception("Не удалось удалить вопрос университета")
            await message.answer("Не удалось удалить вопрос.")
            return
        await message.answer(f"Вопрос №{question_id} отключён.")
        return
    await message.answer("Доступно: /uni_exam_admin list, add|... или remove|ID.")


