# 12. ВСПОМОГАТЕЛЬНЫЕ ФУНКЦИИ
# =========================================================

def now_text():
    return datetime.now().isoformat(timespec="seconds")


def travel_duration_seconds(origin, destination, mode):
    """Игровое время поездки: пешком заметно дольше, чем на автомобиле."""
    try:
        distance = abs(LOCATIONS.index(origin) - LOCATIONS.index(destination))
    except ValueError:
        distance = 3
    distance = max(1, distance)
    if mode == "vehicle":
        return 12 + distance * 6
    return 45 + distance * 20


def active_player_travel(user_id):
    return db.execute(
        "SELECT * FROM player_travel WHERE user_id=? AND status='В пути'",
        (user_id,)
    ).fetchone()


def travel_remaining_seconds(travel):
    try:
        return max(0, int((datetime.fromisoformat(travel["arrives_at"]) - datetime.now()).total_seconds()))
    except (TypeError, ValueError):
        return 0


def begin_player_travel(user_id, destination, mode, vehicle_id=0, vehicle_name=""):
    """Атомарно создаёт поездку и, если нужно, списывает ресурс автомобиля."""
    if mode not in ("walk", "vehicle") or destination not in LOCATIONS:
        return None, "Некорректный маршрут."
    try:
        begin_immediate()
        current = db.execute("SELECT location FROM players WHERE user_id=?", (user_id,)).fetchone()
        if not current:
            db.rollback()
            return None, "Персонаж не найден."
        if current["location"] == destination:
            db.rollback()
            return None, "Ты уже находишься в этой локации."
        active = db.execute("SELECT destination,arrives_at FROM player_travel WHERE user_id=? AND status='В пути'", (user_id,)).fetchone()
        if active:
            db.rollback()
            return None, f"Ты уже в пути к локации «{active['destination']}». Дождись прибытия."
        if mode == "vehicle":
            car = db.execute("SELECT * FROM vehicles WHERE id=? AND user_id=?", (vehicle_id, user_id)).fetchone()
            if not car or int(car["fuel"] or 0) < 5 or int(car["condition"] or 0) <= 0:
                db.rollback()
                return None, "Автомобиль не готов к поездке. Проверь топливо и состояние."
            changed = db.execute(
                "UPDATE vehicles SET fuel=fuel-5,condition=MAX(0,condition-1) WHERE id=? AND user_id=? AND fuel>=5 AND condition>0",
                (vehicle_id, user_id)
            )
            if changed.rowcount != 1:
                db.rollback()
                return None, "Не удалось подготовить автомобиль к поездке."
            vehicle_name = car["vehicle_name"]
        seconds = travel_duration_seconds(current["location"], destination, mode)
        started = datetime.now()
        arrives = started + timedelta(seconds=seconds)
        db.execute(
            "INSERT INTO player_travel(user_id,origin,destination,travel_mode,vehicle_id,vehicle_name,started_at,arrives_at,status) "
            "VALUES(?,?,?,?,?,?,?,?, 'В пути') "
            "ON CONFLICT(user_id) DO UPDATE SET origin=excluded.origin,destination=excluded.destination,travel_mode=excluded.travel_mode,vehicle_id=excluded.vehicle_id,vehicle_name=excluded.vehicle_name,started_at=excluded.started_at,arrives_at=excluded.arrives_at,status='В пути'",
            (user_id, current["location"], destination, mode, vehicle_id, vehicle_name, started.isoformat(timespec="seconds"), arrives.isoformat(timespec="seconds"))
        )
        if mode == "vehicle":
            db.execute(
                "INSERT INTO vehicle_service_log(vehicle_id,user_id,service_type,amount,created_at) VALUES(?,?, 'trip',0,?)",
                (vehicle_id, user_id, now_text())
            )
        db.commit()
        return {"origin": current["location"], "destination": destination, "mode": mode, "seconds": seconds, "arrives_at": arrives.isoformat(timespec="seconds"), "vehicle_name": vehicle_name}, None
    except sqlite3.Error:
        if db.in_transaction:
            db.rollback()
        log.exception("Не удалось начать перемещение персонажа %s", user_id)
        return None, "Не удалось начать перемещение. Попробуй позже."


async def travel_completion_loop():
    """Завершает сохранённые поездки; незавершённые поездки переживают перезапуск бота."""
    while True:
        try:
            due = db.execute(
                "SELECT * FROM player_travel WHERE status='В пути' AND arrives_at<=? ORDER BY arrives_at LIMIT 100",
                (now_text(),)
            ).fetchall()
            completed = []
            for travel in due:
                try:
                    begin_immediate()
                    changed = db.execute(
                        "UPDATE player_travel SET status='Прибыл' WHERE user_id=? AND status='В пути' AND arrives_at<=?",
                        (travel["user_id"], now_text())
                    )
                    if changed.rowcount == 1:
                        db.execute("UPDATE players SET location=? WHERE user_id=?", (travel["destination"], travel["user_id"]))
                        if "npc_ai_active_chat" in _existing_tables():
                            db.execute("DELETE FROM npc_ai_active_chat WHERE user_id=?", (travel["user_id"],))
                        db.commit()
                        completed.append(dict(travel))
                    else:
                        db.rollback()
                except sqlite3.Error:
                    if db.in_transaction:
                        db.rollback()
                    log.exception("Не удалось завершить поездку пользователя %s", travel["user_id"])
            for travel in completed:
                uid = int(travel["user_id"])
                if bot is None:
                    continue
                if travel["travel_mode"] == "vehicle":
                    text_value = f"🚘 Ты приехал в «{travel['destination']}» на автомобиле {travel['vehicle_name']}."
                else:
                    text_value = f"🚶 Ты дошёл до локации «{travel['destination']}»."
                try:
                    sent = await bot.send_message(uid, text_value)
                    if travel["destination"] in ("Мэрия", "Больница", "Университет", "Офис СМИ", "Военная база", "Участок ЦПД", "Офис ФБР", "Офис Следственного комитета"):
                        await show_location_reception(sent, uid, travel["destination"])
                    else:
                        await sent.answer(f"📍 Ты осматриваешься в локации «{travel['destination']}». Здесь можно поговорить с находящимися рядом NPC.", reply_markup=reception_keyboard(travel["destination"]))
                except Exception:
                    log.debug("Не удалось уведомить пользователя %s о прибытии", uid, exc_info=True)
        except Exception:
            log.exception("Ошибка фоновой обработки поездок")
        await asyncio.sleep(5)


def get_player(user_id):
    return db.execute(
        "SELECT * FROM players WHERE user_id = ?",
        (user_id,)
    ).fetchone()


def player_display_name(player, fallback="Персонаж"):
    """Единый публичный формат RP-имени: Имя Фамилия [игровой ID]."""
    if not player:
        return fallback
    rp_name = str(player["name"] or "").strip()
    if not rp_name or rp_name in ("Нет", "Не указано"):
        rp_name = fallback
    try:
        game_id = int(player["game_id"])
    except (KeyError, IndexError, TypeError, ValueError):
        game_id = 0
    # В старых версиях ID иногда приписывался к имени через пробел.
    # Числовой суффикс убираем только если он совпадает с постоянным game_id.
    if game_id > 0:
        rp_name = re.sub(rf"\s+{game_id}$", "", rp_name).strip()
        return f"{rp_name} [{game_id}]"
    return rp_name


def gender_form(player, masculine, feminine):
    """Возвращает нужную русскую форму по полу персонажа; для старых записей — мужскую."""
    try:
        return feminine if str(player["gender"] or "").strip() == "Женский" else masculine
    except (KeyError, IndexError, TypeError):
        return masculine


def get_player_by_game_id(game_id):
    try:
        game_id = int(game_id)
    except (TypeError, ValueError):
        return None
    if game_id <= 0:
        return None
    return db.execute("SELECT * FROM players WHERE game_id=?", (game_id,)).fetchone()


def create_player(user_id):
    """Создаёт персонажа и связанные записи атомарно, не фиксируя чужую транзакцию."""
    owns_transaction = not db.in_transaction
    try:
        if owns_transaction:
            db.execute("BEGIN IMMEDIATE")
        db.execute(
            "INSERT OR IGNORE INTO players(user_id, labor_book) VALUES (?, 1)",
            (user_id,)
        )
        current = db.execute("SELECT game_id FROM players WHERE user_id=?", (user_id,)).fetchone()
        if current and (current["game_id"] is None or int(current["game_id"] or 0) <= 0):
            next_game_id = int(db.execute(
                "SELECT COALESCE(MAX(game_id),0)+1 FROM players WHERE game_id IS NOT NULL"
            ).fetchone()[0])
            db.execute(
                "UPDATE players SET game_id=? WHERE user_id=? AND (game_id IS NULL OR game_id<=0)",
                (next_game_id, user_id)
            )

        db.execute("INSERT OR IGNORE INTO activity(user_id) VALUES (?)", (user_id,))
        db.execute("INSERT OR IGNORE INTO documents(user_id) VALUES (?)", (user_id,))
        db.execute("INSERT OR IGNORE INTO phone_settings(user_id) VALUES (?)", (user_id,))
        if owns_transaction:
            db.commit()
    except Exception:
        if owns_transaction and db.in_transaction:
            db.rollback()
        log.exception("Не удалось создать персонажа/связанные записи для нового игрового аккаунта")
        raise


def touch(user_id):
    create_player(user_id)

    current = datetime.now()
    row = db.execute(
        "SELECT last_active FROM activity WHERE user_id = ?",
        (user_id,)
    ).fetchone()

    if row and row["last_active"]:
        try:
            previous = datetime.fromisoformat(row["last_active"])
            seconds = max(
                0,
                min((current - previous).total_seconds(), 3600)
            )

            days = int(seconds // 60)

            if days > 0:
                player = get_player(user_id)

                total = (
                    player["rp_year"] * 360
                    + (player["rp_month"] - 1) * 30
                    + player["rp_day"] - 1
                    + days
                )

                year = total // 360
                remaining = total % 360
                month = remaining // 30 + 1
                day = remaining % 30 + 1

                db.execute(
                    """
                    UPDATE players
                    SET rp_year = ?, rp_month = ?, rp_day = ?
                    WHERE user_id = ?
                    """,
                    (year, month, day, user_id)
                )
        except (ValueError, TypeError):
            pass

    db.execute(
        "UPDATE activity SET last_active = ? WHERE user_id = ?",
        (current.isoformat(timespec="seconds"), user_id)
    )

    db.commit()


def change_balance(user_id, amount):
    create_player(user_id)

    try:
        begin_immediate()

        cursor = db.execute(
            """
            UPDATE players
            SET balance = balance + ?
            WHERE user_id = ?
            AND balance + ? >= 0
            AND balance + ? <= ?
            """,
            (amount, user_id, amount, amount, MAX_BALANCE)
        )

        if cursor.rowcount != 1:
            db.rollback()
            return False

        db.commit()
        return True

    except sqlite3.Error:
        db.rollback()
        log.exception("Ошибка изменения баланса")
        return False


def set_flag(user_id, field, value):
    allowed = {
        "passport",
        "medcard",
        "labor_book",
        "banned"
    }

    if field not in allowed:
        return False

    create_player(user_id)

    db.execute(
        f"UPDATE players SET {field} = ? WHERE user_id = ?",
        (value, user_id)
    )

    db.commit()
    return True


def valid_rp_name(name):
    if not name:
        return False

    parts = name.strip().split()

    if len(parts) != 2:
        return False

    pattern = r"^[А-ЯЁ][а-яё]{1,20}$"

    return all(re.fullmatch(pattern, part) for part in parts)


def expire_housing(user_id):
    player = get_player(user_id)

    if not player or not player["housing_until"]:
        return

    try:
        until = datetime.fromisoformat(player["housing_until"])

        if datetime.now() >= until:
            db.execute(
                """
                UPDATE players
                SET housing = 'Нет', housing_until = ''
                WHERE user_id = ?
                """,
                (user_id,)
            )
            db.commit()

    except ValueError:
        pass


def education_points(user_id, subject):
    row = db.execute(
        """
        SELECT points FROM lessons
        WHERE user_id = ? AND subject = ?
        """,
        (user_id, subject)
    ).fetchone()

    return row["points"] if row else 0


def subject_passed(user_id, subject):
    row = db.execute(
        """
        SELECT passed FROM university_tests
        WHERE user_id = ? AND subject = ?
        ORDER BY id DESC LIMIT 1
        """,
        (user_id, subject)
    ).fetchone()

    return bool(row and row["passed"])


def all_subjects_passed(user_id):
    return all(
        subject_passed(user_id, subject)
        for subject in SUBJECTS
    )


def university_employee(user_id):
    player = get_player(user_id)

    if not player:
        return False

    return (
        player["faction"] == "Университет"
        and player["rank"] in UNIVERSITY_RANKS
    )


def employee_rank(user_id):
    player = get_player(user_id)

    if not player:
        return None

    if player["faction"] != "Университет":
        return None

    if player["rank"] not in UNIVERSITY_RANKS:
        return None

    return player["rank"]


def is_student(user_id):
    row = db.execute(
        """
        SELECT active FROM university_students
        WHERE user_id = ?
        """,
        (user_id,)
    ).fetchone()

    return bool(row and row["active"])


def has_university_documents(user_id):
    player = get_player(user_id)

    if not player:
        return False

    return bool(
        player["passport"]
        and player["medcard"]
        and player["labor_book"]
    )


def university_access(user_id):
    player = get_player(user_id)

    if not player:
        return False

    return (
        player["location"] == "Университет"
        and has_university_documents(user_id)
        and is_student(user_id)
    )


def grade_from_score(score):
    if score == 5:
        return 5

    if score == 4:
        return 4

    if score == 3:
        return 3

    return 2


def shuffle_question(question):
    text_value, answers, correct_index = question

    combined = list(enumerate(answers))
    random.shuffle(combined)

    shuffled_answers = [
        answer for _, answer in combined
    ]

    new_correct_index = next(
        index
        for index, (old_index, _) in enumerate(combined)
        if old_index == correct_index
    )

    return (
        text_value,
        shuffled_answers,
        new_correct_index
    )


