def expire_temporary_bans(user_id=None):
    """Снимает истёкшие временные BAN, не затрагивая постоянные и legacy-блокировки."""
    now = datetime.now()
    params = [now.isoformat()]
    query = "SELECT id,user_id,expires_at FROM player_punishments WHERE punishment_type='BAN' AND active=1 AND COALESCE(expires_at,'')!='' AND expires_at<=?"
    if user_id is not None:
        query += " AND user_id=?"
        params.append(int(user_id))
    # Не берём write-lock для обычных сообщений, когда у игрока нет временного бана.
    if not db.execute(query, params).fetchone():
        return 0
    try:
        begin_immediate()
        rows = db.execute(query, params).fetchall()
        affected_users = set()
        for row in rows:
            try:
                expires = datetime.fromisoformat(row["expires_at"])
            except (TypeError, ValueError):
                # Некорректная дата не должна приводить к досрочному снятию бана.
                continue
            if expires <= now:
                changed = db.execute(
                    "UPDATE player_punishments SET active=0 WHERE id=? AND active=1 AND punishment_type='BAN'",
                    (row["id"],)
                )
                if changed.rowcount:
                    affected_users.add(int(row["user_id"]))
        for uid in affected_users:
            still_banned = db.execute(
                "SELECT 1 FROM player_punishments WHERE user_id=? AND punishment_type='BAN' AND active=1 LIMIT 1",
                (uid,)
            ).fetchone()
            if not still_banned:
                # Меняем флаг только если реально истёкшая запись BAN была найдена.
                db.execute("UPDATE players SET banned=0 WHERE user_id=?", (uid,))
        db.commit()
        return len(affected_users)
    except TransactionConflict:
        # Чужую транзакцию общего SQLite-соединения откатывать нельзя.
        raise
    except sqlite3.Error:
        if db.in_transaction:
            db.rollback()
        log.exception("Не удалось автоматически снять истёкшие временные блокировки")
        raise


async def ban_expiry_loop():
    """Фоновая проверка временных блокировок; интервал — 30 секунд."""
    while True:
        await asyncio.sleep(30)
        try:
            expire_temporary_bans()
        except TransactionConflict:
            log.debug("Фоновая проверка временных банов отложена: база занята")
        except Exception:
            log.exception("Ошибка фоновой проверки временных блокировок")


def add_punishment(user_id: int, kind: str, reason: str,
                   admin_id: int, minutes: int = 0):
    """Атомарно применяет наказание, законность и запись аудита."""
    expires_at = ""
    if minutes > 0:
        expires_at = (datetime.now() + timedelta(minutes=minutes)).isoformat(timespec="seconds")
    try:
        begin_immediate()
        if not claim_operation(f"punishment_{kind.upper()}"):
            db.rollback()
            return False
        db.execute(
            """INSERT INTO player_punishments(
                user_id,punishment_type,reason,expires_at,active,created_by,created_at
            ) VALUES(?,?,?,?,1,?,?)""",
            (user_id, kind.upper(), reason, expires_at, admin_id, now_text())
        )
        if kind.upper() == "BAN":
            db.execute("UPDATE players SET banned=1 WHERE user_id=?", (user_id,))
        if kind.upper() == "JAIL":
            current = db.execute("SELECT lawfulness FROM players WHERE user_id=?", (user_id,)).fetchone()
            if current:
                after = max(0, int(current["lawfulness"] if current["lawfulness"] is not None else 100) - 10)
                db.execute("UPDATE players SET lawfulness=? WHERE user_id=?", (after, user_id))
                db.execute(
                    "INSERT INTO lawfulness_log(user_id,delta,value_after,reason,created_at) VALUES(?,-10,?,?,?)",
                    (user_id, after, f"Игровое заключение: {reason}", now_text())
                )
        db.execute(
            "INSERT INTO admin_audit(admin_id,target_id,action,details,created_at) VALUES(?,?,?,?,?)",
            (admin_id, user_id, kind.upper(), reason, now_text())
        )
        db.commit()
        return True
    except TransactionConflict:
        # Общее соединение уже занято другой операцией: не откатываем её.
        log.warning("Наказание %s игроку %s отложено: база занята", kind, user_id)
        return False
    except sqlite3.Error:
        if db.in_transaction:
            db.rollback()
        log.exception("Не удалось применить наказание %s игроку %s", kind, user_id)
        return False


