@dp.callback_query(F.data.startswith("faction:"))
async def faction_info_handler(callback: CallbackQuery):
    try:
        index = int(callback.data.split(":")[1])
        faction_name = list(FACTIONS.keys())[index]
    except (ValueError, IndexError):
        await callback.answer("Организация не найдена.", show_alert=True)
        return

    info = FACTIONS[faction_name]
    hiring_rule = db.execute(
        "SELECT * FROM faction_hiring_rules WHERE faction=?", (faction_name,)
    ).fetchone()
    recruitment = db.execute(
        "SELECT is_open FROM faction_recruitment WHERE faction=?", (faction_name,)
    ).fetchone()
    requirements = ["Паспорт"]
    if hiring_rule:
        if hiring_rule["require_medcard"]:
            requirements.append("медицинская карта")
        if hiring_rule["require_labor_book"]:
            requirements.append("трудовая книжка")
        if hiring_rule["require_housing"]:
            requirements.append("собственное жильё")
        if hiring_rule["min_previous_factions"]:
            requirements.append(f"опыт работы: {hiring_rule['min_previous_factions']} предыдущих фракций")
        if hiring_rule["min_previous_days"]:
            requirements.append(f"общий стаж: {hiring_rule['min_previous_days']} дней")
        citizens_allowed = bool(hiring_rule["allow_citizens"])
        transfers_allowed = bool(hiring_rule["allow_transfers"])
    else:
        citizens_allowed = transfers_allowed = True
    recruitment_open = bool(recruitment and recruitment["is_open"])
    recruitment_label = "🟢 Набор открыт" if recruitment_open else "🔴 Набор закрыт"
    admission_modes = []
    if citizens_allowed:
        admission_modes.append("гражданские")
    if transfers_allowed:
        admission_modes.append("переводы")
    admission_text = ", ".join(admission_modes) if admission_modes else "приём временно ограничен"

    text_value = (
        f"🏢 **{faction_name}**\n\n"
        f"{recruitment_label}\n"
        f"Стоимость вступления: {faction_entry_fee_label(info)}\n"
        f"Требование к образованию: {info['education']}\n"
        f"Принимаются: {admission_text}\n\n"
        f"**Обязательные требования:**\n"
        + "\n".join(f"• {item}" for item in requirements)
        + "\n\n**Доступные должности:**\n"
    )

    for rank_index, rank in enumerate(info["ranks"], start=1):
        text_value += f"{rank_index}. {rank}\n"

    keyboard = InlineKeyboardMarkup(
        inline_keyboard=[
            [
                InlineKeyboardButton(
                    text="📋 Подать заявку",
                    callback_data=f"fjoin:{index}"
                )
            ]
        ]
    )

    await callback.answer()
    await callback.message.edit_text(
        text_value,
        parse_mode="Markdown",
        reply_markup=keyboard
    )


def education_meets_requirement(player_education, required):
    levels = {
        "Нет": 0,
        "Общее": 1,
        "Среднее": 1,
        "Профессиональное": 2,
        "Высшее": 3
    }

    return levels.get(player_education, 0) >= levels.get(required, 0)


def faction_missing_entry_requirements(user_id, player, rule):
    """Возвращает недостающие документы и жильё по настройкам конкретной фракции."""
    missing = []
    if not player or not player["passport"]:
        missing.append("паспорт")
    if rule and rule["require_medcard"] and not player["medcard"]:
        missing.append("медицинская карта")
    if rule and rule["require_labor_book"] and not player["labor_book"]:
        missing.append("трудовая книжка")
    if rule and rule["require_housing"]:
        home = db.execute(
            "SELECT 1 FROM property_ownership o JOIN property_catalog c ON c.id=o.property_id "
            "WHERE o.user_id=? AND c.kind IN ('Комната','Трейлер','Квартира','Дом','Апартаменты','Особняк') LIMIT 1",
            (user_id,)
        ).fetchone()
        if not home:
            missing.append("собственное жильё")
    return missing


@dp.callback_query(F.data.startswith("fjoin:"))
async def faction_join_handler(callback: CallbackQuery):
    user_id = callback.from_user.id
    create_player(user_id)
    try:
        index = int(callback.data.split(":")[1])
        faction_name = list(FACTIONS.keys())[index]
    except (ValueError, IndexError):
        await callback.answer("Организация не найдена.", show_alert=True)
        return

    player = get_player(user_id)
    info = FACTIONS[faction_name]
    if player and player["banned"]:
        await callback.answer("Заблокированный персонаж не может подавать заявки.", show_alert=True); return
    if player and player["faction"] == faction_name:
        await callback.answer("Ты уже состоишь в этой организации. Повторное вступление невозможно.", show_alert=True)
        return
    blocked = db.execute("SELECT 1 FROM faction_blacklist WHERE user_id=? AND faction=? AND active=1", (user_id, faction_name)).fetchone()
    if blocked:
        await callback.answer("Ты находишься в чёрном списке этой организации. Повторное вступление запрещено до снятия ЧС руководством.", show_alert=True); return
    rule=db.execute("SELECT * FROM faction_hiring_rules WHERE faction=?",(faction_name,)).fetchone()
    if player["faction"] in ("Нет", "Университет") and rule and not rule["allow_citizens"]:
        await callback.answer("Эта организация сейчас принимает только переводом.",show_alert=True); return
    if player["faction"] in FACTIONS and (not rule or not rule["allow_transfers"]):
        await callback.answer("Организация не принимает переводы из других фракций.",show_alert=True); return
    if player["faction"] not in FACTIONS and player["faction"] not in ("Нет", "Университет", faction_name):
        await callback.answer("У персонажа указана неизвестная организация. Обратись к администрации.",show_alert=True); return
    exp_count,exp_days=_employment_experience(user_id)
    if rule and (exp_count < rule["min_previous_factions"] or exp_days < rule["min_previous_days"]):
        await callback.answer(f"Не хватает опыта работы: требуется {rule['min_previous_factions']} предыдущих фракций и {rule['min_previous_days']} дней стажа.",show_alert=True); return
    missing_requirements = faction_missing_entry_requirements(user_id, player, rule)
    if missing_requirements:
        await callback.answer("Не выполнены требования: " + ", ".join(missing_requirements) + ".", show_alert=True)
        return
    if not education_meets_requirement(player["education"], info["education"]):
        await callback.answer("Недостаточно образования.", show_alert=True)
        return
    entry_fee = new_faction_entry_fee(info)
    if int(player["balance"] or 0) < entry_fee:
        await callback.answer(f"Недостаточно денег. Стоимость этой заявки: ${entry_fee:,}.", show_alert=True)
        return
    busy = db.execute("SELECT faction,status FROM faction_interview_sessions WHERE candidate_id=? AND status IN ('В процессе','Ожидает решения') ORDER BY id DESC LIMIT 1", (user_id,)).fetchone()
    if busy:
        await callback.answer(f"У тебя уже есть активное собеседование в «{busy['faction']}». Сначала заверши его.",show_alert=True); return
    opened = db.execute("SELECT is_open FROM faction_recruitment WHERE faction=?", (faction_name,)).fetchone()
    if not opened or not opened["is_open"]:
        await callback.answer("Набор сейчас закрыт.", show_alert=True)
        return

    try:
        begin_immediate()
        fresh_player = get_player(user_id)
        current_open = db.execute("SELECT is_open FROM faction_recruitment WHERE faction=?", (faction_name,)).fetchone()
        if (not fresh_player or fresh_player["banned"] or fresh_player["faction"] != player["faction"]
                or int(fresh_player["balance"] or 0) < entry_fee or not current_open or not current_open["is_open"]):
            db.rollback()
            await callback.answer("Условия подачи заявки изменились. Обнови данные и попробуй снова.", show_alert=True)
            return
        db.execute("""INSERT INTO faction_applications(user_id, faction, status, created_at, entry_fee)
                      VALUES (?, ?, 'На собеседование', ?, ?)
                      ON CONFLICT(user_id, faction) DO UPDATE SET status='На собеседование', created_at=excluded.created_at, entry_fee=excluded.entry_fee""",
                   (user_id, faction_name, now_text(), entry_fee))
        db.commit()
    except TransactionConflict:
        await callback.answer("База занята. Повтори немного позже.", show_alert=True)
        return
    except sqlite3.Error:
        if db.in_transaction:
            db.rollback()
        log.exception("Не удалось сохранить заявку во фракцию %s для %s", faction_name, user_id)
        await callback.answer("Не удалось сохранить заявку. Попробуй позже.", show_alert=True)
        return
    await callback.answer(f"Заявка отправлена. Стоимость при принятии: ${entry_fee:,}.")
    await callback.message.edit_text(
        f"📋 Заявка в {faction_name} отправлена.\n"
        "Дождись, пока руководство назначит собеседование.\n"
        "Вступление без собеседования отключено."
    )


