@dp.callback_query(F.data == "uni:work")
async def university_staff_work_menu(callback: CallbackQuery):
    employee = get_player(callback.from_user.id)
    if not university_employee(callback.from_user.id):
        await callback.answer("Раздел доступен только сотрудникам университета.", show_alert=True)
        return
    if employee["location"] != "Университет":
        await callback.answer("Для служебной работы нужно прибыть в кампус университета.", show_alert=True)
        return
    active = db.execute(
        "SELECT * FROM faction_work_sessions WHERE user_id=? AND faction='Университет' "
        "AND status IN ('В работе','На проверке') ORDER BY id DESC LIMIT 1",
        (callback.from_user.id,)
    ).fetchone()
    lines = [f"📚 СЛУЖЕБНАЯ РАБОТА · {employee['rank']}", "Задания преподавателей и администрации университета."]
    buttons = []
    if active:
        lines.append(f"Текущее поручение №{active['id']}: {active['task_title']} · {active['status']}")
        if active['status'] == 'В работе':
            buttons.append([InlineKeyboardButton(text="▶️ Продолжить поручение", callback_data=f"fwork:stage:{active['id']}:{int(active['stage_index'] or 0)}")]) if int(active['stage_index'] or 0) < len(_faction_work_steps(active['faction'], active['task_key'])) else buttons.append([InlineKeyboardButton(text="📝 Сдать отчёт", callback_data=f"fwork:submit:{active['id']}")])
    else:
        buttons.append([InlineKeyboardButton(text="📋 Получить поручение", callback_data="fwork:take")])
    pending = []
    if employee['rank'] in ("Заместитель декана", "Декан"):
        pending = db.execute("SELECT id,user_id,task_title,report,created_at FROM faction_work_sessions WHERE faction='Университет' AND status='На проверке' ORDER BY id DESC LIMIT 10").fetchall()
    await callback.answer()
    await callback.message.answer("\n".join(lines), reply_markup=InlineKeyboardMarkup(inline_keyboard=buttons) if buttons else university_keyboard(callback.from_user.id))
    for report in pending:
        author = get_player(report['user_id'])
