# =========================================================
# 22. ОБРАБОТКА ОТВЕТОВ НА ВОПРОСЫ
# =========================================================

@dp.callback_query(F.data.startswith("uq:"))
async def university_answer_handler(
    callback: CallbackQuery,
    state: FSMContext
):
    if await state.get_state() != UniversityQuiz.answering.state:
        await callback.answer(
            "Этот вопрос уже неактуален.",
            show_alert=True
        )
        return

    data = await state.get_data()

    try:
        _, nonce, answer_text = callback.data.split(":")
        answer_index = int(answer_text)
    except (ValueError, AttributeError):
        await callback.answer("Ошибка ответа.", show_alert=True)
        return

    if nonce != data.get("nonce"):
        await callback.answer(
            "Этот вопрос уже неактуален.",
            show_alert=True
        )
        return

    questions = data["questions"]
    index = data["index"]

    if index >= len(questions):
        await callback.answer("Тест завершён.", show_alert=True)
        return

    question, answers, correct = questions[index]

    if answer_index < 0 or answer_index >= len(answers):
        await callback.answer("Некорректный ответ.", show_alert=True)
        return

    score = data["score"]

    if answer_index == correct:
        score += 1
        answer_result = "✅ Верно!"
    else:
        answer_result = (
            f"❌ Неверно.\nПравильный ответ: {answers[correct]}"
        )

    index += 1

    await state.update_data(
        index=index,
        score=score,
        nonce=secrets.token_hex(3)
    )

    await callback.answer()

    try:
        await callback.message.edit_reply_markup(
            reply_markup=None
        )
        await callback.message.edit_text(
            callback.message.text + "\n\n" + answer_result
        )
    except Exception:
        log.debug("Optional operation failed", exc_info=True)
    if index < len(questions):
        if data["quiz_kind"] in ("final", "unified_express"):
            await send_final_university_question(
                callback.message,
                state
            )
        else:
            await send_university_question(
                callback.message,
                state
            )
        return

    if data["quiz_kind"] == "final":
        await finish_final_university_exam(callback.message, state, score)
    elif data["quiz_kind"] == "unified_express":
        await finish_unified_express_exam(callback.message, state, score)
    else:
        await finish_university_quiz(callback.message, state, score)


# =========================================================
# 23. ЗАВЕРШЕНИЕ ЗАНЯТИЯ И ЭКЗАМЕНА
# =========================================================

async def finish_university_quiz(message, state, score):
    data = await state.get_data()

    quiz_kind = data["quiz_kind"]
    subject = data["subject"]
    user_id = message.chat.id

    if quiz_kind == "lesson":
        earned = score * 5

        try:
            begin_immediate()
            db.execute(
                """
                INSERT INTO lessons(user_id, subject, points, completed)
                VALUES (?, ?, ?, 1)
                ON CONFLICT(user_id, subject)
                DO UPDATE SET
                    points = MIN(25, lessons.points + excluded.points),
                    completed = 1
                """,
                (user_id, subject, earned)
            )
            db.commit()
        except sqlite3.Error:
            if db.in_transaction: db.rollback()
            log.exception("Ошибка сохранения баллов урока")
            await state.clear()
            await message.answer("Не удалось сохранить результат занятия. Попробуй позже.")
            return

        total_points = education_points(user_id, subject)

        result = (
            f"📖 Занятие завершено!\n\n"
            f"Правильных ответов: {score}/5\n"
            f"Получено баллов: {earned}\n"
            f"Всего по предмету: {total_points}/25"
        )

    else:
        grade = grade_from_score(score)
        passed = score >= 3

        try:
            begin_immediate()
            db.execute(
                """
                INSERT INTO university_tests(
                    user_id, subject, score, grade, passed, taken_at
                )
                VALUES (?, ?, ?, ?, ?, ?)
                """,
                (user_id, subject, score, grade, int(passed), now_text())
            )
            db.commit()
        except sqlite3.Error:
            if db.in_transaction: db.rollback()
            log.exception("Ошибка сохранения результата теста")
            await state.clear()
            await message.answer("Не удалось сохранить результат экзамена. Попробуй позже.")
            return

        result = (
            f"📝 Экзамен завершён!\n\n"
            f"Предмет: {subject}\n"
            f"Правильных ответов: {score}/5\n"
            f"Оценка: {grade}\n"
            f"Результат: {'Зачёт ✅' if passed else 'Не зачёт ❌'}"
        )

        if not passed:
            result += (
                "\n\nМожешь продолжить занятия "
                "и попробовать сдать экзамен повторно."
            )

    await state.clear()

    await message.answer(
        result,
        reply_markup=university_keyboard(user_id)
    )


async def finish_unified_express_exam(message, state, score):
    user_id = message.chat.id
    passed = score >= 5
    try:
        begin_immediate()
        db.execute(
            "INSERT INTO university_express_results(user_id,score,passed,taken_at) VALUES(?,?,?,?)",
            (user_id, score, int(passed), now_text())
        )
        if passed:
            for subject in SUBJECTS:
                db.execute(
                    "INSERT INTO university_tests(user_id,subject,score,grade,passed,taken_at) VALUES(?,?,?,?,1,?)",
                    (user_id, subject, score, 5, now_text())
                )
        db.commit()
    except sqlite3.Error:
        if db.in_transaction:
            db.rollback()
        log.exception("Не удалось сохранить единый экспресс-экзамен")
        await state.clear()
        await message.answer("Не удалось сохранить результат экзамена. Попробуй позже.")
        return
    await state.clear()
    if passed:
        result = (
            "✅ ЕДИНЫЙ ЭКСПРЕСС-ЭКЗАМЕН СДАН!\n\n"
            f"Правильных ответов: {score}/7.\n"
            "Все семь предметов зачтены. Теперь доступен итоговый экзамен."
        )
    else:
        result = (
            "❌ ЕДИНЫЙ ЭКСПРЕСС-ЭКЗАМЕН НЕ СДАН.\n\n"
            f"Правильных ответов: {score}/7.\n"
            "Для зачёта нужно минимум 5 правильных ответов. Попробуй ещё раз позже."
        )
    await message.answer(result, reply_markup=university_keyboard(user_id))


