@dp.callback_query(F.data == "uni:job")
async def university_job_handler(callback: CallbackQuery):
    user_id = callback.from_user.id
    create_player(user_id)
    player = get_player(user_id)
    if player["education"] != "Высшее":
        await callback.answer("Для работы преподавателем требуется высшее образование.", show_alert=True)
        return
    if player["faction"] == "Университет":
        await callback.answer("Ты уже работаешь в университете.", show_alert=True)
        return
    if player["faction"] != "Нет":
        await callback.answer("Сначала нужно завершить службу в другой организации.", show_alert=True)
        return
    pending = db.execute(
        "SELECT id FROM university_job_applications WHERE user_id=? AND status='На рассмотрении' ORDER BY id DESC LIMIT 1",
        (user_id,)
    ).fetchone()
    if pending:
        await callback.answer(f"Твоя заявка №{pending['id']} уже рассматривается.", show_alert=True)
        return
    try:
        begin_immediate()
        if not claim_operation("university_job_application"):
            db.rollback(); await callback.answer("Эта заявка уже отправлена.", show_alert=True); return
        pending = db.execute(
            "SELECT id FROM university_job_applications WHERE user_id=? AND status='На рассмотрении' LIMIT 1",
            (user_id,)
        ).fetchone()
        if pending:
            db.rollback(); await callback.answer(f"Заявка №{pending['id']} уже рассматривается.", show_alert=True); return
        cur = db.execute(
            "INSERT INTO university_job_applications(user_id,experience,status,created_at) VALUES(?,?,'На рассмотрении',?)",
            (user_id, "Высшее образование; заявка на должность преподавателя", now_text())
        )
        application_id = cur.lastrowid
        db.commit()
    except sqlite3.Error:
        if db.in_transaction: db.rollback()
        log.exception("Не удалось сохранить заявку на работу в университете")
        await callback.answer("Не удалось отправить заявку. Попробуй позже.", show_alert=True)
        return
    leaders = db.execute(
        "SELECT user_id FROM players WHERE faction='Университет' AND rank IN ('Декан','Заместитель декана') AND user_id!=?",
        (user_id,)
    ).fetchall()
    reviewers = [int(row["user_id"]) for row in leaders] or [int(x) for x in ADMIN_IDS if int(x) != user_id]
    keyboard = InlineKeyboardMarkup(inline_keyboard=[[
        InlineKeyboardButton(text="✅ Принять на работу", callback_data=f"unijob:decision:{application_id}:accept"),
        InlineKeyboardButton(text="❌ Отказать", callback_data=f"unijob:decision:{application_id}:reject")
    ]])
    delivered = 0
    for reviewer_id in reviewers:
        try:
            await callback.bot.send_message(
                reviewer_id,
                f"🎓 Заявка на работу в университете №{application_id}\nКандидат: {player_display_name(player)}\nОбразование: {player['education']}\nПосле одобрения ты будешь {gender_form(player, 'назначен', 'назначена')} преподавателем.",
                reply_markup=keyboard
            )
            delivered += 1
        except Exception:
            log.debug("Не удалось уведомить руководство университета %s", reviewer_id, exc_info=True)
    await callback.answer("Заявка отправлена.")
    await callback.message.answer(
        f"✅ Заявка на работу №{application_id} сохранена.\n"
        + ("Руководство университета уведомлено." if delivered else "Уведомление руководству не доставлено; заявка сохранена и доступна через /uni_jobs.")
    )


@dp.message(Command("uni_report"))
async def university_report_submit_command(message: Message):
    uid = message.from_user.id
    player = get_player(uid)
    if not player or not university_employee(uid):
        await message.answer("Академический отчёт могут подавать только сотрудники университета.")
        return
    body = (message.text or "").partition(" ")[2].strip()
    if len(body) < 50:
        await message.answer("Опиши выполненную работу минимум в 50 символах. Формат: /uni_report текст отчёта")
        return
    if len(body) > 1800:
        await message.answer("Отчёт слишком длинный. Максимум — 1800 символов.")
        return
    try:
        begin_immediate()
        if not claim_operation("university_report_submit"):
            db.rollback(); await message.answer("Этот отчёт уже отправлен."); return
        pending = db.execute("SELECT id FROM university_reports WHERE user_id=? AND status='На проверке' LIMIT 1", (uid,)).fetchone()
        if pending:
            db.rollback(); await message.answer(f"У тебя уже есть отчёт №{pending['id']} на проверке."); return
        cur = db.execute(
            "INSERT INTO university_reports(user_id,report,checked,created_at,status,reviewed_by,reviewed_at) VALUES(?,?,0,?,'На проверке',0,'')",
            (uid, body, now_text())
        )
        report_id = cur.lastrowid
        db.commit()
    except sqlite3.Error:
        if db.in_transaction: db.rollback()
        log.exception("Не удалось сохранить академический отчёт")
        await message.answer("Не удалось отправить отчёт. Попробуй позже.")
        return
    leaders = db.execute("SELECT user_id FROM players WHERE faction='Университет' AND rank IN ('Декан','Заместитель декана') AND user_id!=?", (uid,)).fetchall()
    reviewers = [int(row["user_id"]) for row in leaders] or [int(x) for x in ADMIN_IDS if int(x) != uid]
    keyboard = InlineKeyboardMarkup(inline_keyboard=[[
        InlineKeyboardButton(text="✅ Принять отчёт", callback_data=f"unireport:{report_id}:accept"),
        InlineKeyboardButton(text="❌ Отклонить", callback_data=f"unireport:{report_id}:reject")
    ]])
    delivered = 0
    for reviewer_id in reviewers:
        try:
            await message.bot.send_message(reviewer_id, f"📑 Академический отчёт №{report_id}\nСотрудник: {player_display_name(player)}\nДолжность: {player['rank']}\n\n{body}", reply_markup=keyboard)
            delivered += 1
        except Exception:
            log.debug("Не удалось доставить академический отчёт руководителю %s", reviewer_id, exc_info=True)
    await message.answer(f"✅ Академический отчёт №{report_id} отправлен. " + ("Руководство уведомлено." if delivered else "Отчёт сохранён; руководство сможет открыть /uni_reports."))


