@dp.callback_query(F.data.startswith("unireport:"))
async def university_report_decision_callback(callback: CallbackQuery):
    parts = callback.data.split(":")
    if len(parts) != 3 or not parts[1].isdigit() or parts[2] not in ("accept", "reject"):
        await callback.answer("Некорректное решение.", show_alert=True)
        return
    report_id, decision = int(parts[1]), parts[2]
    actor = get_player(callback.from_user.id)
    allowed = bool(is_admin(callback.from_user.id) or (actor and actor["faction"] == "Университет" and actor["rank"] in ("Декан", "Заместитель декана")))
    if not allowed:
        await callback.answer("Проверять отчёты может декан, заместитель декана или администрация.", show_alert=True)
        return
    try:
        begin_immediate()
        if not claim_operation("university_report_decision"):
            db.rollback(); await callback.answer("Это решение уже обработано.", show_alert=True); return
        report = db.execute("SELECT * FROM university_reports WHERE id=? AND status='На проверке'", (report_id,)).fetchone()
        if not report:
            db.rollback(); await callback.answer("Отчёт уже проверен или не найден.", show_alert=True); return
        if int(report["user_id"]) == callback.from_user.id:
            db.rollback(); await callback.answer("Нельзя проверять собственный академический отчёт.", show_alert=True); return
        target = get_player(report["user_id"])
        if not target or not university_employee(report["user_id"]):
            db.execute("UPDATE university_reports SET status='Отменён',reviewed_by=?,reviewed_at=? WHERE id=?", (callback.from_user.id, now_text(), report_id))
            db.commit(); await callback.answer("Автор больше не работает в университете.", show_alert=True); return
        accepted = decision == "accept"
        db.execute(
            "UPDATE university_reports SET checked=?,status=?,reviewed_by=?,reviewed_at=? WHERE id=? AND status='На проверке'",
            (int(accepted), "Принят" if accepted else "Отклонён", callback.from_user.id, now_text(), report_id)
        )
        db.commit()
    except sqlite3.Error:
        if db.in_transaction: db.rollback()
        log.exception("Не удалось сохранить решение по академическому отчёту")
        await callback.answer("Не удалось сохранить решение.", show_alert=True)
        return
    await callback.answer("Решение сохранено.")
    try:
        await callback.message.edit_reply_markup(reply_markup=None)
        await callback.bot.send_message(report["user_id"], f"📑 Академический отчёт №{report_id}: {'принят' if accepted else 'отклонён'}.")
    except Exception:
        log.debug("Не удалось уведомить автора академического отчёта", exc_info=True)
    await callback.message.answer(f"Отчёт №{report_id}: {'принят' if accepted else 'отклонён'}.")


