@dp.callback_query(F.data.startswith("unijob:decision:"))
async def university_job_decision_callback(callback: CallbackQuery):
    parts = callback.data.split(":")
    if len(parts) != 4 or not parts[2].isdigit() or parts[3] not in ("accept", "reject"):
        await callback.answer("Некорректное решение.", show_alert=True)
        return
    application_id, decision = int(parts[2]), parts[3]
    actor = get_player(callback.from_user.id)
    is_dean = bool(actor and actor["faction"] == "Университет" and actor["rank"] in ("Декан", "Заместитель декана"))
    if not is_admin(callback.from_user.id) and not is_dean:
        await callback.answer("Решать заявки может декан, заместитель декана или администрация.", show_alert=True)
        return
    try:
        begin_immediate()
        if not claim_operation("university_job_decision"):
            db.rollback(); await callback.answer("Это решение уже обработано.", show_alert=True); return
        application = db.execute(
            "SELECT * FROM university_job_applications WHERE id=? AND status='На рассмотрении'",
            (application_id,)
        ).fetchone()
        if not application:
            db.rollback(); await callback.answer("Заявка уже обработана или не найдена.", show_alert=True); return
        if int(application["user_id"]) == callback.from_user.id:
            db.rollback(); await callback.answer("Нельзя самостоятельно одобрить собственную заявку.", show_alert=True); return
        target = db.execute("SELECT faction,rank,education FROM players WHERE user_id=?", (application["user_id"],)).fetchone()
        now = now_text()
        if decision == "reject":
            db.execute(
                "UPDATE university_job_applications SET status='Отклонена',reviewed_by=?,reviewed_at=?,decision_note='Отказ руководства' WHERE id=? AND status='На рассмотрении'",
                (callback.from_user.id, now, application_id)
            )
            result = "Отклонена"
        else:
            if not target or target["faction"] != "Нет" or target["education"] != "Высшее":
                db.execute(
                    "UPDATE university_job_applications SET status='Отменена: кандидат больше не соответствует условиям',reviewed_by=?,reviewed_at=?,decision_note='Изменились условия кандидата' WHERE id=? AND status='На рассмотрении'",
                    (callback.from_user.id, now, application_id)
                )
                result = "Отменена: кандидат не соответствует условиям"
            else:
                db.execute("UPDATE players SET faction='Университет',rank='Преподаватель' WHERE user_id=? AND faction='Нет'", (application["user_id"],))
                membership = db.execute(
                    "SELECT id FROM faction_membership WHERE user_id=? AND faction='Университет' AND (left_at IS NULL OR left_at='') ORDER BY id DESC LIMIT 1",
                    (application["user_id"],)
                ).fetchone()
                if membership:
                    db.execute("UPDATE faction_membership SET rank='Преподаватель' WHERE id=?", (membership["id"],))
                else:
                    db.execute("INSERT INTO faction_membership(user_id,faction,rank,joined_at) VALUES(?,'Университет','Преподаватель',?)", (application["user_id"], now))
                db.execute(
                    "INSERT INTO rank_history(user_id,faction,old_rank,new_rank,changed_by,reason,created_at) VALUES(?,'Университет',?,?,?,'Принят на работу в университет',?)",
                    (application["user_id"], target["rank"] or "Нет", "Преподаватель", callback.from_user.id, now)
                )
                employment = db.execute(
                    "SELECT id FROM employment_history WHERE user_id=? AND faction='Университет' AND (ended_at IS NULL OR ended_at='') ORDER BY id DESC LIMIT 1",
                    (application["user_id"],)
                ).fetchone()
                if employment:
                    db.execute("UPDATE employment_history SET rank='Преподаватель' WHERE id=?", (employment["id"],))
                else:
                    db.execute(
                        "INSERT INTO employment_history(user_id,faction,rank,action,started_at,ended_at,actor_id,created_at) VALUES(?,'Университет','Преподаватель','Приём',?,'',?,?)",
                        (application["user_id"], now, callback.from_user.id, now)
                    )
                db.execute(
                    "UPDATE university_job_applications SET status='Принята',reviewed_by=?,reviewed_at=?,decision_note='Назначен преподавателем' WHERE id=? AND status='На рассмотрении'",
                    (callback.from_user.id, now, application_id)
                )
                result = "Принята. Кандидат назначен преподавателем."
        db.commit()
    except sqlite3.Error:
        if db.in_transaction: db.rollback()
        log.exception("Ошибка решения по заявке университета")
        await callback.answer("Не удалось сохранить решение.", show_alert=True)
        return
    await callback.answer("Решение сохранено.")
    try:
        await callback.message.edit_reply_markup(reply_markup=None)
        await callback.bot.send_message(application["user_id"], f"🎓 Решение по заявке на работу №{application_id}: {result}")
    except Exception:
        log.debug("Не удалось уведомить кандидата о решении по заявке", exc_info=True)
    await callback.message.answer(f"Заявка №{application_id}: {result}")


@dp.message(Command("setdean"))
async def set_dean_handler(message: Message):
    if message.from_user.id not in ADMIN_IDS:
        await message.answer("❌ У тебя нет доступа к этой команде.")
        return

    parts = message.text.split()

    if len(parts) != 2 or not parts[1].isdigit():
        await message.answer("Использование: /setdean GAME_ID")
        return

    player = get_player_by_game_id(parts[1])
    if not player:
        await message.answer("Персонаж с таким игровым ID не найден.")
        return
    target_id = int(player["user_id"])

    if player["faction"] not in ("Нет", "Университет"):
        await message.answer(
            "Игрок уже состоит в другой организации."
        )
        return

    try:
        begin_immediate()
        fresh_player = db.execute("SELECT faction,rank FROM players WHERE user_id=?", (target_id,)).fetchone()
        if not fresh_player or fresh_player["faction"] not in ("Нет", "Университет"):
            db.rollback()
            await message.answer("Назначение отменено: персонаж уже состоит в другой организации.")
            return

        db.execute(
            """
            UPDATE players
            SET faction = 'Университет', rank = 'Декан'
            WHERE user_id = ?
            """,
            (target_id,)
        )

        active_membership = db.execute(
            "SELECT id FROM faction_membership WHERE user_id=? AND faction='Университет' "
            "AND (left_at IS NULL OR left_at='') ORDER BY id DESC LIMIT 1",
            (target_id,)
        ).fetchone()
        if active_membership:
            db.execute("UPDATE faction_membership SET rank='Декан' WHERE id=?", (active_membership["id"],))
        else:
            db.execute(
                "INSERT INTO faction_membership(user_id,faction,rank,joined_at) VALUES(?,'Университет','Декан',?)",
                (target_id, now_text())
            )
        now = now_text()
        old_rank = fresh_player["rank"] or "Нет"
        if old_rank != "Декан":
            db.execute(
                "INSERT INTO rank_history(user_id,faction,old_rank,new_rank,changed_by,reason,created_at) VALUES(?,'Университет',?,'Декан',?,'Назначение деканом',?)",
                (target_id, old_rank, message.from_user.id, now)
            )
        employment = db.execute(
            "SELECT id FROM employment_history WHERE user_id=? AND faction='Университет' AND (ended_at IS NULL OR ended_at='') ORDER BY id DESC LIMIT 1",
            (target_id,)
        ).fetchone()
        if employment:
            db.execute("UPDATE employment_history SET rank=? WHERE id=?", ("Декан", employment["id"]))
        else:
            db.execute(
                "INSERT INTO employment_history(user_id,faction,rank,action,started_at,ended_at,actor_id,created_at) VALUES(?,'Университет','Декан','Приём',?,'',?,?)",
                (target_id, now, message.from_user.id, now)
            )

        db.commit()

    except sqlite3.Error:
        db.rollback()
        log.exception("Ошибка назначения декана")
        await message.answer("Не удалось назначить декана.")
        return

    await message.answer(
        f"✅ {player_display_name(get_player(target_id))} {gender_form(get_player(target_id), 'назначен', 'назначена')} деканом."
    )


@dp.message(Command("uniset"))
async def uniset_handler(message: Message):
    if message.from_user.id not in ADMIN_IDS:
        await message.answer("❌ Нет доступа.")
        return

    parts = message.text.split()

    if len(parts) != 3:
        await message.answer(
            "Использование:\n"
            "/uniset GAME_ID Должность\n\n"
            "Должности:\n"
            "Староста\n"
            "Преподаватель\n"
            "Заместитель_декана\n"
            "Декан"
        )
        return

    if not parts[1].isdigit():
        await message.answer("Некорректный игровой ID.")
        return

    target_player = get_player_by_game_id(parts[1])
    if not target_player:
        await message.answer("Персонаж с таким игровым ID не найден.")
        return
    target_id = int(target_player["user_id"])
    rank = parts[2].replace("_", " ")

    if rank not in UNIVERSITY_RANKS:
        await message.answer("Неизвестная должность.")
        return

    try:
        begin_immediate()

        player = db.execute(
            "SELECT faction,rank FROM players WHERE user_id = ?",
            (target_id,)
        ).fetchone()

        if not player:
            db.rollback()
            await message.answer("Игрок не найден.")
            return

        if player["faction"] not in ("Нет", "Университет"):
            db.rollback()
            await message.answer(
                "Игрок состоит в другой организации."
            )
            return

        db.execute(
            """
            UPDATE players
            SET faction = 'Университет', rank = ?
            WHERE user_id = ?
            """,
            (rank, target_id)
        )

        active_membership = db.execute(
            "SELECT id FROM faction_membership WHERE user_id=? AND faction='Университет' "
            "AND (left_at IS NULL OR left_at='') ORDER BY id DESC LIMIT 1",
            (target_id,)
        ).fetchone()
        if active_membership:
            db.execute("UPDATE faction_membership SET rank=? WHERE id=?", (rank, active_membership["id"]))
        else:
            db.execute(
                "INSERT INTO faction_membership(user_id,faction,rank,joined_at) VALUES(?,'Университет',?,?)",
                (target_id, rank, now_text())
            )
        now = now_text()
        old_rank = player["rank"] or "Нет"
        if old_rank != rank:
            db.execute(
                "INSERT INTO rank_history(user_id,faction,old_rank,new_rank,changed_by,reason,created_at) VALUES(?,?,?,?,?,'Назначение должности университета',?)",
                (target_id, "Университет", old_rank, rank, message.from_user.id, now)
            )
        employment = db.execute(
            "SELECT id FROM employment_history WHERE user_id=? AND faction='Университет' AND (ended_at IS NULL OR ended_at='') ORDER BY id DESC LIMIT 1",
            (target_id,)
        ).fetchone()
        if employment:
            db.execute("UPDATE employment_history SET rank=? WHERE id=?", (rank, employment["id"]))
        else:
            db.execute(
                "INSERT INTO employment_history(user_id,faction,rank,action,started_at,ended_at,actor_id,created_at) VALUES(?, 'Университет', ?, 'Приём', ?, '', ?, ?)",
                (target_id, rank, now, message.from_user.id, now)
            )

        db.commit()

    except sqlite3.Error:
        db.rollback()
        log.exception("Ошибка изменения должности")
        await message.answer("Не удалось изменить должность.")
        return

    await message.answer(
        f"✅ {player_display_name(get_player(target_id))} теперь занимает должность: {rank}."
    )


# =========================================================
# 27. ВЫПЛАТА ЗАРПЛАТЫ УНИВЕРСИТЕТА
# =========================================================

# Ручная команда /payday отключена: зарплата начисляется автоматически раз в час.


def purchase_item(user_id, item_name, price, description=""):
    """
    Списывает деньги и добавляет предмет в инвентарь
    в одной транзакции.
    """
    if price < 0:
        return False

    try:
        begin_immediate()
        if not claim_operation("purchase"):
            db.rollback()
            return True

        player = db.execute(
            "SELECT balance FROM players WHERE user_id = ?",
            (user_id,)
        ).fetchone()

        if not player or player["balance"] < price:
            db.rollback()
            return False

        _debit = db.execute(
            """
            UPDATE players
            SET balance = balance - ?
            WHERE user_id = ? AND balance >= ?
            """,
            (price, user_id, price)
        )
        if _debit.rowcount != 1:
            raise sqlite3.IntegrityError("insufficient_funds")

        db.execute(
            """
            INSERT INTO inventory(user_id, item_name, quantity)
            VALUES (?, ?, 1)
            ON CONFLICT(user_id, item_name)
            DO UPDATE SET quantity = quantity + 1
            """,
            (user_id, item_name)
        )

        db.execute(
            """
            INSERT INTO bank_transactions(
                user_id, other_user_id, amount,
                transaction_type, description, created_at
            )
            VALUES (?, 0, ?, 'purchase', ?, ?)
            """,
            (user_id, price, description or item_name, now_text())
        )

        db.commit()
        return True

    except sqlite3.Error:
        db.rollback()
        log.exception("Ошибка покупки предмета")
        return False


