@dp.callback_query(F.data == "bank:transfer")
async def bank_transfer_start(
    callback: CallbackQuery,
    state: FSMContext
):
    await state.clear()
    await state.set_state(BankTransferFlow.receiver)

    await callback.answer()

    await callback.message.answer(
        "🏦 Введи игровой ID персонажа-получателя перевода."
    )


@dp.message(BankTransferFlow.receiver)
async def bank_transfer_receiver(
    message: Message,
    state: FSMContext
):
    if not message.text or not message.text.isdigit():
        await message.answer("Введи числовой игровой ID.")
        return

    receiver = get_player_by_game_id(message.text)
    if not receiver:
        await message.answer("Персонаж с таким игровым ID не найден.")
        return
    receiver_id = int(receiver["user_id"])

    if receiver_id == message.from_user.id:
        await message.answer("Нельзя переводить деньги самому себе.")
        return

    await state.update_data(receiver_id=receiver_id)
    await state.set_state(BankTransferFlow.amount)

    await message.answer("Введи сумму перевода целым числом.")


@dp.message(BankTransferFlow.amount)
async def bank_transfer_amount(
    message: Message,
    state: FSMContext
):
    if not message.text or not message.text.isdigit():
        await message.answer("Сумма должна быть целым положительным числом.")
        return

    amount = int(message.text)

    if amount <= 0 or amount > 1_000_000_000:
        await message.answer("Недопустимая сумма.")
        return

    data = await state.get_data()
    sender_id = message.from_user.id
    receiver_id = data["receiver_id"]

    try:
        begin_immediate()
        if not claim_operation("transfer"):
            db.rollback()
            await state.clear()
            await message.answer("Этот перевод уже выполнен.")
            return

        sender = db.execute(
            "SELECT balance FROM players WHERE user_id = ?",
            (sender_id,)
        ).fetchone()

        receiver = db.execute(
            "SELECT user_id,balance FROM players WHERE user_id = ?",
            (receiver_id,)
        ).fetchone()

        if not sender or sender["balance"] < amount:
            db.rollback()
            await message.answer("Недостаточно средств.")
            return

        if not receiver:
            db.rollback()
            await message.answer("Получатель не найден.")
            return

        if sender_id == receiver_id:
            raise sqlite3.IntegrityError("self_transfer")

        _out = db.execute(
            """
            UPDATE players
            SET balance = balance - ?
            WHERE user_id = ? AND balance >= ?
            """,
            (amount, sender_id, amount)
        )
        if _out.rowcount != 1:
            raise sqlite3.IntegrityError("insufficient_funds")

        if int(receiver["balance"]) > MAX_BALANCE - amount:
            db.rollback()
            await message.answer("Перевод отменён: у получателя достигнут лимит игрового баланса.")
            return
        _in = db.execute(
            """
            UPDATE players
            SET balance = balance + ?
            WHERE user_id = ? AND balance <= ?
            """,
            (amount, receiver_id, MAX_BALANCE - amount)
        )
        if _in.rowcount != 1:
            raise sqlite3.IntegrityError("receiver_missing")

        db.execute(
            """
            INSERT INTO bank_transactions(
                user_id, other_user_id, amount,
                transaction_type, description, created_at
            )
            VALUES (?, ?, ?, 'transfer_out', ?, ?)
            """,
            (
                sender_id,
                receiver_id,
                amount,
                "Перевод игроку",
                now_text()
            )
        )

        db.execute(
            """
            INSERT INTO bank_transactions(
                user_id, other_user_id, amount,
                transaction_type, description, created_at
            )
            VALUES (?, ?, ?, 'transfer_in', ?, ?)
            """,
            (
                receiver_id,
                sender_id,
                amount,
                "Получен перевод",
                now_text()
            )
        )

        db.commit()

    except sqlite3.Error:
        db.rollback()
        log.exception("Ошибка банковского перевода")
        await message.answer("Ошибка перевода. Попробуй позже.")
        await state.clear()
        return

    await state.clear()
    receiver = get_player(receiver_id)

    await message.answer(
        f"✅ Перевод выполнен.\n\n"
        f"Получатель: {player_display_name(receiver)}\n"
        f"Сумма: ${amount:,}",
        reply_markup=main_keyboard(get_player(message.from_user.id))
    )

    settings = db.execute(
        """
        SELECT notifications FROM phone_settings
        WHERE user_id = ?
        """,
        (receiver_id,)
    ).fetchone()

    if settings and settings["notifications"]:
        try:
            await bot.send_message(
                receiver_id,
                f"🏦 На твой счёт поступило ${amount:,}."
            )
        except Exception:
            log.info("Не удалось уведомить получателя перевода")


