@dp.message(Command("garage"))
async def garage_handler(message: Message):
    user_id = message.from_user.id
    create_player(user_id)
    rows = db.execute(
        "SELECT id,vehicle_name,purchased_at,fuel,condition,plate FROM vehicles WHERE user_id=? ORDER BY id DESC",
        (user_id,)
    ).fetchall()
    if not rows:
        await message.answer("🚗 Твой гараж пока пуст.")
        return
    lines = ["🚗 **ТВОЙ ГАРАЖ**"]
    keyboard = []
    catalog_prices = {name: price for name, price in VEHICLE_CATALOG.items()}
    for row in rows:
        base_price = catalog_prices.get(row["vehicle_name"])
        condition = max(0, min(100, int(row["condition"] or 0)))
        resale = int(base_price * 0.60 * condition / 100) if base_price is not None else 0
        lines.append(
            f"• {row['vehicle_name']}\n"
            f"Номер: {row['plate'] or 'не присвоен'} · Топливо: {row['fuel']}% · Состояние: {condition}%\n"
            f"Куплен: {row['purchased_at']}"
            + (f"\nОценка продажи: {_west_money(resale)}" if base_price is not None else "\nОценка продажи недоступна для этой старой модели.")
        )
        if base_price is not None:
            keyboard.append([InlineKeyboardButton(text=f"Продать {row['vehicle_name']} · {_west_money(resale)}", callback_data=f"westcarsell:{row['id']}")])
    await message.answer("\n\n".join(lines), parse_mode="Markdown", reply_markup=InlineKeyboardMarkup(inline_keyboard=keyboard) if keyboard else None)


@dp.callback_query(F.data.startswith("westcarsell:"))
async def west_vehicle_sell_callback(callback: CallbackQuery):
    try:
        vehicle_id = int(callback.data.split(":", 1)[1])
    except (TypeError, ValueError):
        await callback.answer("Автомобиль не найден.", show_alert=True)
        return
    uid = callback.from_user.id
    catalog_prices = {name: price for name, price in VEHICLE_CATALOG.items()}
    try:
        begin_immediate()
        if not claim_operation("vehicle_sale"):
            db.rollback(); await callback.answer("Эта продажа уже обработана.", show_alert=True); return
        vehicle = db.execute("SELECT * FROM vehicles WHERE id=? AND user_id=?", (vehicle_id, uid)).fetchone()
        if not vehicle:
            db.rollback(); await callback.answer("Этот автомобиль тебе не принадлежит.", show_alert=True); return
        base_price = catalog_prices.get(vehicle["vehicle_name"])
        if base_price is None:
            db.rollback(); await callback.answer("Для этой старой модели нет оценочной цены.", show_alert=True); return
        condition = max(0, min(100, int(vehicle["condition"] or 0)))
        amount = int(base_price * 0.60 * condition / 100)
        balance = db.execute("SELECT balance FROM players WHERE user_id=?", (uid,)).fetchone()
        if not balance or int(balance["balance"]) > MAX_BALANCE - amount:
            db.rollback(); await callback.answer("Продажа отклонена: превышен лимит игрового баланса.", show_alert=True); return
        credited = db.execute("UPDATE players SET balance=balance+? WHERE user_id=? AND balance<=?", (amount, uid, MAX_BALANCE - amount))
        if credited.rowcount != 1:
            db.rollback(); await callback.answer("Не удалось зачислить средства.", show_alert=True); return
        db.execute("DELETE FROM vehicles WHERE id=? AND user_id=?", (vehicle_id, uid))
        db.execute(
            "INSERT INTO bank_transactions(user_id,other_user_id,amount,transaction_type,description,created_at) VALUES(?,0,?,'vehicle_sale',?,?)",
            (uid, amount, f"Продажа автомобиля: {vehicle['vehicle_name']}", now_text())
        )
        db.commit()
    except sqlite3.Error:
        if db.in_transaction: db.rollback()
        log.exception("Vehicle sale failed")
        await callback.answer("Не удалось продать автомобиль.", show_alert=True)
        return
    await callback.answer("Автомобиль продан.")
    await callback.message.answer(f"🚗 {vehicle['vehicle_name']} продан за {_west_money(amount)}. Оценка учитывала состояние автомобиля.")


