SIDE_ACTIVITY_DAILY_LIMIT = 6
SIDE_ACTIVITY_DAILY_EARNINGS_LIMIT = 3500


db.executescript("""
CREATE TABLE IF NOT EXISTS side_activity_sessions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    activity_key TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'accepted',
    created_at TEXT NOT NULL,
    arrived_at TEXT DEFAULT '',
    work_started_at TEXT DEFAULT '',
    completed_at TEXT DEFAULT '',
    reward INTEGER DEFAULT 0
);
CREATE INDEX IF NOT EXISTS idx_side_activity_user_history
    ON side_activity_sessions(user_id, id DESC);
CREATE UNIQUE INDEX IF NOT EXISTS idx_side_activity_one_active
    ON side_activity_sessions(user_id)
    WHERE status IN ('accepted','arrived','working');
""")
db.commit()


def side_activities_keyboard():
    rows = []
    for key, activity in SIDE_ACTIVITIES.items():
        rows.append([InlineKeyboardButton(
            text=f"{activity['emoji']} {activity['name']}",
            callback_data=f"sidejob:{key}"
        )])
    return InlineKeyboardMarkup(inline_keyboard=rows)


def side_job_stage_keyboard(session_id, stage, activity_key=None):
    activity = SIDE_ACTIVITIES.get(activity_key, {})
    if stage == "accepted":
        buttons = [
            [InlineKeyboardButton(text=activity.get("arrive_label", "📍 Приехал"), callback_data=f"sidejob:arrive:{session_id}")],
            [InlineKeyboardButton(text="❌ Отменить заказ", callback_data=f"sidejob:cancel:{session_id}")],
        ]
    elif stage == "arrived":
        buttons = [
            [InlineKeyboardButton(text=activity.get("start_label", "▶️ Начать работу"), callback_data=f"sidejob:start:{session_id}")],
            [InlineKeyboardButton(text="❌ Отменить заказ", callback_data=f"sidejob:cancel:{session_id}")],
        ]
    elif stage == "working":
        buttons = [
            [InlineKeyboardButton(text=activity.get("complete_label", "✅ Завершить заказ"), callback_data=f"sidejob:complete:{session_id}")],
            [InlineKeyboardButton(text="❌ Отменить заказ", callback_data=f"sidejob:cancel:{session_id}")],
        ]
    else:
        buttons = []
    return InlineKeyboardMarkup(inline_keyboard=buttons) if buttons else None


@dp.message(Command("activities"))
@dp.message(F.text == "🧰 Подработки")
async def side_activities_command(message: Message):
    create_player(message.from_user.id)
    active = db.execute(
        "SELECT id,activity_key,status FROM side_activity_sessions "
        "WHERE user_id=? AND status IN ('accepted','arrived','working') ORDER BY id DESC LIMIT 1",
        (message.from_user.id,)
    ).fetchone()
    if active:
        activity = SIDE_ACTIVITIES.get(active["activity_key"], {})
        stage_text = {"accepted": "Заказ принят. Нужно прибыть на место.", "arrived": "Ты прибыл. Начни выполнение работы.", "working": "Работа выполняется. Заверши заказ после выполнения."}.get(active["status"], "")
        await message.answer(
            f"🧰 Активная работа: {activity.get('name', 'Заказ')} №{active['id']}\n{stage_text}",
            reply_markup=side_job_stage_keyboard(active["id"], active["status"], active["activity_key"])
        )
        return
    await message.answer(
        "🧰 **Подработки RPM WEST**\n\n"
        "Выбери работу. После принятия заказа этапы будут открываться последовательно: "
        "«Приехал» → «Начать работу» → «Завершить заказ». Оплата начисляется только после завершения.",
        parse_mode="Markdown",
        reply_markup=side_activities_keyboard()
    )


@dp.callback_query(F.data.startswith("sidejob:"))
async def side_activity_callback(callback: CallbackQuery):
    user_id = callback.from_user.id
    create_player(user_id)
    parts = callback.data.split(":")
    now = datetime.now()
    today = now.date().isoformat()

    # Шаги уже принятого заказа. Все переходы атомарны и проверяют владельца.
    if len(parts) >= 3 and parts[1] in {"arrive", "start", "complete", "cancel"}:
        action = parts[1]
        try:
            session_id = int(parts[2])
        except (ValueError, IndexError):
            await callback.answer("Некорректный номер заказа.", show_alert=True)
            return
        try:
            begin_immediate()
            session = db.execute(
                "SELECT * FROM side_activity_sessions WHERE id=? AND user_id=?",
                (session_id, user_id)
            ).fetchone()
            if not session:
                db.rollback()
                await callback.answer("Заказ не найден.", show_alert=True)
                return
            if action == "cancel":
                changed = db.execute(
                    "UPDATE side_activity_sessions SET status='cancelled' "
                    "WHERE id=? AND user_id=? AND status IN ('accepted','arrived','working')",
                    (session_id, user_id)
                )
                if changed.rowcount != 1:
                    db.rollback()
                    await callback.answer("Заказ уже завершён или отменён.", show_alert=True)
                    return
                db.commit()
                await callback.answer("Заказ отменён. Выплаты нет.", show_alert=True)
                await callback.message.edit_text("❌ Заказ отменён. Денежная выплата не начислялась.")
                return
            expected = {"arrive": "accepted", "start": "arrived", "complete": "working"}[action]
            if session["status"] != expected:
                db.rollback()
                await callback.answer("Этот этап уже пройден или пока недоступен.", show_alert=True)
                return

            if action == "arrive":
                db.execute(
                    "UPDATE side_activity_sessions SET status='arrived',arrived_at=? "
                    "WHERE id=? AND user_id=? AND status='accepted'",
                    (now_text(), session_id, user_id)
                )
                db.commit()
                await callback.answer("Прибытие отмечено.")
                await callback.message.edit_text(
                    "📍 Ты отметил прибытие на место. Следующий этап открыт: начать работу.",
                    reply_markup=side_job_stage_keyboard(session_id, "arrived", session["activity_key"])
                )
                return

            if action == "start":
                db.execute(
                    "UPDATE side_activity_sessions SET status='working',work_started_at=? "
                    "WHERE id=? AND user_id=? AND status='arrived'",
                    (now_text(), session_id, user_id)
                )
                db.commit()
                await callback.answer("Работа начата.")
                await callback.message.edit_text(
                    "▶️ Работа начата. После выполнения задания нажми «Завершить заказ».",
                    reply_markup=side_job_stage_keyboard(session_id, "working", session["activity_key"])
                )
                return

            # Завершение: минимум 30 секунд активной стадии, повторная проверка лимитов.
            try:
                started = datetime.fromisoformat(session["work_started_at"])
                elapsed = (now - started).total_seconds()
            except (TypeError, ValueError):
                elapsed = 0
            if elapsed < 30:
                db.rollback()
                remaining = max(1, int(30 - elapsed + 0.999))
                await callback.answer(f"Работа ещё выполняется. Подожди {remaining} сек.", show_alert=True)
                return

            activity = SIDE_ACTIVITIES.get(session["activity_key"])
            if not activity:
                db.rollback()
                await callback.answer("Профессия больше недоступна. Обратись к администрации.", show_alert=True)
                return
            stats = db.execute(
                "SELECT last_completed FROM side_activity_stats WHERE user_id=? AND activity_key=?",
                (user_id, session["activity_key"])
            ).fetchone()
            if stats and stats["last_completed"]:
                try:
                    last = datetime.fromisoformat(stats["last_completed"])
                    remaining = int(activity["cooldown"] - (now - last).total_seconds())
                except (TypeError, ValueError):
                    remaining = 0
                if remaining > 0:
                    db.rollback()
                    await callback.answer("Для этой работы ещё действует перезарядка.", show_alert=True)
                    return
            daily = db.execute(
                "SELECT COUNT(*) AS runs, COALESCE(SUM(amount),0) AS earned "
                "FROM bank_transactions WHERE user_id=? AND transaction_type='work_reward' "
                "AND substr(created_at,1,10)=?",
                (user_id, today)
            ).fetchone()
            if daily["runs"] >= SIDE_ACTIVITY_DAILY_LIMIT or daily["earned"] >= SIDE_ACTIVITY_DAILY_EARNINGS_LIMIT:
                db.rollback()
                await callback.answer("Дневной лимит подработок уже исчерпан. Выплаты нет.", show_alert=True)
                return
            amount = random.randint(activity["min"], activity["max"])
            amount = min(amount, SIDE_ACTIVITY_DAILY_EARNINGS_LIMIT - int(daily["earned"]))
            changed = db.execute(
                "UPDATE players SET balance=balance+? WHERE user_id=? AND balance<=?",
                (amount, user_id, MAX_BALANCE - amount)
            )
            if changed.rowcount != 1:
                raise sqlite3.IntegrityError("side_job_balance_limit")
            completed_at = now_text()
            marked = db.execute(
                "UPDATE side_activity_sessions SET status='completed',completed_at=?,reward=? "
                "WHERE id=? AND user_id=? AND status='working'",
                (completed_at, amount, session_id, user_id)
            )
            if marked.rowcount != 1:
                raise sqlite3.IntegrityError("side_job_already_completed")
            db.execute(
                "INSERT INTO bank_transactions(user_id,other_user_id,amount,transaction_type,description,created_at) "
                "VALUES (?,0,?,'work_reward',?,?)",
                (user_id, amount, f"Подработка: {activity['name']}", completed_at)
            )
            db.execute(
                "INSERT INTO side_activity_stats(user_id,activity_key,last_completed,total_runs) "
                "VALUES(?,?,?,1) ON CONFLICT(user_id,activity_key) DO UPDATE SET "
                "last_completed=excluded.last_completed,total_runs=side_activity_stats.total_runs+1",
                (user_id, session["activity_key"], completed_at)
            )
            db.commit()
        except sqlite3.Error:
            if db.in_transaction:
                db.rollback()
            log.exception("Ошибка завершения этапа гражданской работы")
            await callback.answer("Не удалось обработать этап. Попробуй ещё раз.", show_alert=True)
            return

        balance = db.execute("SELECT balance FROM players WHERE user_id=?", (user_id,)).fetchone()["balance"]
        await callback.answer("Заказ завершён. Оплата начислена.", show_alert=True)
        await callback.message.edit_text(
            f"✅ **Заказ завершён: {activity['name']}**\n\n"
            f"Заработано: **${amount:,}**\nБаланс: **${balance:,}**\n"
            f"Дневной лимит: {daily['runs'] + 1}/{SIDE_ACTIVITY_DAILY_LIMIT} смен.",
            parse_mode="Markdown"
        )
        return

    # Принятие нового заказа.
    if len(parts) != 2:
        await callback.answer("Неизвестное действие с заказом.", show_alert=True)
        return
    key = parts[1]
    activity = SIDE_ACTIVITIES.get(key)
    if not activity:
        await callback.answer("Активность не найдена.", show_alert=True)
        return
    try:
        begin_immediate()
        active = db.execute(
            "SELECT id FROM side_activity_sessions WHERE user_id=? "
            "AND status IN ('accepted','arrived','working') LIMIT 1",
            (user_id,)
        ).fetchone()
        if active:
            db.rollback()
            await callback.answer(f"Сначала заверши или отмени заказ №{active['id']}.", show_alert=True)
            return
        stats = db.execute(
            "SELECT last_completed FROM side_activity_stats WHERE user_id=? AND activity_key=?",
            (user_id, key)
        ).fetchone()
        if stats and stats["last_completed"]:
            try:
                last = datetime.fromisoformat(stats["last_completed"])
                remaining = int(activity["cooldown"] - (now - last).total_seconds())
            except (TypeError, ValueError):
                remaining = 0
            if remaining > 0:
                db.rollback()
                minutes = max(1, (remaining + 59) // 60)
                await callback.answer(f"Эта работа пока недоступна. Подожди примерно {minutes} мин.", show_alert=True)
                return
        daily = db.execute(
            "SELECT COUNT(*) AS runs, COALESCE(SUM(amount),0) AS earned "
            "FROM bank_transactions WHERE user_id=? AND transaction_type='work_reward' "
            "AND substr(created_at,1,10)=?",
            (user_id, today)
        ).fetchone()
        if daily["runs"] >= SIDE_ACTIVITY_DAILY_LIMIT or daily["earned"] >= SIDE_ACTIVITY_DAILY_EARNINGS_LIMIT:
            db.rollback()
            await callback.answer("На сегодня лимит подработок исчерпан.", show_alert=True)
            return
        cur = db.execute(
            "INSERT INTO side_activity_sessions(user_id,activity_key,status,created_at) VALUES(?,?,'accepted',?)",
            (user_id, key, now_text())
        )
        session_id = cur.lastrowid
        db.commit()
    except sqlite3.Error:
        if db.in_transaction:
            db.rollback()
        log.exception("Ошибка принятия гражданского заказа")
        await callback.answer("Не удалось принять заказ. Попробуй позже.", show_alert=True)
        return
    await callback.answer("Заказ принят.", show_alert=True)
    await callback.message.answer(
        f"📋 **Заказ №{session_id}: {activity['name']}**\n\n"
        f"{activity['description']}\n\n"
        "Когда прибудешь на место, нажми «Приехал». Оплата будет доступна только после выполнения всех этапов.",
        parse_mode="Markdown",
        reply_markup=side_job_stage_keyboard(session_id, "accepted", key)
    )


