@dp.message(NewsFlow.text, F.text)
async def news_submission_body(message: Message, state: FSMContext):
    player = get_player(message.from_user.id)
    if not player or player["faction"] != "СМИ" or player["rank"] not in FACTIONS["СМИ"]["ranks"]:
        await state.clear()
        await message.answer("Ты больше не состоишь в СМИ. Материал не отправлен.")
        return
    body = (message.text or "").strip()
    if not 80 <= len(body) <= 3000:
        await message.answer("Текст должен содержать от 80 до 3000 символов.")
        return
    data = await state.get_data()
    title = str(data.get("news_title", "")).strip()
    try:
        begin_immediate()
        cur = db.execute(
            "INSERT INTO news_submissions(author_id,faction,title,body,status,created_at) "
            "VALUES(?, 'СМИ', ?, ?, 'На проверке', ?)",
            (message.from_user.id, title, body, now_text())
        )
        submission_id = cur.lastrowid
        db.commit()
    except sqlite3.Error:
        if db.in_transaction:
            db.rollback()
        log.exception("Не удалось сохранить материал СМИ")
        await message.answer("Не удалось сохранить материал. Попробуй позже.")
        await state.clear()
        return
    await state.clear()
    await message.answer(f"Материал №{submission_id} отправлен редакторам. Публикации пока нет — дождись решения.")
    keyboard = InlineKeyboardMarkup(inline_keyboard=[[
        InlineKeyboardButton(text="Открыть материал", callback_data=f"newsreview:view:{submission_id}")
    ]])
    delivered = 0
    for editor_id in _news_editor_ids(message.from_user.id):
        try:
            await message.bot.send_message(
                editor_id,
                f"📰 Новый материал №{submission_id}\nАвтор: {player_display_name(player)}\nЗаголовок: {title}",
                reply_markup=keyboard
            )
            delivered += 1
        except Exception:
            log.exception("Не удалось уведомить редактора СМИ %s", editor_id)
    if not delivered:
        await message.answer("Материал сохранён в редакционной очереди. Сейчас нет доступных редакторов; директор может проверить его через /news_review.")


