@dp.message(NewsReviewFlow.note, F.text)
async def news_review_note_finish(message: Message, state: FSMContext):
    actor = get_player(message.from_user.id)
    if not _is_news_editor(actor) and not is_admin(message.from_user.id):
        await state.clear()
        await message.answer("Редакционные полномочия отсутствуют. Решение не сохранено.")
        return
    note = (message.text or "").strip()
    if not 10 <= len(note) <= 1000:
        await message.answer("Замечание должно содержать от 10 до 1000 символов.")
        return
    data = await state.get_data()
    submission_id = int(data.get("news_submission_id", 0))
    try:
        begin_immediate()
        cur = db.execute(
            "UPDATE news_submissions SET status='На доработке',editor_id=?,editor_note=?,reviewed_at=? "
            "WHERE id=? AND status IN ('На проверке','На доработке')",
            (message.from_user.id, note, now_text(), submission_id)
        )
        if cur.rowcount != 1:
            db.rollback()
            await state.clear()
            await message.answer("Материал уже обработан или не найден.")
            return
        row = db.execute("SELECT author_id,title FROM news_submissions WHERE id=?", (submission_id,)).fetchone()
        db.commit()
    except sqlite3.Error:
        if db.in_transaction:
            db.rollback()
        log.exception("Не удалось вернуть материал СМИ на доработку")
        await message.answer("Не удалось сохранить замечания.")
        await state.clear()
        return
    await state.clear()
    await message.answer(f"Материал №{submission_id} возвращён автору на доработку.")
    try:
        await message.bot.send_message(
            row["author_id"],
            f"Материал №{submission_id} «{row['title']}» возвращён на доработку.\nЗамечания редактора: {note}\nПосле исправления отправь /news_resubmit {submission_id}."
        )
    except Exception:
        log.exception("Не удалось уведомить автора о доработке материала")


@dp.message(Command("news_resubmit"))
async def news_resubmit_start(message: Message, state: FSMContext):
    parts = (message.text or "").split()
    if len(parts) != 2 or not parts[1].isdigit():
        await message.answer("Формат: /news_resubmit ID_материала")
        return
    submission_id = int(parts[1])
    row = db.execute(
        "SELECT id,title FROM news_submissions WHERE id=? AND author_id=? AND status='На доработке'",
        (submission_id, message.from_user.id)
    ).fetchone()
    if not row:
        await message.answer("Материал не найден, не принадлежит тебе или не ожидает доработки.")
        return
    await state.clear()
    await state.update_data(news_submission_id=submission_id)
    await state.set_state(NewsFlow.resubmit)
    await message.answer(f"Отправь исправленную версию материала «{row['title']}» (80–3000 символов). Для отмены: /cancel.")


@dp.message(NewsFlow.resubmit, F.text)
async def news_resubmit_finish(message: Message, state: FSMContext):
    current_player = get_player(message.from_user.id)
    if not current_player or current_player["faction"] != "СМИ" or current_player["rank"] not in FACTIONS["СМИ"]["ranks"]:
        await state.clear()
        await message.answer("Исправленную версию может отправить только действующий сотрудник СМИ.")
        return
    body = (message.text or "").strip()
    if not 80 <= len(body) <= 3000:
        await message.answer("Исправленный текст должен содержать от 80 до 3000 символов.")
        return
    data = await state.get_data()
    submission_id = int(data.get("news_submission_id", 0))
    try:
        begin_immediate()
        cur = db.execute(
            "UPDATE news_submissions SET body=?,status='На проверке',editor_id=0,editor_note='',reviewed_at='' "
            "WHERE id=? AND author_id=? AND status='На доработке'",
            (body, submission_id, message.from_user.id)
        )
        if cur.rowcount != 1:
            db.rollback()
            await state.clear()
            await message.answer("Материал уже изменён или не ожидает доработки.")
            return
        row = db.execute("SELECT title FROM news_submissions WHERE id=?", (submission_id,)).fetchone()
        db.commit()
    except sqlite3.Error:
        if db.in_transaction:
            db.rollback()
        log.exception("Не удалось повторно отправить материал СМИ")
        await state.clear()
        await message.answer("Не удалось отправить исправленную версию.")
        return
    await state.clear()
    await message.answer("Исправленная версия снова отправлена на проверку.")
    keyboard = InlineKeyboardMarkup(inline_keyboard=[[
        InlineKeyboardButton(text="Открыть материал", callback_data=f"newsreview:view:{submission_id}")
    ]])
    for editor_id in _news_editor_ids(message.from_user.id):
        try:
            await message.bot.send_message(editor_id, f"📰 Исправленная версия №{submission_id}: {row['title']}", reply_markup=keyboard)
        except Exception:
            log.exception("Не удалось уведомить редактора о повторной отправке")


