@dp.callback_query(F.data == "settings:toggle")
async def phone_settings_toggle(callback: CallbackQuery):
    user_id = callback.from_user.id
    create_player(user_id)

    row = db.execute(
        """
        SELECT notifications FROM phone_settings
        WHERE user_id = ?
        """,
        (user_id,)
    ).fetchone()

    current = bool(row and row["notifications"])
    new_value = 0 if current else 1

    db.execute(
        """
        UPDATE phone_settings
        SET notifications = ?
        WHERE user_id = ?
        """,
        (new_value, user_id)
    )
    db.commit()

    await callback.answer(
        "Настройки сохранены."
    )

    await callback.message.edit_text(
        "⚙️ Настройки телефона\n\n"
        f"Уведомления: {'включены' if new_value else 'выключены'}"
    )


def _vip_display(user_id):
    row = db.execute("SELECT tier,expires_at FROM player_vip WHERE user_id=?", (user_id,)).fetchone()
    if not row:
        return "нет"
    if row["expires_at"]:
        try:
            if datetime.fromisoformat(row["expires_at"]) <= datetime.now():
                db.execute("DELETE FROM player_vip WHERE user_id=?", (user_id,))
                db.commit()
                return "нет"
        except ValueError:
            return "нет"
    icon = {"VIP": "⭐", "Premium": "💎", "Elite": "👑"}.get(row["tier"], "")
    return f"{icon} {row['tier']} · до {row['expires_at'][:10]}"


