@dp.message(Command("vip_set"))
async def admin_vip_set_command(message: Message):
    if not is_admin(message.from_user.id):
        await message.answer("Команда доступна только администрации.")
        return
    parts = (message.text or "").split()
    if len(parts) not in (3, 4) or not parts[1].isdigit():
        await message.answer("Формат: /vip_set GAME_ID VIP|Premium|Elite [дней]")
        return
    tier = parts[2].capitalize()
    if tier not in ("Vip", "Premium", "Elite"):
        await message.answer("Доступные уровни: VIP, Premium, Elite.")
        return
    tier = "VIP" if tier == "Vip" else tier
    days = 30
    if len(parts) == 4:
        if not parts[3].isdigit():
            await message.answer("Срок должен быть числом дней от 1 до 365.")
            return
        days = int(parts[3])
    if not 1 <= days <= 365:
        await message.answer("Срок должен быть от 1 до 365 дней.")
        return
    target = get_player_by_game_id(parts[1])
    if not target:
        await message.answer("Персонаж с таким игровым ID не найден.")
        return
    expires = (datetime.now() + timedelta(days=days)).isoformat(timespec="seconds")
    db.execute(
        "INSERT INTO player_vip(user_id,tier,granted_by,granted_at,expires_at) VALUES(?,?,?,?,?) "
        "ON CONFLICT(user_id) DO UPDATE SET tier=excluded.tier,granted_by=excluded.granted_by,granted_at=excluded.granted_at,expires_at=excluded.expires_at",
        (target["user_id"], tier, message.from_user.id, now_text(), expires)
    )
    db.commit()
    audit_admin_action(message.from_user.id, int(target["user_id"]), "VIP_SET", f"{tier}|{days} days")
    await message.answer(f"✨ Персонажу {player_display_name(target)} назначен косметический статус {tier} на {days} дней.")


