@dp.message(Command("edu"))
async def admin_education_handler(message: Message):
    if not is_admin(message.from_user.id):
        await message.answer("❌ Нет доступа.")
        return
    parts = (message.text or "").split(maxsplit=2)
    if len(parts) != 3 or not parts[1].isdigit():
        await message.answer("Формат: /edu GAME_ID уровень\nУровни: Нет, Общее, Среднее, Профессиональное, Высшее")
        return
    target, education = get_player_by_game_id(parts[1]), parts[2].strip().replace("_", " ")
    if not target:
        await message.answer("Персонаж с таким игровым ID не найден.")
        return
    target_id = int(target["user_id"])
    if education not in EDUCATION_LEVELS:
        await message.answer("Неизвестный уровень образования.")
        return
    db.execute("UPDATE players SET education = ? WHERE user_id = ?", (education, target_id))
    db.commit()
    audit_admin_action(message.from_user.id, target_id, "EDUCATION", education)
    await message.answer(f"🎓 Персонажу {player_display_name(target)} установлено образование: {education}.")


@dp.message(Command("uniexam_status"))
async def admin_university_exam_status(message: Message):
    if not is_admin(message.from_user.id):
        await message.answer("Команда доступна только администрации.")
        return
    rows = db.execute(
        "SELECT r.user_id,p.name,p.game_id,r.score,r.passed,r.taken_at FROM university_express_results r "
        "LEFT JOIN players p ON p.user_id=r.user_id ORDER BY r.id DESC LIMIT 30"
    ).fetchall()
    if not rows:
        await message.answer("Попыток единого экспресс-экзамена пока нет.")
        return
    lines = ["📊 РЕЗУЛЬТАТЫ ЕДИНОГО ЭКСПРЕСС-ЭКЗАМЕНА"]
    lines.extend(
        f"{player_display_name(row, 'Персонаж')} · {row['score']}/7 · {'сдан' if row['passed'] else 'не сдан'} · {row['taken_at']}"
        for row in rows
    )
    await message.answer("\n".join(lines))


@dp.message(Command("uniexam_reset"))
async def admin_university_exam_reset(message: Message):
    if not is_admin(message.from_user.id):
        await message.answer("Команда доступна только администрации.")
        return
    parts = (message.text or "").split()
    if len(parts) != 2 or not parts[1].isdigit():
        await message.answer("Формат: /uniexam_reset GAME_ID")
        return
    target = get_player_by_game_id(parts[1])
    if not target:
        await message.answer("Персонаж с таким игровым ID не найден.")
        return
    target_id = int(target["user_id"])
    try:
        begin_immediate()
        db.execute("DELETE FROM university_express_results WHERE user_id=?", (target_id,))
        db.execute("DELETE FROM university_tests WHERE user_id=?", (target_id,))
        db.execute("UPDATE university_final SET score=0,passed=0,taken_at=? WHERE user_id=?", (now_text(), target_id))
        db.execute("UPDATE players SET education='Нет' WHERE user_id=? AND education='Высшее'", (target_id,))
        db.commit()
    except sqlite3.Error:
        if db.in_transaction:
            db.rollback()
        log.exception("Не удалось сбросить результаты университетского экзамена")
        await message.answer("Не удалось сбросить экзаменационные результаты.")
        return
    audit_admin_action(message.from_user.id, target_id, "UNIVERSITY_EXAM_RESET", "Единый экспресс-экзамен и предметные результаты сброшены")
    await message.answer(f"Результаты экзаменов персонажа {player_display_name(target)} сброшены.")


@dp.message(Command("adminlog"))
async def admin_log_handler(message: Message):
    if not is_admin(message.from_user.id):
        await message.answer("❌ Нет доступа.")
        return
    parts = (message.text or "").split()
    limit = 10
    if len(parts) > 1 and parts[1].isdigit():
        limit = max(1, min(int(parts[1]), 30))
    rows = db.execute(
        "SELECT admin_id, target_id, action, details, created_at "
        "FROM admin_audit ORDER BY id DESC LIMIT ?",
        (limit,)
    ).fetchall()
    if not rows:
        await message.answer("Журнал действий пока пуст.")
        return
    output = ["🧾 Журнал действий администраторов:"]
    for row in rows:
        output.append(
            f"• {row['created_at']} | {player_display_name(get_player(row['admin_id']), 'Администратор системы')} → "
            f"{player_display_name(get_player(row['target_id']), 'Персонаж')} | {row['action']} {row['details']}"
        )
    await message.answer("\n".join(output))


