# Normalize employment labels from early University builds to the shared career-history vocabulary.
db.execute("UPDATE employment_history SET action='Приём' WHERE faction='Университет' AND action IN ('Назначен','Принят на работу') AND (ended_at IS NULL OR ended_at='')")
db.commit()

def _employment_experience(user_id):
    rows=db.execute("SELECT faction,started_at,ended_at FROM employment_history WHERE user_id=? AND action IN ('Приём','Перевод','Увольнение')",(user_id,)).fetchall()
    distinct={r['faction'] for r in rows if r['ended_at']}
    days=0
    for r in rows:
        if r['started_at'] and r['ended_at']:
            try: days += max(0,(datetime.fromisoformat(r['ended_at'])-datetime.fromisoformat(r['started_at'])).days)
            except Exception: log.debug("Optional notification or fallback failed", exc_info=True)
    return len(distinct),days


