@dp.callback_query(F.data.startswith("hmed:treat:"))
async def hospital_sanitary_treat_patient(callback: CallbackQuery):
    sanitary=get_player(callback.from_user.id)
    try: _,_,target_raw,condition=callback.data.split(":"); target_id=int(target_raw)
    except (ValueError,IndexError): await callback.answer("Некорректная медицинская запись.",show_alert=True); return
    if condition not in ("fractures","cold"):
        await callback.answer("Тип лечения не распознан.",show_alert=True); return
    target=get_player(target_id)
    if not sanitary or sanitary["faction"]!="Больница" or sanitary["rank"]!="Санитар" or sanitary["location"]!="Больница":
        await callback.answer("Лечить пациентов может только санитар, находящийся в больнице.",show_alert=True); return
    if not target or target["location"]!="Больница":
        await callback.answer("Пациент уже покинул больницу.",show_alert=True); return
    changed=db.execute(f"UPDATE documents SET {condition}=0 WHERE user_id=? AND {condition}<>0",(target_id,))
    if changed.rowcount!=1:
        await callback.answer("Это состояние уже снято или запись изменилась.",show_alert=True); return
    db.execute("INSERT INTO medical_treatment_history(user_id,treated_by,condition_key,created_at) VALUES(?,?,?,?)",(target_id,callback.from_user.id,condition,now_text())); db.commit()
    label="травма" if condition=="fractures" else "простуда"
    await callback.answer("Лечение отмечено.")
    try: await callback.bot.send_message(target_id,f"🏥 Санитар {player_display_name(sanitary)} оказал помощь в больнице. Отметка «{label}» снята.")
    except Exception: log.debug("Optional notification or fallback failed", exc_info=True)
    await callback.message.answer(f"✅ Помощь пациенту {player_display_name(target)} оказана. Состояние «{label}» отмечено как устранённое.")


@dp.message(FactionPhoneState.wanted_target,F.text)
async def faction_wanted_target_input(message:Message,state:FSMContext):
    value=message.text.strip()
    if not value.isdigit(): await message.answer("Нужен числовой игровой ID персонажа."); return
    target=get_player_by_game_id(value)
    if not target: await message.answer("Персонаж с таким игровым ID не найден."); return
    target_id=int(target["user_id"]); actor=get_player(message.from_user.id)
    if not target or target_id==message.from_user.id: await message.answer("Персонаж не найден или выбран неверно."); return
    if not actor or actor["faction"] not in ("ЦПД","ФБР"): await state.clear(); await message.answer("Нет доступа к реестру розыска."); return
    await state.update_data(wanted_target=target_id); await state.set_state(FactionPhoneState.wanted_reason); await message.answer(f"Цель: {player_display_name(target)} · {target['faction']}. Укажи игровое основание для розыска:")


@dp.message(FactionPhoneState.wanted_reason,F.text)
async def faction_wanted_reason_input(message:Message,state:FSMContext):
    actor=get_player(message.from_user.id); data=await state.get_data(); target_id=int(data['wanted_target']); target=get_player(target_id); reason=message.text.strip()
    if not actor or actor["faction"] not in ("ЦПД","ФБР") or not target or len(reason)<5: await state.clear(); await message.answer("Не удалось оформить розыск: проверь данные и доступ."); return
    db.execute("INSERT INTO player_wanted(user_id,faction,wanted_level,reason,issued_by,active,created_at) VALUES(?,?,1,?,?,1,?) ON CONFLICT(user_id) DO UPDATE SET faction=excluded.faction,wanted_level=MIN(5,player_wanted.wanted_level+1),reason=excluded.reason,issued_by=excluded.issued_by,active=1,created_at=excluded.created_at",(target_id,actor['faction'],reason,message.from_user.id,now_text()))
    db.execute("INSERT INTO reports(user_id,text,created_at) VALUES(?,?,?)",(message.from_user.id,f"Игровой розыск персонажа {player_display_name(target)}: {reason}",now_text())); db.commit(); await state.clear()
    row=db.execute("SELECT wanted_level FROM player_wanted WHERE user_id=?",(target_id,)).fetchone()
    await message.answer(f"🚨 Игровой розыск оформлен. Уровень: {row['wanted_level']}/5. Запись сохранена.")
    try: await message.bot.send_message(target_id,f"🚨 Твой персонаж получил игровой розыск уровня {row['wanted_level']}/5. Основание: {reason}")
    except Exception: log.debug("Optional notification or fallback failed", exc_info=True)


@dp.message(Command("election_start"))
async def governor_election_start_command(message: Message):
    if not is_admin(message.from_user.id):
        await message.answer("Открывать выборы губернатора может только администрация.")
        return
    parts = (message.text or "").split()
    hours = int(parts[1]) if len(parts) == 2 and parts[1].isdigit() else 48
    if not 1 <= hours <= 168:
        await message.answer("Срок приёма заявок: от 1 до 168 часов. Формат: /election_start [часы]")
        return
    active = db.execute("SELECT id,status FROM governor_elections WHERE status IN ('Приём заявок','Голосование') ORDER BY id DESC LIMIT 1").fetchone()
    if active:
        await message.answer(f"Уже идут выборы №{active['id']} ({active['status']}).")
        return
    opened = datetime.now()
    closes = opened + timedelta(hours=hours)
    cur = db.execute("INSERT INTO governor_elections(status,created_by,opened_at,closes_at) VALUES('Приём заявок',?,?,?)", (message.from_user.id, opened.isoformat(timespec='seconds'), closes.isoformat(timespec='seconds')))
    db.commit()
    await message.answer(f"🗳 Выборы губернатора №{cur.lastrowid} открыты. Приём заявок продлится {hours} ч. Подать кандидатуру: /governor_apply программа")


@dp.message(Command("governor_apply"))
async def governor_candidate_apply_command(message: Message):
    player = get_player(message.from_user.id)
    statement = (message.text or "").partition(" ")[2].strip()
    election = db.execute("SELECT * FROM governor_elections WHERE status='Приём заявок' ORDER BY id DESC LIMIT 1").fetchone()
    if not election or datetime.fromisoformat(election["closes_at"]) <= datetime.now():
        await message.answer("Сейчас приём кандидатур на пост губернатора закрыт.")
        return
    if not player or player["banned"] or not player["passport"] or not player["medcard"] or not player["labor_book"]:
        await message.answer("Для кандидатуры нужны действующий персонаж, паспорт, медкарта и трудовая книжка; заблокированные персонажи не допускаются.")
        return
    if int(player["age"] or 0) < 18 or int(player["level"] or 1) < 3 or int(player["lawfulness"] or 0) < 70:
        await message.answer("Требования: возраст персонажа от 18 лет, уровень не ниже 3 и законопослушность не ниже 70.")
        return
    jail = db.execute("SELECT 1 FROM player_punishments WHERE user_id=? AND punishment_type='JAIL' AND active=1 LIMIT 1", (message.from_user.id,)).fetchone()
    if jail:
        await message.answer("Персонаж в игровом заключении и не может выдвигаться.")
        return
    if len(statement) < 30 or len(statement) > 1000:
        await message.answer("Напиши программу кандидата объёмом от 30 до 1000 символов. Формат: /governor_apply текст")
        return
    try:
        db.execute("INSERT INTO governor_candidates(election_id,user_id,statement,status) VALUES(?,?,?,'На проверке')", (election["id"], message.from_user.id, statement))
        db.commit()
    except sqlite3.IntegrityError:
        await message.answer("Ты уже подал кандидатуру на этих выборах.")
        return
    await message.answer(f"📨 Кандидатура на выборы №{election['id']} отправлена администрации на проверку.")
    for admin_id in ADMIN_IDS:
        try:
            await message.bot.send_message(admin_id, f"🗳 Новая кандидатура губернатора · выборы №{election['id']}\nКандидат: {player_display_name(player)}\nПрограмма: {statement[:800]}\nРассмотрение: /election_review")
        except Exception:
            log.debug("Не удалось уведомить администратора о кандидатуре", exc_info=True)


@dp.message(Command("election_review"))
async def governor_election_review_command(message: Message):
    if not is_admin(message.from_user.id):
        await message.answer("Рассматривать кандидатуры может только администрация.")
        return
    rows = db.execute("SELECT c.id,c.election_id,c.user_id,c.statement FROM governor_candidates c JOIN governor_elections e ON e.id=c.election_id WHERE c.status='На проверке' AND e.status='Приём заявок' ORDER BY c.id").fetchall()
