def _governor_candidate_eligible_now(user_id: int) -> bool:
    """Повторная проверка требований к кандидату непосредственно перед итогами выборов."""
    candidate = get_player(int(user_id))
    if (
        not candidate
        or candidate["banned"]
        or not candidate["passport"]
        or not candidate["medcard"]
        or not candidate["labor_book"]
        or int(candidate["age"] or 0) < 18
        or int(candidate["level"] or 1) < 3
        or int(candidate["lawfulness"] or 0) < 70
    ):
        return False
    return not db.execute(
        "SELECT 1 FROM player_punishments WHERE user_id=? AND punishment_type='JAIL' AND active=1 LIMIT 1",
        (int(user_id),)
    ).fetchone()


def _remove_ineligible_governor_candidates(election_id: int) -> int:
    """Снимает кандидатов, переставших соответствовать условиям после допуска."""
    rows = db.execute(
        "SELECT id,user_id FROM governor_candidates WHERE election_id=? AND status='Допущен'",
        (int(election_id),)
    ).fetchall()
    removed = 0
    for row in rows:
        if not _governor_candidate_eligible_now(int(row["user_id"])):
            changed = db.execute(
                "UPDATE governor_candidates SET status='Снят: требования' WHERE id=? AND status='Допущен'",
                (row["id"],)
            )
            removed += max(0, changed.rowcount)
    if removed:
        db.commit()
    return removed


async def governor_election_maintenance_loop(bot_obj):
    """Автоматически подводит итоги выборов после окончания срока голосования."""
    while True:
        try:
            expired = db.execute(
                "SELECT * FROM governor_elections WHERE status='Голосование' ORDER BY id"
            ).fetchall()
            for election in expired:
                try:
                    deadline = datetime.fromisoformat(election["closes_at"])
                except (TypeError, ValueError):
                    log.warning("Некорректный срок выборов губернатора №%s", election["id"])
                    continue
                if deadline > datetime.now():
                    continue
                _remove_ineligible_governor_candidates(int(election["id"]))
                results = db.execute(
                    """SELECT c.id,c.user_id,COUNT(v.id) AS votes
                       FROM governor_candidates c
                       LEFT JOIN governor_votes v ON v.candidate_id=c.id AND v.election_id=c.election_id
                       WHERE c.election_id=? AND c.status='Допущен'
                       GROUP BY c.id,c.user_id ORDER BY votes DESC,c.id""",
                    (election["id"],)
                ).fetchall()
                if not results:
                    changed = db.execute(
                        "UPDATE governor_elections SET status='Завершены',closed_at=? WHERE id=? AND status='Голосование'",
                        (now_text(), election["id"])
                    )
                    db.commit()
                    if changed.rowcount:
                        log.info("Выборы губернатора №%s завершены без допущенных кандидатов", election["id"])
                    continue
                top_votes = int(results[0]["votes"])
                tied = [row for row in results if int(row["votes"]) == top_votes]
                if len(tied) != 1:
                    changed = db.execute(
                        "UPDATE governor_elections SET status='Завершены: ничья',closed_at=? WHERE id=? AND status='Голосование'",
                        (now_text(), election["id"])
                    )
                    db.commit()
                    if changed.rowcount:
                        voters = db.execute("SELECT DISTINCT voter_id FROM governor_votes WHERE election_id=?", (election["id"],)).fetchall()
                        for voter in voters:
                            try:
                                await bot_obj.send_message(voter["voter_id"], f"🗳 Выборы губернатора №{election['id']} завершились ничьей. Администрация объявит повторное голосование.")
                            except Exception:
                                log.debug("Не удалось уведомить участника о ничьей на выборах", exc_info=True)
                    continue
                winner_id = int(results[0]["user_id"])
                old_id = 0
                try:
                    begin_immediate()
                    current = db.execute("SELECT status FROM governor_elections WHERE id=?", (election["id"],)).fetchone()
                    if not current or current["status"] != "Голосование":
                        db.rollback()
                        continue
                    old_governor = db.execute(
                        "SELECT user_id FROM players WHERE faction='Мэрия' AND rank='Губернатор' AND user_id<>? ORDER BY user_id LIMIT 1",
                        (winner_id,)
                    ).fetchone()
                    if old_governor:
                        old_id = int(old_governor["user_id"])
                        db.execute("UPDATE players SET rank='Вице-губернатор' WHERE user_id=? AND faction='Мэрия' AND rank='Губернатор'", (old_id,))
                        db.execute("UPDATE faction_membership SET rank='Вице-губернатор' WHERE user_id=? AND faction='Мэрия' AND (left_at IS NULL OR left_at='')", (old_id,))
                        db.execute("UPDATE employment_history SET rank='Вице-губернатор' WHERE user_id=? AND faction='Мэрия' AND (ended_at IS NULL OR ended_at='')", (old_id,))
                    winner = get_player(winner_id)
                    if not winner or not _governor_candidate_eligible_now(winner_id):
                        db.execute(
                            "UPDATE governor_candidates SET status='Снят: требования' WHERE election_id=? AND user_id=? AND status='Допущен'",
                            (election["id"], winner_id)
                        )
                        db.execute("UPDATE governor_elections SET status='Завершены: победитель недоступен',closed_at=? WHERE id=? AND status='Голосование'", (now_text(), election["id"]))
                        db.commit()
                        continue
                    old_faction = winner["faction"]
                    if old_faction in FACTIONS:
                        _close_faction_membership(winner_id, old_faction, "Избрание губернатором", int(election["created_by"] or 0), now_text())
                    db.execute("UPDATE players SET faction='Мэрия',rank='Губернатор',labor_book=1 WHERE user_id=?", (winner_id,))
                    db.execute("INSERT INTO faction_membership(user_id,faction,rank,joined_at) VALUES(?,?,?,?)", (winner_id, "Мэрия", "Губернатор", now_text()))
                    db.execute("INSERT INTO employment_history(user_id,faction,rank,action,started_at,actor_id,created_at) VALUES(?,?,?,?,?,?,?)", (winner_id, "Мэрия", "Губернатор", "Избран", now_text(), int(election["created_by"] or 0), now_text()))
                    _cancel_other_applications(winner_id, "Мэрия", now_text())
                    db.execute("UPDATE governor_candidates SET status=CASE WHEN user_id=? THEN 'Победитель' ELSE 'Не избран' END WHERE election_id=? AND status='Допущен'", (winner_id, election["id"]))
                    db.execute("UPDATE governor_elections SET status='Завершены',closed_at=?,winner_id=? WHERE id=? AND status='Голосование'", (now_text(), winner_id, election["id"]))
                    db.commit()
                except sqlite3.Error:
                    if db.in_transaction:
                        db.rollback()
                    log.exception("Не удалось автоматически завершить выборы губернатора №%s", election["id"])
                    continue
                winner = get_player(winner_id)
                try:
                    await bot_obj.send_message(winner_id, f"🏆 Поздравляем! По итогам голосования ты {gender_form(winner, 'набрал', 'набрала')} {top_votes} голосов и автоматически {gender_form(winner, 'назначен', 'назначена')} губернатором штата RPM WEST.", reply_markup=main_keyboard(winner))
                except Exception:
                    log.debug("Не удалось уведомить победителя автоматических выборов", exc_info=True)
                if old_id:
                    try:
                        await bot_obj.send_message(old_id, "Срок твоих полномочий губернатора завершён. По итогам выборов ты переведён на должность вице-губернатора.")
                    except Exception:
                        log.debug("Не удалось уведомить прежнего губернатора", exc_info=True)
                voters = db.execute("SELECT DISTINCT voter_id FROM governor_votes WHERE election_id=?", (election["id"],)).fetchall()
                for voter in voters:
                    try:
                        await bot_obj.send_message(voter["voter_id"], f"🗳 Выборы губернатора №{election['id']} завершены. Победитель: {player_display_name(winner)} ({top_votes} голосов).")
                    except Exception:
                        log.debug("Не удалось уведомить избирателя об итогах выборов", exc_info=True)
        except asyncio.CancelledError:
            raise
        except Exception:
            log.exception("Ошибка фонового завершения выборов губернатора")
        await asyncio.sleep(30)


@dp.message(Command("election_close"))
async def governor_election_close_command(message: Message):
    if not is_admin(message.from_user.id):
        await message.answer("Завершать выборы может только администрация.")
        return
    election = db.execute("SELECT * FROM governor_elections WHERE status='Голосование' ORDER BY id DESC LIMIT 1").fetchone()
    if not election:
        await message.answer("Активное голосование не найдено.")
        return
    if datetime.fromisoformat(election["closes_at"]) > datetime.now():
        await message.answer("Срок голосования ещё не закончился.")
        return
    _remove_ineligible_governor_candidates(int(election["id"]))
    results = db.execute("SELECT c.id,c.user_id,COUNT(v.id) AS votes FROM governor_candidates c LEFT JOIN governor_votes v ON v.candidate_id=c.id AND v.election_id=c.election_id WHERE c.election_id=? AND c.status='Допущен' GROUP BY c.id,c.user_id ORDER BY votes DESC,c.id", (election["id"],)).fetchall()
    if not results:
        db.execute("UPDATE governor_elections SET status='Завершены',closed_at=? WHERE id=?", (now_text(), election["id"]))
        db.commit()
        await message.answer("Выборы завершены: допущенных кандидатов нет.")
        return
    top_votes = int(results[0]["votes"])
    tied = [r for r in results if int(r["votes"]) == top_votes]
    if len(tied) != 1:
        db.execute("UPDATE governor_elections SET status='Завершены: ничья',closed_at=? WHERE id=?", (now_text(), election["id"]))
        db.commit()
        await message.answer("🗳 Выборы завершены с равным количеством голосов. Администрации нужно назначить повторное голосование.")
        return
    winner_id = int(results[0]["user_id"])
    try:
        begin_immediate()
        old_governor = db.execute("SELECT user_id FROM players WHERE faction='Мэрия' AND rank='Губернатор' AND user_id<>? ORDER BY user_id LIMIT 1", (winner_id,)).fetchone()
        if old_governor:
            old_id = int(old_governor["user_id"])
            db.execute("UPDATE players SET rank='Вице-губернатор' WHERE user_id=? AND faction='Мэрия' AND rank='Губернатор'", (old_id,))
            db.execute("UPDATE faction_membership SET rank='Вице-губернатор' WHERE user_id=? AND faction='Мэрия' AND (left_at IS NULL OR left_at='')", (old_id,))
            db.execute("UPDATE employment_history SET rank='Вице-губернатор' WHERE user_id=? AND faction='Мэрия' AND (ended_at IS NULL OR ended_at='')", (old_id,))
        winner = get_player(winner_id)
        if not winner or not _governor_candidate_eligible_now(winner_id):
            db.rollback()
            await message.answer("Победитель больше не соответствует требованиям. Кандидатура снята; запусти повторный подсчёт после проверки списка.")
            return
        old_faction = winner["faction"]
        if old_faction in FACTIONS:
            _close_faction_membership(winner_id, old_faction, "Избрание губернатором", message.from_user.id, now_text())
        db.execute("UPDATE players SET faction='Мэрия',rank='Губернатор',labor_book=1 WHERE user_id=?", (winner_id,))
        db.execute("INSERT INTO faction_membership(user_id,faction,rank,joined_at) VALUES(?,?,?,?)", (winner_id, "Мэрия", "Губернатор", now_text()))
        db.execute("INSERT INTO employment_history(user_id,faction,rank,action,started_at,actor_id,created_at) VALUES(?,?,?,?,?,?,?)", (winner_id, "Мэрия", "Губернатор", "Избран", now_text(), message.from_user.id, now_text()))
        _cancel_other_applications(winner_id, "Мэрия", now_text())
        db.execute("UPDATE governor_candidates SET status='Победитель' WHERE election_id=? AND user_id=?", (election["id"], winner_id))
        db.execute("UPDATE governor_elections SET status='Завершены',closed_at=?,winner_id=? WHERE id=? AND status='Голосование'", (now_text(), winner_id, election["id"]))
        db.commit()
    except sqlite3.Error:
        if db.in_transaction: db.rollback()
        log.exception("Не удалось назначить победителя выборов губернатора")
        await message.answer("Не удалось завершить выборы и назначить победителя. Проверь журнал ошибок.")
        return
    winner = get_player(winner_id)
    await message.answer(f"🏆 Победитель выборов губернатора — {player_display_name(winner)} ({top_votes} голосов). Новый губернатор назначен в Мэрию.")
    try:
        await message.bot.send_message(winner_id, f"🏆 Поздравляем! Ты {gender_form(winner, 'победил', 'победила')} на выборах и {gender_form(winner, 'назначен', 'назначена')} губернатором штата RPM WEST.", reply_markup=main_keyboard(winner))
    except Exception:
        log.debug("Не удалось уведомить победителя выборов", exc_info=True)
    if old_governor:
        try:
            await message.bot.send_message(old_id, "Срок твоих полномочий губернатора завершён. По итогам выборов ты переведён на должность вице-губернатора.")
        except Exception:
            log.debug("Не удалось уведомить прежнего губернатора", exc_info=True)


