@dp.message(Command("givemoney"))
async def admin_givemoney_command(message: Message):
    """Выдача игровой валюты только администратору, с транзакцией и аудитом."""
    admin_id = message.from_user.id
    if not is_admin(admin_id):
        await message.answer("❌ Команда доступна только администрации.")
        return
    parts = (message.text or "").split()
    if len(parts) not in (2, 3) or not parts[1].isdigit() or (len(parts) == 3 and not parts[2].isdigit()):
        await message.answer("Формат: /givemoney СУММА или /givemoney GAME_ID СУММА")
        return
    if len(parts) == 2:
        target_id, amount = admin_id, int(parts[1])
    else:
        target_by_game_id = get_player_by_game_id(int(parts[1]))
        if not target_by_game_id:
            await message.answer("Персонаж с таким игровым ID не найден.")
            return
        target_id, amount = int(target_by_game_id["user_id"]), int(parts[2])
    if amount <= 0 or amount > 1_000_000_000:
        await message.answer("Сумма должна быть от $1 до $1 000 000 000.")
        return
    target = get_player(target_id)
    if not target:
        await message.answer("Персонаж не найден. Сначала игрок должен запустить /start.")
        return
    try:
        begin_immediate()
        if not claim_operation("admin_givemoney"):
            db.rollback()
            await message.answer("Эта операция уже была обработана.")
            return
        changed = db.execute(
            "UPDATE players SET balance=balance+? WHERE user_id=? AND balance<=?",
            (amount, target_id, MAX_BALANCE - amount)
        )
        if changed.rowcount != 1:
            db.rollback()
            await message.answer("Операция отклонена: баланс достиг максимального лимита.")
            return
        db.execute(
            "INSERT INTO bank_transactions(user_id,other_user_id,amount,transaction_type,description,created_at) VALUES(?,0,?,'admin_grant',?,?)",
            (target_id, amount, "Выдача игровой валюты администрацией", now_text())
        )
        db.commit()
    except TransactionConflict:
        await message.answer("Система занята другой операцией. Повтори чуть позже.")
        return
    except Exception:
        if db.in_transaction:
            db.rollback()
        log.exception("Ошибка /givemoney для игрока %s", target_id)
        await message.answer("Не удалось выдать деньги. Ошибка записана в журнал.")
        return
    audit_admin_action(admin_id, target_id, "GIVEMONEY", str(amount))
    await message.answer(f"✅ Начислено {_west_money(amount)} персонажу {player_display_name(target)}.")
    if target_id != admin_id:
        try:
            await message.bot.send_message(target_id, f"💵 Администрация начислила твоему персонажу {_west_money(amount)}.")
        except Exception:
            log.debug("Optional operation failed", exc_info=True)
def _settle_property_taxes(user_id):
    """Начисляет налог за прошедшие календарные дни и списывает доступную часть долга."""
    today = datetime.now().date()
    begin_immediate()
    try:
        rows = db.execute(
            "SELECT o.id,o.tax_debt,o.last_tax_date,o.purchased_at,c.daily_tax,c.name "
            "FROM property_ownership o JOIN property_catalog c ON c.id=o.property_id "
            "WHERE o.user_id=? ORDER BY o.id",
            (user_id,)
        ).fetchall()
        total_debt = 0
        debts = []
        for row in rows:
            try:
                last_day = datetime.fromisoformat(row["last_tax_date"]).date() if row["last_tax_date"] else today
            except (ValueError, TypeError):
                try:
                    last_day = datetime.fromisoformat(row["purchased_at"]).date()
                except (ValueError, TypeError):
                    last_day = today
            days = max(0, (today - last_day).days)
            debt = max(0, int(row["tax_debt"] or 0)) + days * max(0, int(row["daily_tax"] or 0))
            db.execute("UPDATE property_ownership SET tax_debt=?,last_tax_date=? WHERE id=?", (debt, today.isoformat(), row["id"]))
            debts.append((row["id"], debt))
            total_debt += debt
        balance_row = db.execute("SELECT balance FROM players WHERE user_id=?", (user_id,)).fetchone()
        available = max(0, int(balance_row["balance"] if balance_row else 0))
        paid = min(available, total_debt)
        remaining_to_pay = paid
        for ownership_id, debt in debts:
            part = min(debt, remaining_to_pay)
            if part:
                db.execute("UPDATE property_ownership SET tax_debt=tax_debt-? WHERE id=?", (part, ownership_id))
                remaining_to_pay -= part
            if remaining_to_pay <= 0:
                break
        if paid:
            db.execute("UPDATE players SET balance=balance-? WHERE user_id=? AND balance>=?", (paid, user_id, paid))
            db.execute(
                "INSERT INTO bank_transactions(user_id,other_user_id,amount,transaction_type,description,created_at) "
                "VALUES(?,0,?,'property_tax','Ежедневный налог на недвижимость',?)",
                (user_id, paid, now_text())
            )
        remaining = total_debt - paid
        db.commit()
        return paid, remaining
    except Exception:
        if db.in_transaction:
            db.rollback()
        raise


def _settle_all_property_taxes():
    """Фоновое начисление налогов для всех владельцев недвижимости."""
    owners = db.execute("SELECT DISTINCT user_id FROM property_ownership").fetchall()
    for owner in owners:
        try:
            _settle_property_taxes(int(owner["user_id"]))
        except TransactionConflict:
            log.warning("Налог на недвижимость игрока %s отложен: база занята", owner["user_id"])
        except Exception:
            log.exception("Не удалось начислить налог на недвижимость игрока %s", owner["user_id"])


