@dp.callback_query(F.data.startswith("westprop:"))
async def west_property_callback(callback: CallbackQuery):
    user_id = callback.from_user.id
    action = callback.data.split(":", 1)[1]
    if action == "mine":
        rows = db.execute(
            "SELECT o.id AS ownership_id,c.name,c.district,c.kind,c.price,o.tax_debt "
            "FROM property_ownership o JOIN property_catalog c ON c.id=o.property_id WHERE o.user_id=?",
            (user_id,)
        ).fetchall()
        lines = ["🏠 ТВОЯ НЕДВИЖИМОСТЬ"]
        buttons = []
        for row in rows:
            lines.append(f"• {row['name']} — {row['district']}\nНалоговый долг: {_west_money(row['tax_debt'] or 0)}\nПродажа: {_west_money(int(row['price'] * 0.70))}")
            buttons.append([InlineKeyboardButton(text=f"Продать: {row['name']}", callback_data=f"westpropsell:{row['ownership_id']}")])
        if not rows:
            lines.append("Пока нет объектов.")
        await callback.message.answer("\n\n".join(lines), reply_markup=InlineKeyboardMarkup(inline_keyboard=buttons) if buttons else None)
        await callback.answer()
        return
    try:
        property_id = int(action)
    except ValueError:
        await callback.answer("Некорректный объект.", show_alert=True)
        return
    try:
        begin_immediate()
        if not claim_operation("property_purchase"):
            db.rollback()
            await callback.answer("Эта покупка уже обработана.", show_alert=True)
            return
        prop = db.execute("SELECT * FROM property_catalog WHERE id=?", (property_id,)).fetchone()
        player = db.execute("SELECT balance FROM players WHERE user_id=?", (user_id,)).fetchone()
        if not prop or not player:
            db.rollback(); await callback.answer("Объект или персонаж не найден.", show_alert=True); return
        if player["balance"] < prop["price"]:
            db.rollback(); await callback.answer("Недостаточно средств.", show_alert=True); return
        debit = db.execute("UPDATE players SET balance=balance-? WHERE user_id=? AND balance>=?", (prop["price"], user_id, prop["price"]))
        if debit.rowcount != 1:
            db.rollback(); await callback.answer("Недостаточно средств.", show_alert=True); return
        db.execute("INSERT INTO property_ownership(user_id,property_id,purchased_at,last_tax_date) VALUES(?,?,?,?)", (user_id, property_id, now_text(), datetime.now().date().isoformat()))
        _west_log_money(user_id, prop["price"], "property", f"Покупка недвижимости: {prop['name']}")
        db.commit()
    except sqlite3.IntegrityError:
        if db.in_transaction: db.rollback()
        await callback.answer("Этот объект уже куплен другим игроком.", show_alert=True); return
    except TransactionConflict:
        await callback.answer("Система занята другой операцией. Повтори чуть позже.", show_alert=True)
        return
    except Exception:
        if db.in_transaction: db.rollback()
        log.exception("Property purchase failed")
        await callback.answer("Не удалось оформить покупку.", show_alert=True); return
    await callback.answer("Недвижимость приобретена!")
    await callback.message.answer(f"🏠 Поздравляем! Ты приобрёл **{prop['name']}** за {_west_money(prop['price'])}.", parse_mode="Markdown")


@dp.callback_query(F.data.startswith("westpropsell:"))
async def west_property_sell_callback(callback: CallbackQuery):
    try:
        ownership_id = int(callback.data.split(":", 1)[1])
    except (TypeError, ValueError):
        await callback.answer("Объект не найден.", show_alert=True)
        return
    user_id = callback.from_user.id
    try:
        _settle_property_taxes(user_id)
    except (sqlite3.Error, TransactionConflict):
        log.exception("Не удалось обновить налог перед продажей недвижимости")
        await callback.answer("Не удалось проверить налоговую задолженность. Повтори позже.", show_alert=True)
        return
    try:
        begin_immediate()
        if not claim_operation("property_sale"):
            db.rollback(); await callback.answer("Эта продажа уже обработана.", show_alert=True); return
        row = db.execute(
            "SELECT o.id,o.tax_debt,c.name,c.price FROM property_ownership o "
            "JOIN property_catalog c ON c.id=o.property_id WHERE o.id=? AND o.user_id=?",
            (ownership_id, user_id)
        ).fetchone()
        if not row:
            db.rollback(); await callback.answer("Эта недвижимость тебе не принадлежит.", show_alert=True); return
        if int(row["tax_debt"] or 0) > 0:
            db.rollback(); await callback.answer("Сначала погаси налоговую задолженность через /properties.", show_alert=True); return
        amount = int(int(row["price"]) * 0.70)
        balance = db.execute("SELECT balance FROM players WHERE user_id=?", (user_id,)).fetchone()
        if not balance or int(balance["balance"]) > MAX_BALANCE - amount:
            db.rollback(); await callback.answer("Продажа отклонена: превышен лимит игрового баланса.", show_alert=True); return
        changed = db.execute("UPDATE players SET balance=balance+? WHERE user_id=? AND balance<=?", (amount, user_id, MAX_BALANCE - amount))
        if changed.rowcount != 1:
            db.rollback(); await callback.answer("Не удалось зачислить средства.", show_alert=True); return
        db.execute("DELETE FROM property_ownership WHERE id=? AND user_id=?", (ownership_id, user_id))
        db.execute(
            "INSERT INTO bank_transactions(user_id,other_user_id,amount,transaction_type,description,created_at) VALUES(?,0,?,'property_sale',?,?)",
            (user_id, amount, f"Продажа недвижимости: {row['name']}", now_text())
        )
        db.commit()
    except sqlite3.Error:
        if db.in_transaction: db.rollback()
        log.exception("Property sale failed")
        await callback.answer("Не удалось продать недвижимость.", show_alert=True)
        return
    await callback.answer("Недвижимость продана.")
    await callback.message.answer(f"🏠 Объект «{row['name']}» продан за {_west_money(amount)} (70% от каталожной цены).")


