@dp.message(Command("service"))
async def west_service_handler(message: Message):
    rows=db.execute("SELECT id,vehicle_name,condition FROM vehicles WHERE user_id=? ORDER BY id",(message.from_user.id,)).fetchall()
    if not rows: await message.answer("У тебя нет автомобиля."); return
    keyboard=[]
    for row in rows:
        if row["condition"]<100:
            keyboard.append([InlineKeyboardButton(text=f"🔧 {row['vehicle_name']} · {row['condition']}%",callback_data=f"westservice:{row['id']}")])
    await message.answer("🔧 **АВТОСЕРВИС**\nПолное обслуживание стоит $500.",parse_mode="Markdown",reply_markup=InlineKeyboardMarkup(inline_keyboard=keyboard) if keyboard else None)


@dp.callback_query(F.data.startswith("westservice:"))
async def west_service_callback(callback: CallbackQuery):
    try: vehicle_id=int(callback.data.split(":",1)[1])
    except ValueError: await callback.answer("Ошибка.",show_alert=True); return
    uid=callback.from_user.id; cost=500
    try:
        begin_immediate()
        if not claim_operation("vehicle_service"):
            db.rollback(); await callback.answer("Это обслуживание уже обработано.",show_alert=True); return
        row=db.execute("SELECT * FROM vehicles WHERE id=? AND user_id=?",(vehicle_id,uid)).fetchone()
        player=db.execute("SELECT balance FROM players WHERE user_id=?",(uid,)).fetchone()
        if not row or not player: db.rollback(); await callback.answer("Автомобиль не найден.",show_alert=True); return
        if row["condition"]>=100: db.rollback(); await callback.answer("Автомобиль не нуждается в ремонте.",show_alert=True); return
        if player["balance"]<cost: db.rollback(); await callback.answer("Недостаточно денег.",show_alert=True); return
        db.execute("UPDATE players SET balance=balance-? WHERE user_id=? AND balance>=?",(cost,uid,cost))
        db.execute("UPDATE vehicles SET condition=100 WHERE id=? AND user_id=?",(vehicle_id,uid))
        db.execute("INSERT INTO vehicle_service_log(vehicle_id,user_id,service_type,amount,created_at) VALUES(?,?,'repair',?,?)",(vehicle_id,uid,cost,now_text()))
        _west_log_money(uid,cost,"vehicle_service",f"Обслуживание {row['vehicle_name']}")
        db.commit()
    except TransactionConflict:
        await callback.answer("Система занята другой операцией. Повтори чуть позже.", show_alert=True)
        return
    except Exception:
        if db.in_transaction: db.rollback()
        log.exception("Vehicle service transaction failed")
        await callback.answer("Не удалось выполнить обслуживание.",show_alert=True); return
    await callback.answer("Автомобиль обслужен!")
    await callback.message.answer(f"🔧 {row['vehicle_name']} полностью обслужен за {_west_money(cost)}.")




@dp.message(Command("travel"))
async def travel_status_command(message: Message):
    travel = active_player_travel(message.from_user.id)
    if not travel:
        await message.answer("Сейчас ты не находишься в пути.")
        return
    remaining = travel_remaining_seconds(travel)
    mode_text = "пешком" if travel["travel_mode"] == "walk" else f"на автомобиле {travel['vehicle_name']}"
    await message.answer(f"🧭 Маршрут: {travel['origin']} → {travel['destination']}\nСпособ: {mode_text}\nОсталось примерно {max(1, (remaining + 59) // 60)} мин.")


@dp.message(Command("drive"))
@dp.message(F.text == "🚘 Поехать")
async def west_drive_handler(message: Message):
    user_id = message.from_user.id
    create_player(user_id)
    active = active_player_travel(user_id)
    if active:
        remaining = travel_remaining_seconds(active)
        await message.answer(f"Ты уже в пути к «{active['destination']}». Осталось примерно {max(1, (remaining + 59) // 60)} мин.")
        return
    cars = db.execute("SELECT id,vehicle_name,fuel,condition FROM vehicles WHERE user_id=? ORDER BY id", (user_id,)).fetchall()
    if not cars:
        await message.answer("🚘 У тебя нет автомобиля. Купи его в /dealership.")
        return
    current = get_player(user_id)
    destinations = [loc for loc in LOCATIONS if loc != current["location"]]
    buttons = [[InlineKeyboardButton(text=f"📍 {loc}", callback_data=f"drive:{LOCATIONS.index(loc)}")] for loc in destinations]
    await message.answer(f"🚘 Ты находишься: {current['location']}\nВыбери пункт назначения. Поездка расходует топливо и немного изнашивает автомобиль.", reply_markup=InlineKeyboardMarkup(inline_keyboard=buttons))


@dp.callback_query(F.data.startswith("drive:"))
async def west_drive_destination_callback(callback: CallbackQuery):
    try:
        index = int(callback.data.split(":", 1)[1])
        destination = LOCATIONS[index]
    except (ValueError, IndexError):
        await callback.answer("Пункт назначения не найден.", show_alert=True)
        return
    player = get_player(callback.from_user.id)
    if not player:
        await callback.answer("Персонаж не найден.", show_alert=True)
        return
    if destination == player["location"]:
        await callback.answer("Ты уже находишься в этой локации.", show_alert=True)
        return
    cars = db.execute("SELECT id,vehicle_name,fuel,condition FROM vehicles WHERE user_id=? ORDER BY id", (callback.from_user.id,)).fetchall()
    usable = [r for r in cars if int(r["fuel"] or 0) >= 5 and int(r["condition"] or 0) > 0]
    if not usable:
        await callback.answer("Нет исправного автомобиля с минимум 5% топлива. Заправься через /fuel или отремонтируйся через /service.", show_alert=True)
        return
    buttons = [[InlineKeyboardButton(text=f"{r['vehicle_name']} · топливо {r['fuel']}% · состояние {r['condition']}%", callback_data=f"driveto:{r['id']}:{index}")] for r in usable]
    await callback.answer()
    await callback.message.answer(f"🚘 Выбери автомобиль для поездки в «{destination}». Стоимость поездки: 5% топлива и 1% состояния.", reply_markup=InlineKeyboardMarkup(inline_keyboard=buttons))


@dp.callback_query(F.data.startswith("driveto:"))
async def west_drive_execute_callback(callback: CallbackQuery):
    try:
        _, car_raw, destination_raw = callback.data.split(":", 2)
        car_id, destination_index = int(car_raw), int(destination_raw)
        destination = LOCATIONS[destination_index]
    except (ValueError, IndexError):
        await callback.answer("Данные поездки некорректны.", show_alert=True)
        return
    travel, error = begin_player_travel(callback.from_user.id, destination, "vehicle", vehicle_id=car_id)
    if error:
        await callback.answer(error, show_alert=True)
        return
    await callback.answer("Поездка началась!")
    minutes = max(1, (travel["seconds"] + 59) // 60)
    await callback.message.answer(
        f"🚘 Ты выехал из «{travel['origin']}» в «{destination}» на {travel['vehicle_name']}.\n"
        f"Поездка займёт примерно {minutes} мин. Списано 5% топлива и 1% состояния автомобиля."
    )


@dp.message(Command("mybusiness"))
async def west_my_business_command(message: Message):
    rows=db.execute("SELECT pb.id,pb.last_collect,pb.total_income,bc.name,bc.income_per_day FROM player_businesses pb JOIN business_catalog bc ON bc.id=pb.business_id WHERE pb.user_id=?",(message.from_user.id,)).fetchall()
    if not rows: await message.answer("🏢 У тебя нет бизнеса. Каталог: /businesses"); return
    lines=["🏢 Твои предприятия:"]
    keyboard=[]
    for row in rows:
        lines.append(f"• {row['name']} — {_west_money(row['income_per_day'])}/день; всего получено {_west_money(row['total_income'])}")
        keyboard.append([InlineKeyboardButton(text=f"Собрать: {row['name']}",callback_data=f"westbizcollect:{row['id']}")])
    await message.answer("\n".join(lines),reply_markup=InlineKeyboardMarkup(inline_keyboard=keyboard))




