@dp.message(Command("search"))
async def in_game_search_command(message: Message):
    officer = get_player(message.from_user.id)
    parts = (message.text or "").split(maxsplit=2)
    if not _is_police_or_fbi(officer):
        await message.answer("Обыск доступен только сотрудникам ЦПД и ФБР.")
        return
    if len(parts) < 2 or not parts[1].isdigit():
        await message.answer("Формат: /search GAME_ID причина")
        return
    target = get_player_by_game_id(parts[1])
    if not target:
        await message.answer("Персонаж с таким игровым ID не найден.")
        return
    target_id = int(target["user_id"])
    reason = parts[2].strip() if len(parts) > 2 else "Проверка в рамках игрового RP-сценария"
    rows = db.execute("SELECT id, item_name, quantity FROM inventory WHERE user_id=?", (target_id,)).fetchall()
    flagged = [r for r in rows if any(marker in r["item_name"].casefold() for marker in ILLEGAL_GAME_ITEM_MARKERS)]
    if flagged:
        for item in flagged:
            db.execute("DELETE FROM inventory WHERE id=?", (item["id"],))
    db.execute(
        "INSERT INTO reports(user_id, text, created_at) VALUES (?, ?, ?)",
        (message.from_user.id, f"Игровой обыск персонажа {player_display_name(target)}. Причина: {reason}. Изъято игровых предметов: {len(flagged)}.", now_text())
    )
    db.commit()
    details = "\n".join(f"• {r['item_name']} × {r['quantity']}" for r in flagged) if flagged else "Запрещённых игровых предметов не обнаружено."
    await message.answer(f"🔎 Игровой обыск завершён.\nПричина: {reason}\n{details}\nЗапись внесена в служебный журнал.")
    try:
        await message.bot.send_message(target_id, f"В рамках RP-сценария сотрудник {officer['faction']} провёл игровой обыск. Причина: {reason}.\n{details}")
    except Exception:
        log.debug("Optional operation failed", exc_info=True)
@dp.message(Command("parole"))
async def parole_apply_command(message: Message):
    user_id = message.from_user.id
    parts = (message.text or "").split(maxsplit=1)
    reason = parts[1].strip() if len(parts) > 1 else ""
    if not 20 <= len(reason) <= 500:
        await message.answer("Формат: /parole причина. Объясни, почему заслуживаешь условно-досрочного освобождения (20–500 символов).")
        return
    punishment = db.execute(
        "SELECT id,created_at,expires_at FROM player_punishments WHERE user_id=? AND punishment_type='JAIL' AND active=1 ORDER BY id DESC LIMIT 1",
        (user_id,)
    ).fetchone()
    if not punishment:
        await message.answer("У тебя нет активного игрового заключения.")
        return
    try:
        started = datetime.fromisoformat(punishment["created_at"])
        expires = datetime.fromisoformat(punishment["expires_at"])
        total_seconds = (expires - started).total_seconds()
        elapsed_seconds = (datetime.now() - started).total_seconds()
    except (TypeError, ValueError):
        await message.answer("Срок заключения не удалось проверить. Обратись к администрации.")
        return
    if total_seconds <= 0 or elapsed_seconds < total_seconds * 0.5:
        remaining = max(0, int(total_seconds * 0.5 - elapsed_seconds))
        await message.answer(f"Подать заявление на УДО можно после отбытия половины срока. Осталось примерно {max(1, remaining // 60)} мин. до этого момента.")
        return
    pending = db.execute("SELECT id FROM parole_applications WHERE punishment_id=? AND status='На рассмотрении'", (punishment["id"],)).fetchone()
    if pending:
        await message.answer(f"Заявление на УДО №{pending['id']} уже находится на рассмотрении.")
        return
    try:
        begin_immediate()
        cur = db.execute(
            "INSERT INTO parole_applications(punishment_id,user_id,reason,status,created_at) VALUES(?,?,?,'На рассмотрении',?)",
            (punishment["id"], user_id, reason, now_text())
        )
        application_id = cur.lastrowid
        db.commit()
    except sqlite3.IntegrityError:
        if db.in_transaction: db.rollback()
        await message.answer("Заявление на УДО уже подано и ожидает решения.")
        return
    except sqlite3.Error:
        if db.in_transaction: db.rollback()
        log.exception("Не удалось сохранить заявление на УДО")
        await message.answer("Не удалось сохранить заявление. Попробуй позже.")
        return
    await message.answer(f"⚖️ Заявление на УДО №{application_id} отправлено судье. До решения суда ты остаёшься в игровом заключении.")
    judges = db.execute("SELECT user_id FROM players WHERE faction='Мэрия' AND rank IN ('Судья','Аттестованный судья','Апелляционный судья')").fetchall()
    judge_ids = [int(judge["user_id"]) for judge in judges] or [int(admin_id) for admin_id in ADMIN_IDS if int(admin_id) != user_id]
    keyboard = InlineKeyboardMarkup(inline_keyboard=[[
        InlineKeyboardButton(text="Открыть заявление", callback_data=f"parole:view:{application_id}")
    ]])
    for judge_id in judge_ids:
        try:
            await message.bot.send_message(judge_id, f"⚖️ Новое заявление на УДО №{application_id} от {player_display_name(get_player(user_id))}.", reply_markup=keyboard)
        except Exception:
            log.exception("Не удалось уведомить судью о заявлении на УДО")


