@dp.message(Command("detain"))
async def faction_detain_command(message: Message):
    officer = get_player(message.from_user.id)
    parts = (message.text or "").split(maxsplit=3)
    if not _is_police_or_fbi(officer):
        await message.answer("Игровое задержание доступно сотрудникам ЦПД и ФБР.")
        return
    if officer["banned"] or not db.execute(
        "SELECT 1 FROM faction_duty WHERE user_id=? AND faction=? AND active=1",
        (message.from_user.id, officer["faction"])
    ).fetchone():
        await message.answer("Для задержания нужно состоять в действующем составе ЦПД/ФБР и заступить на дежурство командой /duty_on.")
        return
    if len(parts) < 4 or not parts[1].isdigit() or not parts[2].isdigit():
        await message.answer("Формат: /detain GAME_ID минуты причина (1–120 минут)")
        return
    target, minutes, reason = get_player_by_game_id(parts[1]), int(parts[2]), parts[3].strip()
    if not target:
        await message.answer("Персонаж с таким игровым ID не найден.")
        return
    target_id = int(target["user_id"])
    if target_id == message.from_user.id or minutes < 1 or minutes > 120 or len(reason) < 10:
        await message.answer("Проверь игровой ID, срок (1–120 минут) и причину (не менее 10 символов).")
        return
    if target["location"] != officer["location"]:
        await message.answer("Для RP-задержания персонажи должны находиться в одной игровой локации.")
        return
    if target["banned"]:
        await message.answer("Нельзя оформить RP-задержание персонажу с активной блокировкой.")
        return
    add_punishment(target_id, "JAIL", f"RP-задержание: {reason}", message.from_user.id, minutes)
    db.execute("INSERT INTO reports(user_id, text, created_at) VALUES (?, ?, ?)", (message.from_user.id, f"RP-задержание {player_display_name(target)}; срок {minutes} мин.; причина: {reason}", now_text()))
    db.commit()
    await message.answer(f"🚔 Игровое задержание оформлено на {minutes} мин. Законопослушность персонажа изменена.")
    try:
        await message.bot.send_message(target_id, f"🚔 Ты задержан в рамках игрового RP-сценария на {minutes} мин. Причина: {reason}")
    except Exception:
        log.debug("Optional operation failed", exc_info=True)
