@dp.message(Command("court_verdict"))
async def court_verdict_command(message: Message):
    judge = get_player(message.from_user.id)
    parts = (message.text or "").split(maxsplit=3)
    if not _is_judge(judge) or len(parts) < 4 or not parts[1].isdigit() or parts[2].casefold() not in ("оправдать", "виновен"):
        await message.answer("Формат: /court_verdict ID_дела оправдать|виновен обоснование")
        return
    case_id, verdict, reason = int(parts[1]), parts[2].casefold(), parts[3].strip()
    case = db.execute("SELECT * FROM court_cases WHERE id=? AND status='Слушание' AND judge_id=?", (case_id, message.from_user.id)).fetchone()
    if not case:
        await message.answer("Слушание не найдено или дело ведёт другой судья.")
        return
    db.execute("UPDATE court_cases SET status='Закрыто', verdict=?, decision_text=?, closed_at=? WHERE id=?", (verdict, reason, now_text(), case_id))
    db.execute("INSERT INTO court_entries(case_id, author_id, entry_type, content, created_at) VALUES (?, ?, 'Решение суда', ?, ?)", (case_id, message.from_user.id, f"Решение: {verdict}. Обоснование: {reason}", now_text()))
    db.execute("UPDATE legal_charges SET status=? WHERE id IN (SELECT charge_id FROM court_case_charges WHERE case_id=?) AND status='Выдвинуто'", ("Снято судом" if verdict == "оправдать" else "Подтверждено судом", case_id))
    jury_summary = db.execute(
        "SELECT SUM(CASE WHEN vote='guilty' THEN 1 ELSE 0 END) AS guilty, "
        "SUM(CASE WHEN vote='innocent' THEN 1 ELSE 0 END) AS innocent FROM court_jury_members WHERE case_id=?",
        (case_id,)
    ).fetchone()
    if jury_summary and ((jury_summary["guilty"] or 0) + (jury_summary["innocent"] or 0)):
        db.execute(
            "INSERT INTO court_entries(case_id,author_id,entry_type,content,created_at) VALUES(?,?,'Мнение присяжных',?,?)",
            (case_id, message.from_user.id, f"Совещательное голосование: виновен — {jury_summary['guilty'] or 0}; не виновен — {jury_summary['innocent'] or 0}. Окончательное решение принято судьёй.", now_text())
        )
    db.commit()
    await message.answer(f"⚖️ Решение по делу №{case_id}: {verdict}. Материалы сохранены.")
    for recipient_id in (case["client_id"], case["lawyer_id"]):
        if int(recipient_id or 0) <= 0:
            continue
        try:
            await message.bot.send_message(recipient_id, f"Суд вынес решение по делу №{case_id}: {verdict}. Обоснование: {reason}")
        except Exception:
            log.debug("Не удалось уведомить сторону судебного дела", exc_info=True)
@dp.message(Command("jury_invite"))
async def court_jury_invite_command(message: Message):
    judge = get_player(message.from_user.id)
    parts = (message.text or "").split()
    if not _is_judge(judge) or len(parts) != 3 or not parts[1].isdigit() or not parts[2].isdigit():
        await message.answer("Формат: /jury_invite ID_дела GAME_ID (только судья, ведущий слушание)")
        return
    case_id = int(parts[1])
    target = get_player_by_game_id(parts[2])
    case = db.execute("SELECT * FROM court_cases WHERE id=? AND status='Слушание' AND judge_id=?", (case_id, message.from_user.id)).fetchone()
    if not case or not target:
        await message.answer("Слушание или персонаж не найдены.")
        return
    target_id = int(target["user_id"])
    if target_id in (case["client_id"], case["lawyer_id"], case["judge_id"]):
        await message.answer("Стороны дела и судья не могут входить в состав присяжных.")
        return
    try:
        begin_immediate()
        if not claim_operation("court_jury_invite"):
            db.rollback(); await message.answer("Это приглашение уже обработано."); return
        db.execute(
            "INSERT INTO court_jury_members(case_id,user_id,invited_by,created_at) VALUES(?,?,?,?)",
            (case_id, target_id, message.from_user.id, now_text())
        )
        db.commit()
    except sqlite3.IntegrityError:
        if db.in_transaction: db.rollback()
        await message.answer("Этот персонаж уже приглашён или состоит в составе присяжных по делу.")
        return
    except sqlite3.Error:
        if db.in_transaction: db.rollback()
        log.exception("Не удалось пригласить присяжного")
        await message.answer("Не удалось сохранить приглашение в присяжные.")
        return
    kb = InlineKeyboardMarkup(inline_keyboard=[[InlineKeyboardButton(text="⚖️ Принять приглашение в присяжные", callback_data=f"jury:join:{case_id}")]])
    await message.answer(f"Приглашение в присяжные по делу №{case_id} отправлено персонажу {player_display_name(target)}.")
    try:
        await message.bot.send_message(target_id, f"⚖️ Тебя пригласили в присяжные по делу №{case_id}. Голос будет совещательным; окончательное решение принимает судья.", reply_markup=kb)
    except Exception:
        log.exception("Не удалось доставить приглашение присяжному")


@dp.callback_query(F.data.startswith("jury:join:"))
async def court_jury_join_callback(callback: CallbackQuery):
    try:
        case_id = int(callback.data.rsplit(":", 1)[1])
    except (TypeError, ValueError):
        await callback.answer("Дело не найдено.", show_alert=True)
        return
    case = db.execute("SELECT * FROM court_cases WHERE id=? AND status='Слушание'", (case_id,)).fetchone()
    invite = db.execute("SELECT * FROM court_jury_members WHERE case_id=? AND user_id=? AND status='Приглашён'", (case_id, callback.from_user.id)).fetchone()
    if not case or not invite:
        await callback.answer("Приглашение недействительно или слушание завершено.", show_alert=True)
        return
    changed = db.execute("UPDATE court_jury_members SET status='Участник',joined_at=? WHERE id=? AND status='Приглашён'", (now_text(), invite["id"]))
    db.commit()
    if changed.rowcount != 1:
        await callback.answer("Приглашение уже обработано.", show_alert=True)
        return
    kb = InlineKeyboardMarkup(inline_keyboard=[[
        InlineKeyboardButton(text="Виновен", callback_data=f"jury:vote:{case_id}:guilty"),
        InlineKeyboardButton(text="Не виновен", callback_data=f"jury:vote:{case_id}:innocent")
    ]])
    await callback.answer("Ты вошёл в состав присяжных.")
    await callback.message.answer(f"⚖️ Ты присяжный по делу №{case_id}. После изучения материалов подай совещательный голос:", reply_markup=kb)


@dp.callback_query(F.data.startswith("jury:vote:"))
async def court_jury_vote_callback(callback: CallbackQuery):
    parts = callback.data.split(":")
    if len(parts) != 4 or not parts[2].isdigit() or parts[3] not in ("guilty", "innocent"):
        await callback.answer("Некорректный голос.", show_alert=True)
        return
    case_id, vote = int(parts[2]), parts[3]
    case = db.execute("SELECT id FROM court_cases WHERE id=? AND status='Слушание'", (case_id,)).fetchone()
    member = db.execute("SELECT id,vote FROM court_jury_members WHERE case_id=? AND user_id=? AND status='Участник'", (case_id, callback.from_user.id)).fetchone()
    if not case or not member:
        await callback.answer("Ты не входишь в состав присяжных по этому делу.", show_alert=True)
        return
    if member["vote"]:
        await callback.answer("Твой голос уже записан и не может быть изменён.", show_alert=True)
        return
    changed = db.execute("UPDATE court_jury_members SET vote=?,voted_at=? WHERE id=? AND vote=''", (vote, now_text(), member["id"]))
    db.commit()
    if changed.rowcount != 1:
        await callback.answer("Голос уже записан.", show_alert=True)
        return
    await callback.answer("Совещательный голос записан.", show_alert=True)
    await callback.message.edit_reply_markup(reply_markup=None)


@dp.message(Command("case_report"))
async def court_case_report_command(message: Message):
    parts = (message.text or "").split()
    if len(parts) != 2 or not parts[1].isdigit():
        await message.answer("Формат: /case_report ID_дела")
        return
    case_id = int(parts[1])
    case = db.execute("SELECT * FROM court_cases WHERE id=?", (case_id,)).fetchone()
    if not case:
        await message.answer("Дело не найдено.")
        return
    if message.from_user.id not in (case["client_id"], case["lawyer_id"], case["judge_id"]) and not is_admin(message.from_user.id):
        await message.answer("Нет доступа к материалам дела.")
        return
    entries = db.execute("SELECT author_id, entry_type, content, created_at FROM court_entries WHERE case_id=? ORDER BY id", (case_id,)).fetchall()
    linked_charges = db.execute("SELECT c.id,c.article_code,c.reason,c.status FROM court_case_charges m JOIN legal_charges c ON c.id=m.charge_id WHERE m.case_id=? ORDER BY c.id", (case_id,)).fetchall()
    jury_rows = db.execute("SELECT user_id,status,vote,joined_at,voted_at FROM court_jury_members WHERE case_id=? ORDER BY id", (case_id,)).fetchall()
    client_name = player_display_name(get_player(case["client_id"]), "Неизвестный клиент")
    lawyer_name = "Следственный комитет (обвинение)" if int(case["lawyer_id"] or 0) == 0 else player_display_name(get_player(case["lawyer_id"]), "Неизвестный адвокат")
    judge_name = player_display_name(get_player(case["judge_id"]), "не назначен") if case["judge_id"] else "не назначен"
    lines = [f"⚖️ Дело №{case_id}: {case['title']}", f"Статус: {case['status']}", f"Клиент: {client_name}", f"Адвокат: {lawyer_name}", f"Судья: {judge_name}", f"Решение: {case['verdict'] or 'не вынесено'}"]
    if linked_charges:
        lines.append("Обвинения по делу:")
        lines.extend(f"• №{charge['id']} · {charge['article_code']} · {charge['status']} · {charge['reason']}" for charge in linked_charges)
    if jury_rows:
        guilty_votes = sum(1 for juror in jury_rows if juror["vote"] == "guilty")
        innocent_votes = sum(1 for juror in jury_rows if juror["vote"] == "innocent")
        lines.append(f"Присяжные: {len(jury_rows)} приглашено/принято · голосов: {guilty_votes} за виновность, {innocent_votes} за невиновность")
        lines.extend(
            f"• {player_display_name(get_player(juror['user_id']), 'Присяжный')} — "
            f"{'виновен' if juror['vote']=='guilty' else 'не виновен' if juror['vote']=='innocent' else juror['status']}"
            for juror in jury_rows
        )
    for entry in entries:
        author_name = player_display_name(get_player(entry["author_id"]), "Система/участник")
        lines.append(f"\n[{entry['entry_type']}] {author_name} ({entry['created_at']}): {entry['content']}")
    await message.answer("\n".join(lines)[:4000])


@dp.message(Command("recruit_auto"))
async def recruit_auto_command(message: Message):
    if not is_admin(message.from_user.id):
        await message.answer("Автоматическую ротацию наборов может менять администрация.")
        return
    parts = (message.text or "").split()
    if len(parts) != 2 or parts[1].casefold() not in ("on", "off"):
        await message.answer("Формат: /recruit_auto on|off")
        return
    enabled = 1 if parts[1].casefold() == "on" else 0
    next_time = (datetime.now() + timedelta(minutes=random.randint(30, 60))).isoformat(timespec="seconds") if enabled else ""
    db.execute("UPDATE recruitment_settings SET auto_enabled=?, next_rotation=? WHERE id=1", (enabled, next_time))
    db.commit()
    await message.answer("🔄 Автоматическая ротация наборов включена." if enabled else "Автоматическая ротация наборов выключена.")


async def broadcast_recruitment_notice(bot_obj, faction, opened=True):
    try:
        if opened:
            await _spawn_recruit_npcs(bot_obj, faction)
        else:
            _expire_recruit_npcs(faction)
    except Exception:
        log.exception("Ошибка кандидатов-НПС на наборе")
    users = db.execute("SELECT user_id FROM players").fetchall()
    if opened:
        text_value = f"📢 ОТКРЫТ НАБОР: {faction}\nПриходи в здание организации через «🗺 Карта» и нажми «🎤 Пойти на собеседование»."
    else:
        text_value = f"📢 Набор в организации «{faction}» закрыт. Уже поданные заявки остаются в истории."
    for user in users:
        try:
            await bot_obj.send_message(user["user_id"], text_value)
        except Exception:
            log.debug("Optional operation failed", exc_info=True)
        await asyncio.sleep(0.04)


async def recruitment_rotation_loop(bot_obj):
    """Случайно открывает набор в одной из организаций и уведомляет игроков."""
    while True:
        try:
            setting = db.execute("SELECT * FROM recruitment_settings WHERE id=1").fetchone()
            if setting and setting["auto_enabled"]:
                next_rotation = setting["next_rotation"] or ""
                due = False
                if not next_rotation:
                    due = True
                else:
                    try:
                        due = datetime.fromisoformat(next_rotation) <= datetime.now()
                    except ValueError:
                        due = True
                if due:
                    choices = [f for f in RECRUITMENT_ROTATION_FACTIONS if f != setting["last_faction"]]
                    faction = random.choice(choices or RECRUITMENT_ROTATION_FACTIONS)
                    db.execute("UPDATE faction_recruitment SET is_open=0")
                    db.execute(
                        "INSERT INTO faction_recruitment(faction, is_open, opened_by, opened_at) VALUES (?, 1, 0, ?) "
                        "ON CONFLICT(faction) DO UPDATE SET is_open=1, opened_by=0, opened_at=excluded.opened_at",
                        (faction, now_text())
                    )
                    next_time = datetime.now() + timedelta(minutes=random.randint(120, 240))
                    db.execute("UPDATE recruitment_settings SET next_rotation=?, last_faction=? WHERE id=1", (next_time.isoformat(timespec="seconds"), faction))
                    db.commit()
                    await broadcast_recruitment_notice(bot_obj, faction, opened=True)
        except Exception:
            log.exception("Ошибка автоматической ротации наборов")
        await asyncio.sleep(60)


