def _validate_faction_work_catalog():
    """Fail fast if any configured faction/rank has no real work catalog."""
    missing = []
    for faction, meta in FACTIONS.items():
        for rank in meta.get("ranks", []):
            tasks = FACTION_RANK_WORK_TASKS.get(faction, {}).get(rank)
            if not tasks:
                missing.append(f"{faction}/{rank}: нет заданий")
                continue
            for task in tasks:
                if len(task) < 4 or not task[0] or not task[1] or int(task[3]) <= 0:
                    missing.append(f"{faction}/{rank}: некорректное задание {task!r}")
    for rank in UNIVERSITY_RANKS:
        tasks = FACTION_RANK_WORK_TASKS.get("Университет", {}).get(rank)
        if not tasks:
            missing.append(f"Университет/{rank}: нет заданий")
    if missing:
        raise RuntimeError("Ошибка каталога фракционных работ: " + "; ".join(missing))
    return True


_validate_faction_work_catalog()


def _work_tasks_for(player):
    if not player:
        return []
    role_tasks = FACTION_RANK_WORK_TASKS.get(player["faction"], {}).get(player["rank"])
    return role_tasks if role_tasks is not None else FACTION_WORK_TASKS.get(player["faction"], [])


