def _faction_work_keyboard(row):
    steps = _faction_work_steps(row["faction"], row["task_key"])
    index = max(0, int(row["stage_index"] or 0))
    if index < len(steps):
        return InlineKeyboardMarkup(inline_keyboard=[[
            InlineKeyboardButton(text=steps[index], callback_data=f"fwork:stage:{row['id']}:{index}")
        ]])
    return InlineKeyboardMarkup(inline_keyboard=[[
        InlineKeyboardButton(text="📝 Сдать итоговый отчёт", callback_data=f"fwork:submit:{row['id']}")
    ]])


class FactionWorkState(StatesGroup):
    report = State()


@dp.callback_query(F.data == "fwork:take")
async def faction_work_take_button(callback: CallbackQuery):
    uid = callback.from_user.id
    player = _work_member(uid)
    if not player:
        await callback.answer("Ты не состоишь в действующей фракции.", show_alert=True); return
    if player["faction"] == "Университет" and player["location"] != "Университет":
        await callback.answer("Для получения служебного поручения нужно находиться в кампусе.", show_alert=True); return
    try:
        begin_immediate()
        active = db.execute("SELECT id,task_title FROM faction_work_sessions WHERE user_id=? AND status IN ('Ожидает отчёта','В работе','На проверке') ORDER BY id DESC LIMIT 1", (uid,)).fetchone()
        if active:
            db.rollback(); await callback.answer(f"Сначала заверши поручение №{active['id']}.", show_alert=True); return
        today = datetime.now().date().isoformat()
        completed = db.execute("SELECT COUNT(*) FROM faction_work_log WHERE user_id=? AND faction=? AND substr(created_at,1,10)=?", (uid, player['faction'], today)).fetchone()[0]
        if completed >= 5:
            db.rollback(); await callback.answer("Дневной лимит поручений исчерпан.", show_alert=True); return
        tasks = _work_tasks_for(player)
        last = db.execute("SELECT task_key FROM faction_work_log WHERE user_id=? AND faction=? ORDER BY id DESC LIMIT 1", (uid, player['faction'])).fetchone()
        choices = [t for t in tasks if not last or t[0] != last['task_key']] or tasks
        task = random.choice(choices)
        cur = db.execute("INSERT INTO faction_work_sessions(user_id,faction,department,task_key,task_title,task_description,status,report,reward,created_at,completed_at) VALUES(?,?,?,?,?,?, 'В работе','',?,?, '')", (uid, player['faction'], _department_for(uid), task[0], task[1], task[2], task[3], now_text()))
        sid = cur.lastrowid; db.commit()
    except sqlite3.Error:
        if db.in_transaction: db.rollback()
        log.exception("Ошибка выдачи поручения через кнопку"); await callback.answer("Не удалось выдать поручение.", show_alert=True); return
    await callback.answer("Поручение выдано.", show_alert=True)
    issued = db.execute("SELECT * FROM faction_work_sessions WHERE id=?", (sid,)).fetchone()
    await callback.message.answer(f"📋 ПОРУЧЕНИЕ №{sid} · {task[1]}\n\n{task[2]}\n\nНаграда после проверки: ${task[3]:,}. Этапы выполняются последовательно.", reply_markup=_faction_work_keyboard(issued))


@dp.callback_query(F.data.startswith("fwork:stage:"))
async def faction_work_stage_callback(callback: CallbackQuery):
    parts = callback.data.split(":")
    if len(parts) != 4 or not parts[2].isdigit() or not parts[3].isdigit():
        await callback.answer("Некорректный этап поручения.", show_alert=True)
        return
    session_id, expected_stage = int(parts[2]), int(parts[3])
    player = _work_member(callback.from_user.id)
    if not player:
        await callback.answer("Ты больше не состоишь в действующей фракции.", show_alert=True)
        return
    try:
        begin_immediate()
        row = db.execute(
            "SELECT * FROM faction_work_sessions WHERE id=? AND user_id=? AND status='В работе'",
            (session_id, callback.from_user.id)
        ).fetchone()
        if not row or row["faction"] != player["faction"]:
            db.rollback()
            await callback.answer("Поручение не найдено или уже изменилось.", show_alert=True)
            return
        steps = _faction_work_steps(row["faction"], row["task_key"])
        current_stage = max(0, int(row["stage_index"] or 0))
        if current_stage != expected_stage or current_stage >= len(steps):
            db.rollback()
            await callback.answer("Этот этап уже пройден или пока недоступен.", show_alert=True)
            return
        if current_stage > 0:
            try:
                previous_at = datetime.fromisoformat(row["stage_updated_at"] or row["created_at"])
                wait_seconds = (datetime.now() - previous_at).total_seconds()
            except (TypeError, ValueError):
                wait_seconds = 0
            if wait_seconds < 10:
                db.rollback()
                await callback.answer(f"Следующий этап откроется через {max(1, int(10-wait_seconds+0.99))} сек.", show_alert=True)
                return
        changed = db.execute(
            "UPDATE faction_work_sessions SET stage_index=stage_index+1,stage_updated_at=? "
            "WHERE id=? AND user_id=? AND status='В работе' AND stage_index=?",
            (now_text(), session_id, callback.from_user.id, expected_stage)
        )
        if changed.rowcount != 1:
            db.rollback()
            await callback.answer("Этап уже изменился. Обнови поручение.", show_alert=True)
            return
        updated = db.execute("SELECT * FROM faction_work_sessions WHERE id=?", (session_id,)).fetchone()
        db.commit()
    except sqlite3.Error:
        if db.in_transaction:
            db.rollback()
        log.exception("Ошибка перехода этапа фракционной работы")
        await callback.answer("Не удалось сохранить этап.", show_alert=True)
        return
    next_index = int(updated["stage_index"] or 0)
    if next_index >= len(steps):
        text_value = f"✅ Все этапы поручения №{session_id} пройдены. Теперь можно сдать итоговый RP-отчёт."
    else:
        text_value = f"Этап {next_index}/{len(steps)} выполнен. Следующий этап: {steps[next_index]}"
    await callback.answer("Этап сохранён.")
    await callback.message.edit_text(
        f"📋 ПОРУЧЕНИЕ №{session_id} · {updated['task_title']}\n\n{updated['task_description']}\n\n{text_value}",
        reply_markup=_faction_work_keyboard(updated)
    )


@dp.callback_query(F.data.startswith("fwork:submit:"))
async def faction_work_submit_button(callback: CallbackQuery, state: FSMContext):
    try: sid = int(callback.data.rsplit(":", 1)[1])
    except ValueError: await callback.answer("Некорректное поручение.", show_alert=True); return
    row = db.execute("SELECT * FROM faction_work_sessions WHERE id=? AND user_id=? AND status='В работе'", (sid, callback.from_user.id)).fetchone()
    player = _work_member(callback.from_user.id)
    if not row or not player or row['faction'] != player['faction']:
        await callback.answer("Поручение не найдено.", show_alert=True); return
    if int(row["stage_index"] or 0) < len(_faction_work_steps(row["faction"], row["task_key"])):
        await callback.answer("Сначала пройди все этапы поручения по порядку.", show_alert=True); return
    try: elapsed = (datetime.now() - datetime.fromisoformat(row['created_at'])).total_seconds()
    except Exception: elapsed = 0
    if elapsed < 300:
        await callback.answer("Для RP-работы требуется минимум 5 минут.", show_alert=True); return
    await state.update_data(work_session_id=sid); await state.set_state(FactionWorkState.report)
    await callback.answer(); await callback.message.answer("Напиши подробный RP-отчёт (не менее 80 символов).")


def _work_member(user_id):
    player = get_player(user_id)
    if not player or player["faction"] not in FACTION_WORK_TASKS:
        return None
    if player["faction"] == "Университет":
        return player if university_employee(user_id) else None
    return player if player["rank"] in FACTIONS.get(player["faction"], {}).get("ranks", []) else None


def _faction_work_leader(player):
    if not player:
        return False
    if player["faction"] == "Университет":
        return player["rank"] in ("Заместитель декана", "Декан")
    return _faction_leader(player)


def _faction_work_leader_ranks(faction):
    if faction == "Университет":
        return ["Заместитель декана", "Декан"]
    return FACTIONS.get(faction, {}).get("ranks", [])[-2:]


def _work_task_for(faction, task_key):
    candidates = list(FACTION_WORK_TASKS.get(faction, []))
    for role_tasks in FACTION_RANK_WORK_TASKS.get(faction, {}).values():
        candidates.extend(role_tasks)
    return next((task for task in candidates if task[0] == task_key), None)


db.executescript("""
CREATE TABLE IF NOT EXISTS police_patrol_sessions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    officer_id INTEGER NOT NULL,
    faction TEXT NOT NULL DEFAULT 'ЦПД',
    status TEXT NOT NULL DEFAULT 'В патруле',
    started_at TEXT NOT NULL,
    ended_at TEXT DEFAULT '',
    report TEXT DEFAULT ''
);
CREATE UNIQUE INDEX IF NOT EXISTS idx_police_one_active_patrol
    ON police_patrol_sessions(officer_id) WHERE status='В патруле';
CREATE INDEX IF NOT EXISTS idx_police_patrol_history
    ON police_patrol_sessions(officer_id,id DESC);
CREATE TABLE IF NOT EXISTS police_incidents (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    officer_id INTEGER NOT NULL,
    target_id INTEGER NOT NULL,
    incident_type TEXT NOT NULL,
    reason TEXT NOT NULL,
    location TEXT DEFAULT '',
    amount INTEGER DEFAULT 0,
    created_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_police_incidents_officer
    ON police_incidents(officer_id,incident_type,created_at);
""")
db.commit()


@dp.message(Command("patrol"))
async def cpd_patrol_command(message: Message):
    officer = get_player(message.from_user.id)
    if not officer or officer["faction"] != "ЦПД" or officer["rank"] not in FACTIONS["ЦПД"]["ranks"]:
        await message.answer("Патрульная служба доступна только сотрудникам ЦПД.")
        return
    active = db.execute("SELECT * FROM police_patrol_sessions WHERE officer_id=? AND status='В патруле' ORDER BY id DESC LIMIT 1", (message.from_user.id,)).fetchone()
    if active:
        keyboard = InlineKeyboardMarkup(inline_keyboard=[[InlineKeyboardButton(text="🏁 Завершить патруль", callback_data=f"cpd:patrol:finish:{active['id']}")]])
        await message.answer(f"🚓 Ты находишься на патруле №{active['id']} с {active['started_at']}. После минимум 5 минут можешь завершить смену и отправить рапорт.", reply_markup=keyboard)
        return
    keyboard = InlineKeyboardMarkup(inline_keyboard=[[InlineKeyboardButton(text="🚓 Начать патруль", callback_data="cpd:patrol:start")]])
    await message.answer("🚓 ПАТРУЛЬНАЯ СЛУЖБА ЦПД\nНачни патрульную смену. Для завершения потребуется рапорт о проделанной работе.", reply_markup=keyboard)


@dp.callback_query(F.data.startswith("cpd:patrol:"))
async def cpd_patrol_callback(callback: CallbackQuery, state: FSMContext):
    officer = get_player(callback.from_user.id)
    if not officer or officer["faction"] != "ЦПД" or officer["rank"] not in FACTIONS["ЦПД"]["ranks"]:
        await callback.answer("Патруль доступен только сотрудникам ЦПД.", show_alert=True)
        return
    parts = callback.data.split(":")
    if len(parts) == 3 and parts[2] == "menu":
        active = db.execute("SELECT * FROM police_patrol_sessions WHERE officer_id=? AND status='В патруле' ORDER BY id DESC LIMIT 1", (callback.from_user.id,)).fetchone()
        if active:
            text_value = f"🚓 Активный патруль №{active['id']} начат {active['started_at']}."
            markup = InlineKeyboardMarkup(inline_keyboard=[[InlineKeyboardButton(text="🏁 Завершить патруль", callback_data=f"cpd:patrol:finish:{active['id']}")]])
        else:
            text_value = "🚓 Патрульная служба ЦПД. Начни смену кнопкой ниже. Для завершения потребуется рапорт и минимум 5 минут патрулирования."
            markup = InlineKeyboardMarkup(inline_keyboard=[[InlineKeyboardButton(text="🚓 Начать патруль", callback_data="cpd:patrol:start")]])
        await callback.answer()
        await callback.message.answer(text_value, reply_markup=markup)
        return
    if len(parts) == 3 and parts[2] == "start":
        try:
            begin_immediate()
            active = db.execute("SELECT id FROM police_patrol_sessions WHERE officer_id=? AND status='В патруле'", (callback.from_user.id,)).fetchone()
            if active:
                db.rollback(); await callback.answer("У тебя уже есть активный патруль.", show_alert=True); return
            cur = db.execute("INSERT INTO police_patrol_sessions(officer_id,faction,status,started_at) VALUES(?,'ЦПД','В патруле',?)", (callback.from_user.id, now_text()))
            patrol_id = cur.lastrowid
            db.commit()
        except sqlite3.Error:
            if db.in_transaction: db.rollback()
            log.exception("Не удалось начать патруль ЦПД")
            await callback.answer("Не удалось начать патруль.", show_alert=True)
            return
        await callback.answer("Патруль начат.")
        await callback.message.edit_text(f"🚓 Патруль №{patrol_id} начат. Через 5 минут можно завершить его и отправить рапорт.", reply_markup=InlineKeyboardMarkup(inline_keyboard=[[InlineKeyboardButton(text="🏁 Завершить патруль", callback_data=f"cpd:patrol:finish:{patrol_id}")]]))
        return
    if len(parts) == 4 and parts[2] == "finish" and parts[3].isdigit():
        patrol_id = int(parts[3])
        row = db.execute("SELECT * FROM police_patrol_sessions WHERE id=? AND officer_id=? AND status='В патруле'", (patrol_id, callback.from_user.id)).fetchone()
        if not row:
            await callback.answer("Активный патруль не найден.", show_alert=True)
            return
        try:
            elapsed = (datetime.now() - datetime.fromisoformat(row["started_at"])).total_seconds()
        except (TypeError, ValueError):
            elapsed = 0
        if elapsed < 300:
            await callback.answer(f"Патруль должен длиться минимум 5 минут. Осталось {max(1, int((300-elapsed+59)//60))} мин.", show_alert=True)
            return
        await state.update_data(patrol_session_id=patrol_id)
        await state.set_state(PatrolFlow.report)
        await callback.answer()
        await callback.message.answer("Отправь рапорт о патруле (минимум 80 символов): район, наблюдения, вызовы и результаты. Для отмены: /cancel.")
        return
    await callback.answer("Неизвестное действие патруля.", show_alert=True)


@dp.message(PatrolFlow.report, Command("cancel"))
async def cpd_patrol_report_cancel(message: Message, state: FSMContext):
    await state.clear()
    await message.answer("Отправка рапорта отменена. Патруль остаётся активным.")


@dp.message(PatrolFlow.report, F.text)
async def cpd_patrol_report_finish(message: Message, state: FSMContext):
    report = (message.text or "").strip()
    if len(report) < 80 or len(report) > 2500:
        await message.answer("Рапорт должен содержать от 80 до 2500 символов.")
        return
    data = await state.get_data()
    patrol_id = int(data.get("patrol_session_id", 0))
    officer = get_player(message.from_user.id)
    if not officer or officer["faction"] != "ЦПД":
        await state.clear(); await message.answer("Рапорт не принят: ты больше не состоишь в ЦПД."); return
    try:
        begin_immediate()
        row = db.execute("SELECT * FROM police_patrol_sessions WHERE id=? AND officer_id=? AND status='В патруле'", (patrol_id, message.from_user.id)).fetchone()
        if not row:
            db.rollback(); await state.clear(); await message.answer("Патруль уже завершён или не найден."); return
        elapsed = (datetime.now() - datetime.fromisoformat(row["started_at"])).total_seconds()
        if elapsed < 300:
            db.rollback(); await message.answer("Патруль ещё не достиг минимальной продолжительности 5 минут."); return
        changed = db.execute("UPDATE police_patrol_sessions SET status='Завершён',ended_at=?,report=? WHERE id=? AND officer_id=? AND status='В патруле'", (now_text(), report, patrol_id, message.from_user.id))
        if changed.rowcount != 1:
            raise sqlite3.IntegrityError("patrol_already_closed")
        db.execute("INSERT INTO reports(user_id,text,created_at) VALUES(?,?,?)", (message.from_user.id, f"Патруль ЦПД №{patrol_id}: {report[:1800]}", now_text()))
        db.commit()
    except sqlite3.Error:
        if db.in_transaction: db.rollback()
        log.exception("Не удалось завершить патруль ЦПД")
        await message.answer("Не удалось сохранить рапорт. Попробуй ещё раз.")
        return
    await state.clear()
    await message.answer(f"✅ Патруль №{patrol_id} завершён. Рапорт сохранён в истории службы.")


