def _rank_index(faction, rank):
    try:
        ranks = UNIVERSITY_RANKS if faction == "Университет" else FACTIONS[faction]["ranks"]
        return ranks.index(rank)
    except (KeyError, ValueError):
        return -1


def _dismiss_player(target_id, reason, dismissed_by=0):
    """Атомарно снимает сотрудника с должности, закрывая активные связи и историю."""
    try:
        begin_immediate()
        target = get_player(target_id)
        if not target or (target["faction"] not in FACTIONS and not university_employee(target_id)):
            db.rollback()
            return False
        faction, rank = target["faction"], target["rank"]
        now = now_text()
        active_employment = db.execute(
            "SELECT id FROM employment_history WHERE user_id=? AND faction=? AND (ended_at IS NULL OR ended_at='') ORDER BY id DESC LIMIT 1",
            (target_id, faction)
        ).fetchone()
        if active_employment:
            db.execute("UPDATE employment_history SET action='Увольнение',ended_at=?,actor_id=? WHERE id=?", (now, dismissed_by, active_employment["id"]))
        else:
            membership = db.execute("SELECT joined_at FROM faction_membership WHERE user_id=? AND faction=? AND (left_at IS NULL OR left_at='') ORDER BY id DESC LIMIT 1", (target_id, faction)).fetchone()
            db.execute("INSERT INTO employment_history(user_id,faction,rank,action,started_at,ended_at,actor_id,created_at) VALUES(?,?,?,?,?,?,?,?)", (target_id, faction, rank, "Увольнение", membership["joined_at"] if membership else "", now, dismissed_by, now))
        _close_faction_membership(target_id, faction, reason, dismissed_by, now)
        # Remove live access while retaining all completed work and audit history.
        db.execute("UPDATE faction_duty SET active=0 WHERE user_id=? AND faction=? AND active=1", (target_id, faction))
        db.execute("DELETE FROM faction_department_members WHERE user_id=? AND faction=?", (target_id, faction))
        db.execute("UPDATE faction_departments SET head_id=CASE WHEN head_id=? THEN 0 ELSE head_id END, deputy_id=CASE WHEN deputy_id=? THEN 0 ELSE deputy_id END WHERE faction=?", (target_id, target_id, faction))
        db.execute("UPDATE faction_work_sessions SET status='Отменено: выход из фракции',completed_at=? WHERE user_id=? AND faction=? AND status IN ('В работе','Ожидает отчёта','На проверке')", (now, target_id, faction))
        db.execute("UPDATE promotion_requests SET status='Отменено: выход из фракции',decided_at=?,decision_note='Игрок покинул организацию' WHERE user_id=? AND faction=? AND status IN ('Ожидает','На рассмотрении')", (now, target_id, faction))
        db.execute("UPDATE faction_applications SET status='Отменена: выход из фракции' WHERE user_id=? AND status IN ('На собеседование','На рассмотрении')", (target_id,))
        changed = db.execute("UPDATE players SET faction='Нет',rank='Нет' WHERE user_id=? AND faction=? AND rank=?", (target_id, faction, rank))
        if changed.rowcount != 1:
            raise sqlite3.IntegrityError("dismiss_state_changed")
        db.commit()
        return True
    except sqlite3.Error:
        if db.in_transaction:
            db.rollback()
        log.exception("Ошибка увольнения игрока")
        return False


@dp.message(Command("fire"))
async def fire_command(message: Message):
    actor_id = message.from_user.id
    actor = get_player(actor_id)
    admin = is_admin(actor_id)
    parts = (message.text or "").split(maxsplit=2)

    is_faction_leader = bool(
        actor
        and _faction_work_leader(actor)
    )
    if not admin and not is_faction_leader:
        await message.answer("❌ Команда /fire доступна только администрации и руководству твоей организации. Обычные граждане не могут увольнять сотрудников.")
        return
    if len(parts) < 2 or not parts[1].isdigit():
        await message.answer("Формат: /fire GAME_ID [причина]\nПример: /fire 34 Нарушение устава")
        return

    target = get_player_by_game_id(parts[1])
    if not target:
        await message.answer("Персонаж с таким игровым ID не найден.")
        return
    target_id = int(target["user_id"])
    reason = parts[2].strip()[:200] if len(parts) > 2 else "По решению руководства"

    if target_id == actor_id:
        await message.answer("Себя уволить нельзя. Чтобы уйти самому, используй /quit.")
        return
    if not target or (target["faction"] not in FACTIONS and not university_employee(target_id)):
        await message.answer("Игрок не найден или не состоит в организации.")
        return
    if not admin:
        if target["faction"] != actor["faction"]:
            await message.answer("Этот игрок состоит в другой организации.")
            return
        if _rank_index(target["faction"], target["rank"]) >= _rank_index(actor["faction"], actor["rank"]):
            await message.answer("Можно увольнять только сотрудников с должностью ниже твоей.")
            return

    faction, rank = target["faction"], target["rank"]
    if not _dismiss_player(target_id, reason, actor_id):
        await message.answer("Не удалось уволить игрока. Проверь журнал ошибок.")
        return
    if admin:
        audit_admin_action(actor_id, target_id, "FIRE", f"{faction}|{rank}|{reason}")

    await message.answer(f"✅ {player_display_name(target)} {gender_form(target, 'уволен', 'уволена')} из «{faction}» (должность: {rank}).\nПричина: {reason}")
    try:
        await message.bot.send_message(
            target_id,
            f"❌ Ты {gender_form(get_player(target_id), 'уволен', 'уволена')} из организации «{faction}» (должность: {rank}).\nПричина: {reason}\n"
            "Запись добавлена в трудовую книжку. Ты можешь подать заявку в другую организацию.",
            reply_markup=main_keyboard(get_player(target_id))
        )
    except Exception:
        log.debug("Optional operation failed", exc_info=True)
