def _translate_legacy_npc_name(value):
    parts = str(value or "").split()
    if len(parts) == 2 and all(part in _NPC_NAME_TRANSLATIONS for part in parts):
        return " ".join(_NPC_NAME_TRANSLATIONS[part] for part in parts)
    return value

