EXAM_BANKS = {"Мэрия": {"Вице-губернатор": _EXAM_VICE, "Губернатор": _EXAM_GOV}}

db.execute("""CREATE TABLE IF NOT EXISTS exam_sessions (
    user_id INTEGER PRIMARY KEY,
    faction TEXT NOT NULL,
    rank TEXT NOT NULL,
    questions_json TEXT NOT NULL,
    q_index INTEGER DEFAULT 0,
    correct INTEGER DEFAULT 0,
    created_at TEXT DEFAULT ''
)""")
db.execute("""CREATE TABLE IF NOT EXISTS exam_results (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    faction TEXT NOT NULL,
    rank TEXT NOT NULL,
    score INTEGER DEFAULT 0,
    total INTEGER DEFAULT 0,
    passed INTEGER DEFAULT 0,
    created_at TEXT DEFAULT ''
)""")
db.commit()


def _exam_required(faction, rank):
    return rank in EXAM_BANKS.get(faction, {})


def _exam_passed(user_id, faction, rank):
    row = db.execute("SELECT 1 FROM exam_results WHERE user_id=? AND faction=? AND rank=? AND passed=1 LIMIT 1", (user_id, faction, rank)).fetchone()
    return bool(row)


def _exam_build(faction, rank):
    bank = random.sample(EXAM_BANKS[faction][rank], min(EXAM_QUESTIONS_COUNT, len(EXAM_BANKS[faction][rank])))
    questions = []
    for text_q, options in bank:
        right = options[0]
        shuffled = options[:]
        random.shuffle(shuffled)
        questions.append({"q": text_q, "options": shuffled, "correct": shuffled.index(right)})
    return questions


def _exam_keyboard(q_index, options):
    return InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(text=opt, callback_data=f"exam:{q_index}:{i}")] for i, opt in enumerate(options)
    ])


async def _exam_send_question(message, session_questions, q_index):
    q = session_questions[q_index]
    await message.answer(
        f"📝 Экзамен — вопрос {q_index + 1}/{len(session_questions)}\n\n{q['q']}",
        reply_markup=_exam_keyboard(q_index, q["options"])
    )


@dp.message(Command("exam"))
async def exam_command(message: Message):
    user_id = message.from_user.id
    player = get_player(user_id)
    if not player or player["faction"] not in FACTIONS:
        await message.answer("Экзамен сдают сотрудники организаций, которым положен экзамен на следующую должность.")
        return
    ranks = FACTIONS[player["faction"]]["ranks"]
    idx = _rank_index(player["faction"], player["rank"])
    nxt = ranks[idx + 1] if 0 <= idx < len(ranks) - 1 else None
    if not nxt or not _exam_required(player["faction"], nxt):
        await message.answer("Для твоей следующей должности экзамен не требуется.")
        return
    if _exam_passed(user_id, player["faction"], nxt):
        await message.answer(f"✅ Экзамен на «{nxt}» уже сдан. Подай рапорт: /report")
        return
    active = db.execute("SELECT * FROM exam_sessions WHERE user_id=?", (user_id,)).fetchone()
    if active:
        questions = json.loads(active["questions_json"])
        await message.answer("Экзамен уже идёт. Продолжай с текущего вопроса.")
        await _exam_send_question(message, questions, active["q_index"])
        return
    last = db.execute("SELECT created_at FROM exam_results WHERE user_id=? AND faction=? AND rank=? AND passed=0 ORDER BY id DESC LIMIT 1", (user_id, player["faction"], nxt)).fetchone()
    if last:
        try:
            wait = timedelta(minutes=EXAM_RETRY_MINUTES) - (datetime.now() - datetime.fromisoformat(last["created_at"]))
            if wait.total_seconds() > 0:
                await message.answer(f"Пересдача будет доступна через {int(wait.total_seconds() // 60) + 1} мин.")
                return
        except ValueError:
            pass
    questions = _exam_build(player["faction"], nxt)
    db.execute(
        "INSERT INTO exam_sessions(user_id, faction, rank, questions_json, q_index, correct, created_at) VALUES (?, ?, ?, ?, 0, 0, ?)",
        (user_id, player["faction"], nxt, json.dumps(questions, ensure_ascii=False), now_text())
    )
    db.commit()
    await message.answer(
        f"🏛 Экзамен на должность «{nxt}»\n"
        f"Вопросов: {len(questions)}. Для успеха нужно верных ответов: {EXAM_PASS_SCORE}."
    )
    await _exam_send_question(message, questions, 0)


@dp.callback_query(F.data.startswith("exam:"))
async def exam_answer_callback(callback: CallbackQuery):
    user_id = callback.from_user.id
    session = db.execute("SELECT * FROM exam_sessions WHERE user_id=?", (user_id,)).fetchone()
    if not session:
        await callback.answer("Экзамен не идёт. Начать: /exam", show_alert=True)
        return
    try:
        _, q_text, o_text = callback.data.split(":")
        q_index, option = int(q_text), int(o_text)
    except ValueError:
        await callback.answer()
        return
    questions = json.loads(session["questions_json"])
    if q_index != session["q_index"] or q_index >= len(questions):
        await callback.answer("Этот вопрос уже пройден.", show_alert=True)
        return
    right = option == questions[q_index]["correct"]
    correct = session["correct"] + (1 if right else 0)
    next_index = q_index + 1
    try:
        await callback.message.edit_text(
            f"📝 Вопрос {q_index + 1}/{len(questions)}\n{questions[q_index]['q']}\n\nТвой ответ: {questions[q_index]['options'][option]}"
        )
    except Exception:
        log.debug("Optional operation failed", exc_info=True)
    await callback.answer("✅ Верно" if right else "❌ Неверно")
    if next_index < len(questions):
        db.execute("UPDATE exam_sessions SET q_index=?, correct=? WHERE user_id=?", (next_index, correct, user_id))
        db.commit()
        await _exam_send_question(callback.message, questions, next_index)
        return
    passed = correct >= EXAM_PASS_SCORE
    db.execute("DELETE FROM exam_sessions WHERE user_id=?", (user_id,))
    db.execute(
        "INSERT INTO exam_results(user_id, faction, rank, score, total, passed, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)",
        (user_id, session["faction"], session["rank"], correct, len(questions), 1 if passed else 0, now_text())
    )
    db.commit()
    if passed:
        await callback.message.answer(
            f"🎉 Экзамен сдан: {correct}/{len(questions)}.\n"
            f"Ты допущен к должности «{session['rank']}». Теперь подай рапорт: /report"
        )
    else:
        await callback.message.answer(
            f"❌ Экзамен не сдан: {correct}/{len(questions)} (нужно {EXAM_PASS_SCORE}).\n"
            f"Пересдача через {EXAM_RETRY_MINUTES} минут: /exam"
        )


def _npc_schedule_activity(hour, faction, rank, npc_id=None):
    """Возвращает текущую задачу NPC по сохранённому в SQLite распорядку."""
    if 21 <= hour or hour < 6:
        key, title = "21-06", "Отдых"
    elif 6 <= hour < 9:
        key, title = "06-09", "Подготовка к смене"
    elif 9 <= hour < 12:
        key, title = "09-12", "Рабочая смена"
    elif 12 <= hour < 14:
        key, title = "12-14", "Перерыв"
    elif 14 <= hour < 18:
        key, title = "14-18", "Рабочая смена"
    else:
        key, title = "18-21", "Передача смены"
    if npc_id is not None:
        row = db.execute("SELECT weekday_plan FROM npc_autonomy_schedule WHERE npc_id=?", (int(npc_id),)).fetchone()
        if row:
            try:
                plan = json.loads(row["weekday_plan"] or "{}")
                custom = str(plan.get(key, "")).strip() if isinstance(plan, dict) else ""
                if custom:
                    return title, custom[:300]
            except (TypeError, ValueError, AttributeError):
                log.warning("Некорректное расписание NPC id=%s; используется стандартный распорядок", npc_id)
    defaults = {
        "Отдых": "Закончил смену и отдыхает; доступен только для обоснованного экстренного RP-вызова.",
        "Подготовка к смене": "Проверяет рабочее место, расписание и незавершённые поручения.",
        "Перерыв": "На перерыве, кратко обменивается новостями с коллегами.",
        "Передача смены": "Подводит итоги смены и передаёт незавершённые дела следующей смене.",
        "Рабочая смена": "Выполняет должностные обязанности и готовит служебные доклады руководству."
    }
    if title == "Рабочая смена" and faction == "Университет":
        defaults[title] = "Готовит занятия, проводит консультации и проверяет учебные материалы."
    elif title == "Рабочая смена" and rank in ("Лидер", "Декан", "Владелец", "Шеф", "Директор", "Генерал", "Командир"):
        defaults[title] = "Рассматривает доклады, распределяет поручения и контролирует подразделения."
    elif title == "Рабочая смена" and faction == "Больница":
        defaults[title] = "Выполняет обязанности медицинского персонала в рамках игровой смены."
    return title, defaults[title]


def _npc_autonomy_tick():
    """Фиксирует один слот автономной жизни каждого NPC; повторный тик не дублирует события."""
    if db.in_transaction:
        raise TransactionConflict("npc_autonomy_database_busy")
    now = datetime.now()
    slot = now.strftime("%Y%m%d%H") + ("00" if now.minute < 30 else "30")
    created = 0
    npcs = db.execute(
        "SELECT id,faction,name,rank FROM faction_npcs WHERE active=1 ORDER BY faction,id"
    ).fetchall()
    for npc in npcs:
        db.execute(
            "INSERT OR IGNORE INTO npc_autonomy_schedule(npc_id,weekday_plan,updated_at) VALUES(?,?,?)",
            (int(npc["id"]), "{}", now.isoformat(timespec="seconds"))
        )
        title, details = _npc_schedule_activity(now.hour, npc["faction"], npc["rank"], npc["id"])
        location = FACTION_NPC_LOCATIONS.get(npc["faction"], "Штаб организации")
        cur = db.execute(
            "INSERT OR IGNORE INTO npc_autonomy_events(npc_id,faction,event_type,title,details,location,event_slot,created_at) "
            "VALUES(?,?,?,?,?,?,?,?)",
            (int(npc["id"]), npc["faction"], "schedule", title, details, location, slot, now.isoformat(timespec="seconds"))
        )
        created += max(0, cur.rowcount)
    # Меж-NPC взаимодействие: совещания и передача докладов записываются как события,
    # но не меняют игровые ранги/решения и не имитируют реальные кадровые действия.
    if now.minute < 10 and 8 <= now.hour <= 20:
        factions = db.execute(
            "SELECT faction,COUNT(*) AS total FROM faction_npcs WHERE active=1 GROUP BY faction HAVING COUNT(*)>=2"
        ).fetchall()
        for faction_row in factions:
            faction = faction_row["faction"]
            pair = db.execute(
                "SELECT name,rank FROM faction_npcs WHERE faction=? AND active=1 ORDER BY last_activity_at,id LIMIT 2",
                (faction,)
            ).fetchall()
            if len(pair) < 2:
                continue
            leader_terms = ("Главарь", "Гангстер", "Крёстный отец", "Правая рука", "Бригадир", "Декан", "Владелец", "Заместитель владельца", "Управляющий", "Шеф", "Директор", "Генерал", "Командир")
            senior = next((x for x in pair if x["rank"] in leader_terms), pair[0])
            junior = pair[1] if senior is pair[0] else pair[0]
            meeting_event = db.execute(
                "INSERT OR IGNORE INTO npc_autonomy_events(npc_id,faction,event_type,title,details,location,event_slot,created_at) "
                "VALUES(0,?,'meeting',?,?,?,?,?)",
                (faction, "Внутреннее совещание",
                 f"{senior['name']} ({senior['rank']}) проводит рабочее совещание с {junior['name']} ({junior['rank']}) по текущей смене и докладам.",
                 FACTION_NPC_LOCATIONS.get(faction, "Штаб организации"), "npc-meeting-" + now.strftime("%Y%m%d"), now.isoformat(timespec="seconds"))
            )
            # Не только журнал: создаём реальную запись собрания в штатной системе,
            # чтобы она появилась в разделе «Собрания» и принимала RSVP сотрудников.
            if meeting_event.rowcount == 1:
                meeting_time = (now + timedelta(minutes=30)).replace(second=0, microsecond=0)
                db.execute(
                    "INSERT INTO faction_meetings(faction,creator_id,title,meeting_time,place,audience,status,summary,created_at) "
                    "VALUES(?,?,?,?,?,'Вся фракция','Запланировано',?,?)",
                    (faction, 0, "Рабочее совещание организации", meeting_time.isoformat(timespec="minutes"),
                     FACTION_NPC_LOCATIONS.get(faction, "Штаб организации"),
                     f"Организаторы: {senior['name']} ({senior['rank']}) и {junior['name']} ({junior['rank']}). Повестка: текущая смена, незавершённые доклады и распределение текущих рабочих вопросов.",
                     now.isoformat(timespec="seconds"))
                )
    if created or db.in_transaction:
        db.commit()
    return created


async def npc_autonomy_loop(bot_instance):
    """Автономная жизнь NPC работает независимо от присутствия игроков; сообщения игрокам не спамятся."""
    while True:
        await asyncio.sleep(300)
        try:
            _npc_autonomy_tick()
        except Exception:
            if db.in_transaction:
                db.rollback()
            log.exception("Ошибка автономного расписания NPC")


async def miniapp_npc_activity(request):
    """Персонализированный журнал активности NPC только для авторизованного игрока."""
    uid = int(request["telegram_user_id"])
    try:
        npc_id = int(request.query.get("npc_id", 0))
        limit = max(1, min(50, int(request.query.get("limit", 20))))
    except (TypeError, ValueError):
        return web.json_response({"error": "Некорректные параметры."}, status=400)
    npc = db.execute("SELECT id,name,faction,rank FROM faction_npcs WHERE id=? AND active=1", (npc_id,)).fetchone()
    if not npc:
        return web.json_response({"error": "NPC не найден."}, status=404)
    rows = db.execute(
        "SELECT event_type,title,details,location,created_at FROM npc_autonomy_events "
        "WHERE faction=? ORDER BY id DESC LIMIT ?", (npc["faction"], limit)
    ).fetchall()
    return web.json_response({
        "npc": {"id": int(npc["id"]), "name": npc["name"], "faction": npc["faction"], "rank": npc["rank"]},
        "items": [{"type": r["event_type"], "title": r["title"], "details": r["details"],
                   "location": r["location"], "created_at": r["created_at"]} for r in rows]
    })


