def _validate_miniapp_init_data(init_data: str):
    if not TOKEN or not init_data or len(init_data) > 8192:
        return None
    try:
        parsed_pairs = parse_qsl(init_data, keep_blank_values=True, strict_parsing=True)
        # Повторяющиеся ключи неоднозначны и не должны обходить проверку подписи.
        if len({key for key, _ in parsed_pairs}) != len(parsed_pairs):
            return None
        pairs = dict(parsed_pairs)
        received_hash = pairs.pop("hash", "")
        if not received_hash:
            return None
        auth_date = int(pairs.get("auth_date", "0"))
        now_ts = int(datetime.now().timestamp())
        if auth_date <= 0 or auth_date > now_ts + 60 or now_ts - auth_date > MINI_APP_MAX_AUTH_AGE:
            return None
        check_string = "\n".join(f"{k}={v}" for k, v in sorted(pairs.items()))
        secret = hmac.new(b"WebAppData", TOKEN.encode(), hashlib.sha256).digest()
        calculated = hmac.new(secret, check_string.encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(calculated, received_hash):
            return None
        user_data = json.loads(pairs.get("user", "{}"))
        uid = int(user_data.get("id", 0))
        return uid if uid > 0 else None
    except Exception:
        return None


@web.middleware
async def miniapp_auth_middleware(request, handler):
    if request.path.startswith("/api/"):
        init_data = request.headers.get("X-Telegram-Init-Data", "")
        uid = _validate_miniapp_init_data(init_data)
        if not uid:
            return web.json_response({"error": "Telegram authorization failed"}, status=401)
        if uid not in ADMIN_IDS:
            try:
                expire_temporary_bans(uid)
            except TransactionConflict:
                log.debug("Mini App: проверка временного бана отложена, база занята")
            except Exception:
                log.exception("Mini App: не удалось проверить срок блокировки пользователя %s", uid)
            player_state=db.execute("SELECT banned FROM players WHERE user_id=?",(uid,)).fetchone()
            if player_state and player_state["banned"]:
                return web.json_response({"error": "Аккаунт заблокирован."},status=403)
            jail = refresh_jail_state(uid)
            # Заключённый может открыть Mini App, посмотреть свой статус и подать
            # заявление на УДО. Остальные POST-действия остаются заблокированы.
            if jail and request.method != "GET" and request.path != "/api/parole":
                return web.json_response({"error": "Персонаж находится в игровом заключении."},status=403)
        request["telegram_user_id"] = uid
    return await handler(request)


