async def miniapp_npc_talk(request):
    uid = request["telegram_user_id"]
    try:
        payload = await request.json()
    except Exception:
        return web.json_response({"error": "Некорректный JSON."}, status=400)
    if not isinstance(payload, dict):
        return web.json_response({"error": "Ожидалось сообщение NPC."}, status=400)
    try:
        npc_id = int(payload.get("npc_id", 0))
    except (TypeError, ValueError):
        return web.json_response({"error": "Некорректный собеседник."}, status=400)
    user_text = str(payload.get("message", "")).strip()
    if not user_text or len(user_text) > 2000:
        return web.json_response({"error": "Сообщение должно содержать от 1 до 2000 символов."}, status=400)
    player = get_player(uid)
    if not player:
        return web.json_response({"error": "Сначала создай персонажа."}, status=404)
    if active_player_travel(uid):
        return web.json_response({"error": "Во время поездки поговорить с NPC нельзя. Дождись прибытия."}, status=409)
    npc = next((row for row in _nearby_npcs(player["location"]) if int(row["id"]) == npc_id), None)
    if not npc:
        return web.json_response({"error": "Этот NPC сейчас не находится рядом."}, status=404)
    recent = db.execute(
        "SELECT created_at FROM npc_ai_dialogue WHERE user_id=? ORDER BY id DESC LIMIT 1",
        (uid,)
    ).fetchone()
    if recent and recent["created_at"]:
        try:
            elapsed = (datetime.now() - datetime.fromisoformat(recent["created_at"])).total_seconds()
            if elapsed < 2.5:
                return web.json_response({"error": "Не торопись — подожди пару секунд перед следующим сообщением."}, status=429)
        except (TypeError, ValueError):
            pass
    db.execute(
        "INSERT INTO npc_ai_active_chat(user_id,npc_id,started_at) VALUES(?,?,?) "
        "ON CONFLICT(user_id) DO UPDATE SET npc_id=excluded.npc_id,started_at=excluded.started_at",
        (uid, npc_id, now_text())
    )
    db.commit()
    reply = await _npc_ai_generate(
        npc, player,
        f"{player_display_name(player)} обращается к тебе через Mini App: {user_text}",
        channel="личный разговор через Mini App", memory_user_id=uid
    )
    if not reply:
        return web.json_response({"error": "NPC сейчас не смог ответить. Попробуй ещё раз."}, status=503)
    return web.json_response({"ok": True, "npc": npc["name"], "reply": reply})


async def miniapp_travel(request):
    uid = request["telegram_user_id"]
    try:
        payload = await request.json()
    except Exception:
        return web.json_response({"error": "Некорректный JSON."}, status=400)
    if not isinstance(payload, dict):
        return web.json_response({"error": "Ожидался объект маршрута."}, status=400)
    destination = str(payload.get("destination", "")).strip()
    mode = str(payload.get("mode", "walk")).strip()
    try:
        vehicle_id = int(payload.get("vehicle_id", 0) or 0)
    except (TypeError, ValueError):
        return web.json_response({"error": "Некорректный автомобиль."}, status=400)
    if destination not in LOCATIONS or mode not in ("walk", "vehicle"):
        return web.json_response({"error": "Некорректный маршрут."}, status=400)
    if mode == "vehicle" and not db.execute("SELECT 1 FROM vehicles WHERE id=? AND user_id=?", (vehicle_id, uid)).fetchone():
        return web.json_response({"error": "Выбери свой автомобиль."}, status=404)
    try:
        travel, error = begin_player_travel(uid, destination, mode, vehicle_id=vehicle_id)
        if error:
            return web.json_response({"error": error}, status=409)
        return web.json_response({"ok": True, "travel": travel})
    except TransactionConflict:
        return web.json_response({"error": "Система занята другой операцией. Повтори чуть позже."}, status=409)


async def miniapp_university(request):
    uid = request["telegram_user_id"]
    create_player(uid)
    player = get_player(uid)
    student = is_student(uid)
    staff = university_employee(uid)
    documents_ok = has_university_documents(uid)
    subjects = []
    for subject in SUBJECTS:
        lesson = db.execute("SELECT points,completed FROM lessons WHERE user_id=? AND subject=?", (uid, subject)).fetchone()
        latest_test = db.execute("SELECT score,grade,passed,taken_at FROM university_tests WHERE user_id=? AND subject=? ORDER BY id DESC LIMIT 1", (uid, subject)).fetchone()
        subjects.append({
            "name": subject,
            "points": int(lesson["points"] or 0) if lesson else 0,
            "completed": bool(lesson["completed"]) if lesson else False,
            "passed": bool(latest_test["passed"]) if latest_test else False,
            "grade": int(latest_test["grade"] or 2) if latest_test else 0,
            "last_test": latest_test["taken_at"] if latest_test else ""
        })
    final = db.execute("SELECT score,passed,taken_at FROM university_final WHERE user_id=?", (uid,)).fetchone()
    return web.json_response({
        "student": student,
        "employee": staff,
        "location": player["location"],
        "education": player["education"],
        "documents_ok": documents_ok,
        "can_enroll": not student and player["education"] != "Высшее" and documents_ok and player["location"] == "Университет",
        "can_request_lecture": student and player["location"] == "Университет",
        "subjects": subjects,
        "final": {"score": int(final["score"] or 0), "passed": bool(final["passed"]), "taken_at": final["taken_at"] or ""} if final else None
    })


async def miniapp_university_enroll(request):
    uid = request["telegram_user_id"]
    create_player(uid)
    player = get_player(uid)
    if not player:
        return web.json_response({"error": "Персонаж не найден."}, status=404)
    if player["location"] != "Университет":
        return web.json_response({"error": "Для зачисления нужно находиться в университете."}, status=409)
    if player["education"] == "Высшее":
        return web.json_response({"error": "У тебя уже получено высшее образование."}, status=409)
    if not has_university_documents(uid):
        return web.json_response({"error": "Нужны паспорт, медицинская карта и трудовая книжка."}, status=409)
    if is_student(uid):
        return web.json_response({"error": f"Ты уже {gender_form(player, 'зачислен', 'зачислена')} в университет."}, status=409)
    try:
        begin_immediate()
        fresh = get_player(uid)
        if not fresh or fresh["location"] != "Университет" or fresh["education"] == "Высшее" or not has_university_documents(uid) or is_student(uid):
            db.rollback()
            return web.json_response({"error": "Условия зачисления изменились. Обнови данные и попробуй снова."}, status=409)
        db.execute(
            "INSERT INTO university_students(user_id,enrolled_at,active) VALUES(?,?,1) "
            "ON CONFLICT(user_id) DO UPDATE SET active=1,enrolled_at=excluded.enrolled_at",
            (uid, now_text())
        )
        db.commit()
        return web.json_response({"ok": True, "message": f"Ты {gender_form(fresh, 'зачислен', 'зачислена')} в университет."})
    except TransactionConflict:
        return web.json_response({"error": "Система занята другой операцией. Повтори чуть позже."}, status=409)
    except sqlite3.Error:
        if db.in_transaction:
            db.rollback()
        log.exception("Mini App: не удалось зачислить студента %s", uid)
        return web.json_response({"error": "Не удалось сохранить зачисление."}, status=500)


