async def miniapp_store(request):
    uid = request["telegram_user_id"]
    try:
        _settle_property_taxes(uid)
    except TransactionConflict:
        return web.json_response({"error": "Расчёт налогов временно занят. Обнови магазин чуть позже."}, status=409)
    except sqlite3.Error:
        log.exception("Mini App: не удалось пересчитать налог на недвижимость пользователя %s", uid)
        return web.json_response({"error": "Не удалось обновить налоговую задолженность."}, status=500)
    properties = db.execute(
        "SELECT c.id,c.name,c.district,c.kind,c.price,c.daily_tax,c.description,CASE WHEN o.id IS NULL THEN 0 ELSE 1 END AS owned,o.id AS ownership_id,COALESCE(o.tax_debt,0) AS tax_debt "
        "FROM property_catalog c LEFT JOIN property_ownership o ON o.property_id=c.id AND o.user_id=? ORDER BY c.price",
        (uid,)
    ).fetchall()
    businesses = db.execute(
        "SELECT c.id,c.name,c.category,c.price,c.income_per_day,c.description,CASE WHEN b.id IS NULL THEN 0 ELSE 1 END AS owned,b.id AS ownership_id,b.last_collect,b.total_income "
        "FROM business_catalog c LEFT JOIN player_businesses b ON b.business_id=c.id AND b.user_id=? ORDER BY c.price",
        (uid,)
    ).fetchall()
    business_payload = []
    for row in businesses:
        try:
            elapsed = (datetime.now() - datetime.fromisoformat(row["last_collect"])).total_seconds()
        except (ValueError, TypeError):
            elapsed = 86400
        business_payload.append({
            **dict(row),
            "can_collect": bool(row["owned"] and elapsed >= 86400),
            "hours_remaining": max(0, int((86400 - elapsed + 3599) // 3600))
        })
    vehicles = [{"key": key, "name": value[0], "price": int(value[1])} for key, value in WEST_CARS.items()]
    return web.json_response({
        "properties": [dict(row) for row in properties],
        "businesses": business_payload,
        "vehicles": vehicles
    })


async def miniapp_store_buy(request):
    uid = request["telegram_user_id"]
    try:
        payload = await request.json()
    except Exception:
        return web.json_response({"error": "Некорректный JSON."}, status=400)
    if not isinstance(payload, dict):
        return web.json_response({"error": "Ожидался объект покупки."}, status=400)
    kind = str(payload.get("kind", ""))
    try:
        item_id = int(payload.get("id", 0) or 0)
    except (TypeError, ValueError):
        return web.json_response({"error": "Некорректный ID товара."}, status=400)
    vehicle_key = str(payload.get("vehicle_key", ""))
    if kind not in ("property", "business", "vehicle"):
        return web.json_response({"error": "Неизвестная категория товара."}, status=400)
    if kind == "vehicle" and vehicle_key not in WEST_CARS:
        return web.json_response({"error": "Автомобиль не найден в каталоге."}, status=404)
    try:
        begin_immediate()
        player = db.execute("SELECT balance FROM players WHERE user_id=?", (uid,)).fetchone()
        if not player:
            db.rollback()
            return web.json_response({"error": "Персонаж не найден."}, status=404)
        if kind == "property":
            item = db.execute("SELECT * FROM property_catalog WHERE id=?", (item_id,)).fetchone()
            if not item:
                db.rollback(); return web.json_response({"error": "Объект недвижимости не найден."}, status=404)
            price = int(item["price"])
            name = item["name"]
            if db.execute("SELECT 1 FROM property_ownership WHERE property_id=?", (item_id,)).fetchone():
                db.rollback(); return web.json_response({"error": "Этот объект уже принадлежит другому игроку."}, status=409)
        elif kind == "business":
            item = db.execute("SELECT * FROM business_catalog WHERE id=?", (item_id,)).fetchone()
            if not item:
                db.rollback(); return web.json_response({"error": "Бизнес не найден."}, status=404)
            price = int(item["price"])
            name = item["name"]
            if db.execute("SELECT 1 FROM player_businesses WHERE business_id=?", (item_id,)).fetchone():
                db.rollback(); return web.json_response({"error": "Этот бизнес уже принадлежит другому игроку."}, status=409)
        else:
            name, price = WEST_CARS[vehicle_key]
            price = int(price)
        if price < 0 or int(player["balance"]) < price:
            db.rollback()
            return web.json_response({"error": "Недостаточно средств."}, status=409)
        debit = db.execute("UPDATE players SET balance=balance-? WHERE user_id=? AND balance>=?", (price, uid, price))
        if debit.rowcount != 1:
            db.rollback()
            return web.json_response({"error": "Баланс изменился. Обнови Mini App и попробуй снова."}, status=409)
        if kind == "property":
            db.execute("INSERT INTO property_ownership(user_id,property_id,purchased_at,last_tax_date) VALUES(?,?,?,?)", (uid, item_id, now_text(), datetime.now().date().isoformat()))
            _west_log_money(uid, price, "property", f"Покупка недвижимости: {name}")
        elif kind == "business":
            db.execute("INSERT INTO player_businesses(user_id,business_id,last_collect,purchased_at) VALUES(?,?,?,?)", (uid, item_id, now_text(), now_text()))
            db.execute("INSERT INTO business_ledger(business_owner,amount,entry_type,description,created_at) VALUES(?,?,'purchase',?,?)", (uid, -price, name, now_text()))
            _west_log_money(uid, price, "business", f"Покупка бизнеса: {name}")
        else:
            cur = db.execute("INSERT INTO vehicles(user_id,vehicle_name,purchased_at,fuel,condition,plate) VALUES(?,?,?,100,100,'')", (uid, name, now_text()))
            plate = _west_car_plate(cur.lastrowid, uid)
            db.execute("UPDATE vehicles SET plate=? WHERE id=?", (plate, cur.lastrowid))
            _west_log_money(uid, price, "vehicle", f"Покупка автомобиля {name}")
        db.commit()
        return web.json_response({"ok": True, "kind": kind, "name": name, "price": price})
    except TransactionConflict:
        return web.json_response({"error": "Система занята другой операцией. Повтори чуть позже."}, status=409)
    except sqlite3.IntegrityError:
        if db.in_transaction:
            db.rollback()
        return web.json_response({"error": "Этот товар уже куплен или недоступен."}, status=409)
    except sqlite3.Error:
        if db.in_transaction:
            db.rollback()
        log.exception("Mini App: ошибка покупки %s для пользователя %s", kind, uid)
        return web.json_response({"error": "Не удалось завершить покупку."}, status=500)


async def miniapp_property_sell(request):
    uid = request["telegram_user_id"]
    try:
        payload = await request.json()
        ownership_id = int(payload.get("ownership_id", 0)) if isinstance(payload, dict) else 0
    except Exception:
        return web.json_response({"error": "Некорректные данные продажи."}, status=400)
    if ownership_id <= 0:
        return web.json_response({"error": "Объект недвижимости не найден."}, status=400)
    try:
        _settle_property_taxes(uid)
    except TransactionConflict:
        return web.json_response({"error": "Система занята другой операцией. Повтори позже."}, status=409)
    except sqlite3.Error:
        log.exception("Mini App: не удалось пересчитать налог перед продажей недвижимости")
        return web.json_response({"error": "Не удалось проверить налоговую задолженность."}, status=500)
    try:
        begin_immediate()
        row = db.execute(
            "SELECT o.id,o.tax_debt,c.name,c.price FROM property_ownership o JOIN property_catalog c ON c.id=o.property_id WHERE o.id=? AND o.user_id=?",
            (ownership_id, uid)
        ).fetchone()
        if not row:
            db.rollback()
            return web.json_response({"error": "Эта недвижимость тебе не принадлежит."}, status=404)
        if int(row["tax_debt"] or 0) > 0:
            db.rollback()
            return web.json_response({"error": "Сначала погаси налоговую задолженность."}, status=409)
        amount = int(int(row["price"]) * 0.70)
        changed = db.execute("UPDATE players SET balance=balance+? WHERE user_id=? AND balance<=?", (amount, uid, MAX_BALANCE - amount))
        if changed.rowcount != 1:
            db.rollback()
            return web.json_response({"error": "Продажа отклонена: превышен лимит игрового баланса."}, status=409)
        db.execute("DELETE FROM property_ownership WHERE id=? AND user_id=?", (ownership_id, uid))
        db.execute("INSERT INTO bank_transactions(user_id,other_user_id,amount,transaction_type,description,created_at) VALUES(?,0,?,'property_sale',?,?)", (uid, amount, f"Продажа недвижимости: {row['name']}", now_text()))
        db.commit()
        return web.json_response({"ok": True, "name": row["name"], "amount": amount})
    except TransactionConflict:
        return web.json_response({"error": "Система занята другой операцией. Повтори позже."}, status=409)
    except sqlite3.Error:
        if db.in_transaction:
            db.rollback()
        log.exception("Mini App: ошибка продажи недвижимости пользователя %s", uid)
        return web.json_response({"error": "Не удалось продать недвижимость."}, status=500)


async def miniapp_business_collect(request):
    uid = request["telegram_user_id"]
    try:
        payload = await request.json()
        owned_id = int(payload.get("ownership_id", 0)) if isinstance(payload, dict) else 0
    except Exception:
        return web.json_response({"error": "Некорректные данные бизнеса."}, status=400)
    if owned_id <= 0:
        return web.json_response({"error": "Бизнес не найден."}, status=400)
    try:
        begin_immediate()
        row = db.execute(
            "SELECT pb.*,bc.name,bc.income_per_day FROM player_businesses pb JOIN business_catalog bc ON bc.id=pb.business_id WHERE pb.id=? AND pb.user_id=?",
            (owned_id, uid)
        ).fetchone()
        if not row:
            db.rollback()
            return web.json_response({"error": "Этот бизнес тебе не принадлежит."}, status=404)
        try:
            elapsed = (datetime.now() - datetime.fromisoformat(row["last_collect"])).total_seconds()
        except (ValueError, TypeError):
            elapsed = 86400
        if elapsed < 86400:
            db.rollback()
            return web.json_response({"error": f"Доход будет доступен через {max(1, int((86400-elapsed)//3600))} ч."}, status=409)
        cycles = min(7, max(1, int(elapsed // 86400)))
        gross = int(row["income_per_day"]) * cycles
        tax = max(0, int(gross * 0.05))
        amount = gross - tax
        credited = db.execute("UPDATE players SET balance=balance+? WHERE user_id=? AND balance<=?", (amount, uid, MAX_BALANCE - amount))
        if credited.rowcount != 1:
            db.rollback()
            return web.json_response({"error": "Доход не зачислен: достигнут лимит игрового баланса."}, status=409)
        db.execute("UPDATE player_businesses SET last_collect=?,total_income=total_income+? WHERE id=? AND user_id=?", (now_text(), amount, owned_id, uid))
        db.execute("INSERT INTO business_ledger(business_owner,amount,entry_type,description,created_at) VALUES(?,?,'income',?,?)", (uid, amount, f"Доход {row['name']} за {cycles} дн.", now_text()))
        _west_log_money(uid, amount, "business_income", f"Доход бизнеса {row['name']} после налога")
        db.commit()
        return web.json_response({"ok": True, "name": row["name"], "amount": amount, "tax": tax, "cycles": cycles})
    except TransactionConflict:
        return web.json_response({"error": "Система занята другой операцией. Повтори позже."}, status=409)
    except sqlite3.Error:
        if db.in_transaction:
            db.rollback()
        log.exception("Mini App: ошибка сбора дохода бизнеса %s пользователя %s", owned_id, uid)
        return web.json_response({"error": "Не удалось собрать доход."}, status=500)


async def miniapp_vehicle_action(request):
    uid = request["telegram_user_id"]
    try:
        payload = await request.json()
    except Exception:
        return web.json_response({"error": "Некорректный JSON."}, status=400)
    if not isinstance(payload, dict):
        return web.json_response({"error": "Ожидались данные автомобиля."}, status=400)
    try:
        vehicle_id = int(payload.get("vehicle_id", 0))
    except (TypeError, ValueError):
        return web.json_response({"error": "Некорректный автомобиль."}, status=400)
    action = str(payload.get("action", ""))
    if action not in ("refuel", "service"):
        return web.json_response({"error": "Неизвестная операция."}, status=400)
    cost = 250 if action == "refuel" else 500
    try:
        begin_immediate()
        vehicle = db.execute("SELECT * FROM vehicles WHERE id=? AND user_id=?", (vehicle_id, uid)).fetchone()
        player = db.execute("SELECT balance FROM players WHERE user_id=?", (uid,)).fetchone()
        if not vehicle or not player:
            db.rollback()
            return web.json_response({"error": "Автомобиль не найден."}, status=404)
        if action == "refuel" and int(vehicle["fuel"] or 0) >= 100:
            db.rollback()
            return web.json_response({"error": "Бак уже полный."}, status=409)
        if action == "service" and int(vehicle["condition"] or 0) >= 100:
            db.rollback()
            return web.json_response({"error": "Автомобиль не нуждается в обслуживании."}, status=409)
        if int(player["balance"] or 0) < cost:
            db.rollback()
            return web.json_response({"error": "Недостаточно денег."}, status=409)
        debit = db.execute("UPDATE players SET balance=balance-? WHERE user_id=? AND balance>=?", (cost, uid, cost))
        if debit.rowcount != 1:
            db.rollback()
            return web.json_response({"error": "Баланс изменился. Обнови Mini App."}, status=409)
        if action == "refuel":
            db.execute("UPDATE vehicles SET fuel=100 WHERE id=? AND user_id=?", (vehicle_id, uid))
            service_type = "refuel"
            description = f"Заправка {vehicle['vehicle_name']}"
        else:
            db.execute("UPDATE vehicles SET condition=100 WHERE id=? AND user_id=?", (vehicle_id, uid))
            service_type = "repair"
            description = f"Обслуживание {vehicle['vehicle_name']}"
        db.execute("INSERT INTO vehicle_service_log(vehicle_id,user_id,service_type,amount,created_at) VALUES(?,?,?,?,?)", (vehicle_id, uid, service_type, cost, now_text()))
        _west_log_money(uid, cost, service_type, description)
        db.commit()
        return web.json_response({"ok": True, "vehicle": vehicle["vehicle_name"], "action": action, "cost": cost})
    except TransactionConflict:
        return web.json_response({"error": "Система занята другой операцией. Повтори чуть позже."}, status=409)
    except sqlite3.Error:
        if db.in_transaction:
            db.rollback()
        log.exception("Mini App: ошибка обслуживания автомобиля %s пользователя %s", vehicle_id, uid)
        return web.json_response({"error": "Не удалось выполнить операцию с автомобилем."}, status=500)


async def miniapp_checklist(request):
    uid = request["telegram_user_id"]
    create_player(uid)
    p = get_player(uid)
    if p["faction"] not in FACTIONS and not university_employee(uid):
        return web.json_response({"done": 0, "total": 0, "eligible": False, "items": []})
    rows = _checklist_progress(uid, p)
    items = [{"title": r["title"], "description": r["description"], "type": r["check_type"], "done": bool(ok)} for r, ok in rows]
    done = sum(1 for _, ok in rows if ok)
    return web.json_response({"done": done, "total": len(rows), "eligible": bool(rows) and done == len(rows), "items": items})


async def miniapp_work(request):
    uid = request["telegram_user_id"]
    player = _work_member(uid)
    if not player:
        if is_student(uid):
            student = get_player(uid)
            return web.json_response({"faction": "Университет", "rank": "Студент", "gender": student["gender"] or "Не указан", "employee": False, "university_student": True, "active": None})
        return web.json_response({"faction": "Нет", "employee": False, "university_student": False, "active": None})
    active = db.execute("SELECT id,task_key,task_title,task_description,status,stage_index FROM faction_work_sessions WHERE user_id=? AND status IN ('Ожидает отчёта','В работе','На проверке') ORDER BY id DESC LIMIT 1", (uid,)).fetchone()
    active_payload = None
    if active:
        steps = _faction_work_steps(player["faction"], active["task_key"])
        stage_index = max(0, int(active["stage_index"] or 0))
        active_payload = {"id": active["id"], "title": active["task_title"], "description": active["task_description"], "status": active["status"], "stage_index": stage_index, "stage_count": len(steps), "next_stage": steps[stage_index] if stage_index < len(steps) else "Отправить итоговый отчёт"}
    return web.json_response({"faction": player["faction"], "rank": player["rank"], "employee": True, "university_student": is_student(uid), "active": active_payload})


async def miniapp_work_take(request):
    uid = request["telegram_user_id"]
    player = _work_member(uid)
    if not player:
        return web.json_response({"error": "Ты не состоишь в действующей фракции."}, status=403)
    if player["faction"] == "Университет" and player["location"] != "Университет":
        return web.json_response({"error": "Для получения служебного поручения нужно находиться в кампусе."}, status=409)
    try:
        begin_immediate()
        active = db.execute("SELECT id FROM faction_work_sessions WHERE user_id=? AND status IN ('Ожидает отчёта','В работе','На проверке') LIMIT 1", (uid,)).fetchone()
        if active:
            db.rollback(); return web.json_response({"error": "Сначала заверши текущее поручение."}, status=409)
        today = datetime.now().date().isoformat()
        completed = db.execute("SELECT COUNT(*) FROM faction_work_log WHERE user_id=? AND faction=? AND substr(created_at,1,10)=?", (uid, player["faction"], today)).fetchone()[0]
        if completed >= 5:
            db.rollback(); return web.json_response({"error": "Дневной лимит поручений исчерпан."}, status=429)
        tasks = _work_tasks_for(player)
        last = db.execute("SELECT task_key FROM faction_work_log WHERE user_id=? AND faction=? ORDER BY id DESC LIMIT 1", (uid, player["faction"])).fetchone()
        choices = [t for t in tasks if not last or t[0] != last["task_key"]] or tasks
        task = random.choice(choices)
        cur = db.execute("INSERT INTO faction_work_sessions(user_id,faction,department,task_key,task_title,task_description,status,report,reward,created_at,completed_at) VALUES(?,?,?,?,?,?, 'В работе','',?,?, '')", (uid, player["faction"], _department_for(uid), task[0], task[1], task[2], task[3], now_text()))
        db.commit()
        return web.json_response({"ok": True, "session_id": cur.lastrowid})
    except TransactionConflict:
        return web.json_response({"error": "Система занята другой операцией. Повтори чуть позже."}, status=409)
    except sqlite3.Error:
        if db.in_transaction: db.rollback()
        log.exception("Mini App: выдача поручения не удалась")
        return web.json_response({"error": "Не удалось выдать поручение."}, status=500)


async def miniapp_work_stage(request):
    uid = request["telegram_user_id"]
    try:
        payload = await request.json()
        session_id = int(payload.get("session_id", 0))
        expected_stage = int(payload.get("stage_index", -1))
    except Exception:
        return web.json_response({"error": "Некорректный запрос этапа."}, status=400)
    player = _work_member(uid)
    if not player:
        return web.json_response({"error": "Ты не состоишь в действующей фракции."}, status=403)
    try:
        begin_immediate()
        row = db.execute("SELECT * FROM faction_work_sessions WHERE id=? AND user_id=? AND status='В работе'", (session_id, uid)).fetchone()
        if not row or row["faction"] != player["faction"]:
            db.rollback()
            return web.json_response({"error": "Поручение не найдено."}, status=404)
        steps = _faction_work_steps(row["faction"], row["task_key"])
        current_stage = max(0, int(row["stage_index"] or 0))
        if current_stage != expected_stage or current_stage >= len(steps):
            db.rollback()
            return web.json_response({"error": "Этап уже пройден или недоступен."}, status=409)
        if current_stage > 0:
            try:
                elapsed = (datetime.now() - datetime.fromisoformat(row["stage_updated_at"] or row["created_at"])).total_seconds()
            except (TypeError, ValueError):
                elapsed = 0
            if elapsed < 10:
                db.rollback()
                return web.json_response({"error": "Между этапами нужно подождать 10 секунд."}, status=409)
        changed = db.execute("UPDATE faction_work_sessions SET stage_index=stage_index+1,stage_updated_at=? WHERE id=? AND user_id=? AND status='В работе' AND stage_index=?", (now_text(), session_id, uid, expected_stage))
        if changed.rowcount != 1:
            db.rollback()
            return web.json_response({"error": "Этап уже изменился."}, status=409)
        updated = db.execute("SELECT stage_index FROM faction_work_sessions WHERE id=?", (session_id,)).fetchone()
        db.commit()
        next_index = int(updated["stage_index"] or 0)
        return web.json_response({"ok": True, "stage_index": next_index, "stage_count": len(steps), "next_stage": steps[next_index] if next_index < len(steps) else "Отправить итоговый отчёт"})
    except TransactionConflict:
        return web.json_response({"error": "Система занята другой операцией. Повтори чуть позже."}, status=409)
    except sqlite3.Error:
        if db.in_transaction:
            db.rollback()
        log.exception("Mini App: переход этапа поручения не удался")
        return web.json_response({"error": "Не удалось сохранить этап."}, status=500)



# Idempotency keys protect Mini App write operations from repeated taps and retried HTTP requests.
db.execute("""CREATE TABLE IF NOT EXISTS university_lecture_sessions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    npc_id INTEGER NOT NULL,
    subject TEXT NOT NULL,
    lecture_text TEXT NOT NULL,
    created_at TEXT NOT NULL
)""")
db.execute("""CREATE TABLE IF NOT EXISTS miniapp_operation_claims (
    user_id INTEGER NOT NULL,
    operation TEXT NOT NULL,
    request_key TEXT NOT NULL,
    result_json TEXT NOT NULL DEFAULT '',
    created_at TEXT NOT NULL,
    PRIMARY KEY(user_id,operation,request_key)
)""")
db.commit()


def _miniapp_claim_request(user_id, operation, request_key):
    row = db.execute(
        "SELECT result_json FROM miniapp_operation_claims WHERE user_id=? AND operation=? AND request_key=?",
        (user_id, operation, request_key)
    ).fetchone()
    if row:
        try:
            return json.loads(row["result_json"]) if row["result_json"] else {"error": "Операция уже выполняется."}
        except (TypeError, ValueError):
            return {"error": "Операция уже выполняется."}
    db.execute(
        "INSERT INTO miniapp_operation_claims(user_id,operation,request_key,result_json,created_at) VALUES(?,?,?,'',?)",
        (user_id, operation, request_key, now_text())
    )
    return None


def _miniapp_finish_request(user_id, operation, request_key, result):
    db.execute(
        "UPDATE miniapp_operation_claims SET result_json=? WHERE user_id=? AND operation=? AND request_key=?",
        (json.dumps(result, ensure_ascii=False, separators=(",", ":")), user_id, operation, request_key)
    )


async def miniapp_bank(request):
    uid = request["telegram_user_id"]
    player = get_player(uid)
    if not player:
        return web.json_response({"error": "Персонаж не найден."}, status=404)
    rows = db.execute(
        "SELECT id,other_user_id,amount,transaction_type,description,created_at FROM bank_transactions WHERE user_id=? ORDER BY id DESC LIMIT 30",
        (uid,)
    ).fetchall()
    items = []
    for row in rows:
        other_id = int(row["other_user_id"] or 0)
        other = get_player(other_id) if other_id > 0 else None
        items.append({
            "id": int(row["id"]), "amount": int(row["amount"]),
            "type": row["transaction_type"], "description": row["description"] or "",
            "created_at": row["created_at"] or "",
            "other": player_display_name(other, "Система") if other else "Система",
            "direction": "in" if row["transaction_type"] in ("transfer_in", "salary", "work_reward", "admin_grant", "business_income") else "out"
        })
    return web.json_response({"balance": int(player["balance"] or 0), "items": items})


async def miniapp_bank_transfer(request):
    uid = request["telegram_user_id"]
    try:
        payload = await request.json()
    except Exception:
        return web.json_response({"error": "Некорректный JSON."}, status=400)
    if not isinstance(payload, dict):
        return web.json_response({"error": "Ожидались данные перевода."}, status=400)
    try:
        receiver_game_id = int(payload.get("receiver_game_id", 0))
        amount = int(payload.get("amount", 0))
    except (TypeError, ValueError):
        return web.json_response({"error": "Игровой ID и сумма должны быть числами."}, status=400)
    request_key = str(payload.get("request_key", "")).strip()
    if not 8 <= len(request_key) <= 128:
        return web.json_response({"error": "Не удалось подтвердить запрос перевода. Повтори попытку."}, status=400)
    if receiver_game_id <= 0 or amount <= 0 or amount > 1_000_000_000:
        return web.json_response({"error": "Проверь игровой ID и сумму перевода."}, status=400)
    receiver = get_player_by_game_id(receiver_game_id)
    if not receiver:
        return web.json_response({"error": "Получатель с таким игровым ID не найден."}, status=404)
    receiver_id = int(receiver["user_id"])
    if receiver_id == uid:
        return web.json_response({"error": "Нельзя переводить деньги самому себе."}, status=409)
    try:
        begin_immediate()
        replay = _miniapp_claim_request(uid, "bank_transfer", request_key)
        if replay is not None:
            db.rollback()
            if "error" in replay:
                return web.json_response(replay, status=409)
            return web.json_response(replay)
        sender = db.execute("SELECT balance,banned FROM players WHERE user_id=?", (uid,)).fetchone()
        fresh_receiver = db.execute("SELECT balance,banned FROM players WHERE user_id=?", (receiver_id,)).fetchone()
        if not sender or sender["banned"]:
            db.rollback(); return web.json_response({"error": "Персонаж не найден или заблокирован."}, status=403)
        if not fresh_receiver or fresh_receiver["banned"]:
            db.rollback(); return web.json_response({"error": "Получатель недоступен для перевода."}, status=409)
        if int(sender["balance"] or 0) < amount:
            db.rollback(); return web.json_response({"error": "Недостаточно средств."}, status=409)
        if int(fresh_receiver["balance"] or 0) > MAX_BALANCE - amount:
            db.rollback(); return web.json_response({"error": "У получателя достигнут лимит игрового баланса."}, status=409)
        debited = db.execute("UPDATE players SET balance=balance-? WHERE user_id=? AND balance>=?", (amount, uid, amount))
        credited = db.execute("UPDATE players SET balance=balance+? WHERE user_id=? AND balance<=?", (amount, receiver_id, MAX_BALANCE-amount))
        if debited.rowcount != 1 or credited.rowcount != 1:
            raise sqlite3.IntegrityError("bank_transfer_balance_changed")
        created = now_text()
        db.execute("INSERT INTO bank_transactions(user_id,other_user_id,amount,transaction_type,description,created_at) VALUES(?,?,?,'transfer_out','Перевод игроку',?)", (uid, receiver_id, amount, created))
        db.execute("INSERT INTO bank_transactions(user_id,other_user_id,amount,transaction_type,description,created_at) VALUES(?,?,?,'transfer_in','Получен перевод',?)", (receiver_id, uid, amount, created))
        result = {"ok": True, "amount": amount, "receiver": player_display_name(receiver), "balance": int(sender["balance"]) - amount}
        _miniapp_finish_request(uid, "bank_transfer", request_key, result)
        db.commit()
        return web.json_response(result)
    except TransactionConflict:
        return web.json_response({"error": "Банк временно занят. Повтори чуть позже."}, status=409)
    except sqlite3.Error:
        if db.in_transaction: db.rollback()
        log.exception("Mini App: банковский перевод %s -> %s не выполнен", uid, receiver_id)
        return web.json_response({"error": "Не удалось выполнить перевод."}, status=500)


async def miniapp_inventory(request):
    uid = request["telegram_user_id"]
    rows = db.execute("SELECT id,item_name,quantity FROM inventory WHERE user_id=? AND quantity>0 ORDER BY item_name", (uid,)).fetchall()
    return web.json_response({"items": [
        {"id": int(row["id"]), "name": row["item_name"], "quantity": int(row["quantity"]),
         "can_use": row["item_name"] in ("Аптечка", "Набор инструментов")}
        for row in rows
    ]})


async def miniapp_inventory_use(request):
    uid = request["telegram_user_id"]
    try:
        payload = await request.json()
        item_id = int(payload.get("item_id", 0))
    except Exception:
        return web.json_response({"error": "Некорректный предмет."}, status=400)
    request_key = str(payload.get("request_key", "")).strip()
    if item_id <= 0 or not 8 <= len(request_key) <= 128:
        return web.json_response({"error": "Не удалось подтвердить использование предмета."}, status=400)
    try:
        begin_immediate()
        replay = _miniapp_claim_request(uid, "inventory_use", request_key)
        if replay is not None:
            db.rollback()
            if "error" in replay: return web.json_response(replay, status=409)
            return web.json_response(replay)
        item = db.execute("SELECT id,item_name,quantity FROM inventory WHERE id=? AND user_id=? AND quantity>0", (item_id, uid)).fetchone()
        if not item:
            db.rollback(); return web.json_response({"error": "Предмет не найден или уже использован."}, status=404)
        if item["item_name"] == "Аптечка":
            db.execute("INSERT OR IGNORE INTO documents(user_id) VALUES(?)", (uid,))
            changed = db.execute("UPDATE documents SET fractures=0,cold=0 WHERE user_id=? AND (fractures<>0 OR cold<>0)", (uid,))
            if changed.rowcount != 1:
                db.rollback(); return web.json_response({"error": "Аптечка сейчас не требуется."}, status=409)
            result_text = "Аптечка использована: игровые травмы и простуда устранены."
        elif item["item_name"] == "Набор инструментов":
            vehicle = db.execute("SELECT id,vehicle_name,condition FROM vehicles WHERE user_id=? AND condition<100 ORDER BY condition ASC,id ASC LIMIT 1", (uid,)).fetchone()
            if not vehicle:
                db.rollback(); return web.json_response({"error": "Нет повреждённого автомобиля для ремонта."}, status=409)
            db.execute("UPDATE vehicles SET condition=MIN(100,condition+25) WHERE id=? AND user_id=?", (vehicle["id"], uid))
            result_text = f"Набор инструментов использован. {vehicle['vehicle_name']} восстановлен на 25 пунктов состояния."
        else:
            db.rollback(); return web.json_response({"error": "У этого предмета пока нет механики использования."}, status=409)
        consumed = db.execute("UPDATE inventory SET quantity=quantity-1 WHERE id=? AND user_id=? AND quantity>0", (item_id, uid))
        if consumed.rowcount != 1: raise sqlite3.IntegrityError("inventory_consumption_failed")
        db.execute("DELETE FROM inventory WHERE id=? AND quantity<=0", (item_id,))
        result = {"ok": True, "message": result_text}
        _miniapp_finish_request(uid, "inventory_use", request_key, result)
        db.commit()
        return web.json_response(result)
    except TransactionConflict:
        return web.json_response({"error": "Инвентарь временно занят. Повтори чуть позже."}, status=409)
    except sqlite3.Error:
        if db.in_transaction: db.rollback()
        log.exception("Mini App: ошибка использования предмета %s пользователя %s", item_id, uid)
        return web.json_response({"error": "Не удалось использовать предмет."}, status=500)


async def miniapp_courts(request):
    uid = request["telegram_user_id"]
    player = get_player(uid)
    if not player:
        return web.json_response({"items": [], "can_open_case": False})
    if _is_judge(player) or is_admin(uid):
        rows = db.execute("SELECT * FROM court_cases ORDER BY id DESC LIMIT 30").fetchall()
    else:
        rows = db.execute("SELECT * FROM court_cases WHERE client_id=? OR lawyer_id=? OR judge_id=? ORDER BY id DESC LIMIT 30", (uid, uid, uid)).fetchall()
    items = []
    for row in rows:
        client = get_player(int(row["client_id"]))
        lawyer = get_player(int(row["lawyer_id"])) if int(row["lawyer_id"] or 0) > 0 else None
        entries = db.execute("SELECT entry_type,content,created_at FROM court_entries WHERE case_id=? ORDER BY id DESC LIMIT 10", (row["id"],)).fetchall()
        items.append({
            "id": int(row["id"]), "title": row["title"], "status": row["status"],
            "verdict": row["verdict"] or "", "decision": row["decision_text"] or "",
            "client": player_display_name(client, "Клиент"),
            "lawyer": player_display_name(lawyer, "Обвинение") if lawyer else "Обвинение / СК",
            "is_party": uid in (int(row["client_id"]), int(row["lawyer_id"] or 0)),
            "can_start": _is_judge(player) and row["status"] == "Открыто",
            "can_verdict": _is_judge(player) and row["status"] == "Слушание" and int(row["judge_id"] or 0) == uid,
            "entries": [{"type": e["entry_type"], "content": e["content"], "created_at": e["created_at"]} for e in reversed(entries)]
        })
    return web.json_response({"items": items, "can_open_case": _is_lawyer(player), "can_judge": _is_judge(player)})


async def miniapp_court_open(request):
    uid = request["telegram_user_id"]
    player = get_player(uid)
    if not _is_lawyer(player):
        return web.json_response({"error": "Открыть дело может только действующий адвокат."}, status=403)
    try:
        payload = await request.json()
        client_game_id = int(payload.get("client_game_id", 0))
    except Exception:
        return web.json_response({"error": "Укажи игровой ID клиента."}, status=400)
    title = str(payload.get("title", "")).strip()
    if client_game_id <= 0 or not 5 <= len(title) <= 120:
        return web.json_response({"error": "Проверь игровой ID и название дела (5–120 символов)."}, status=400)
    client = get_player_by_game_id(client_game_id)
    if not client or int(client["user_id"]) == uid:
        return web.json_response({"error": "Клиент не найден или не может быть самим адвокатом."}, status=404)
    try:
        begin_immediate()
        fresh_lawyer = get_player(uid)
        if not _is_lawyer(fresh_lawyer):
            db.rollback(); return web.json_response({"error": "Полномочия адвоката изменились."}, status=403)
        active = db.execute("SELECT id FROM court_cases WHERE client_id=? AND status IN ('Открыто','Слушание','На рассмотрении') ORDER BY id DESC LIMIT 1", (int(client["user_id"]),)).fetchone()
        if active:
            db.rollback(); return web.json_response({"error": f"У клиента уже есть незавершённое дело №{active['id']}."}, status=409)
        cur = db.execute("INSERT INTO court_cases(client_id,lawyer_id,title,created_at) VALUES(?,?,?,?)", (int(client["user_id"]), uid, title, now_text()))
        case_id = int(cur.lastrowid)
        db.commit()
        if bot is not None:
            try: await bot.send_message(int(client["user_id"]), f"⚖️ Адвокат открыл судебное дело №{case_id}: {title}.")
            except Exception: log.debug("Не удалось уведомить клиента об открытии дела", exc_info=True)
        return web.json_response({"ok": True, "case_id": case_id})
    except TransactionConflict:
        return web.json_response({"error": "Судебный реестр занят. Повтори позже."}, status=409)
    except sqlite3.Error:
        if db.in_transaction: db.rollback()
        log.exception("Mini App: не удалось открыть судебное дело")
        return web.json_response({"error": "Не удалось открыть дело."}, status=500)


async def miniapp_court_defense(request):
    uid = request["telegram_user_id"]
    try:
        payload = await request.json()
        case_id = int(payload.get("case_id", 0))
    except Exception:
        return web.json_response({"error": "Некорректное дело."}, status=400)
    content = str(payload.get("content", "")).strip()
    if case_id <= 0 or not 20 <= len(content) <= 2000:
        return web.json_response({"error": "Позиция должна содержать 20–2000 символов."}, status=400)
    case = db.execute("SELECT * FROM court_cases WHERE id=? AND status='Слушание'", (case_id,)).fetchone()
    if not case or uid not in (int(case["client_id"]), int(case["lawyer_id"] or 0)):
        return web.json_response({"error": "Ты не являешься стороной этого дела или слушание не начато."}, status=403)
    try:
        begin_immediate()
        fresh_case = db.execute("SELECT * FROM court_cases WHERE id=? AND status='Слушание'", (case_id,)).fetchone()
        if not fresh_case or uid not in (int(fresh_case["client_id"]), int(fresh_case["lawyer_id"] or 0)):
            db.rollback(); return web.json_response({"error": "Доступ к делу изменился."}, status=403)
        db.execute("INSERT INTO court_entries(case_id,author_id,entry_type,content,created_at) VALUES(?,?, 'Позиция защиты', ?, ?)", (case_id, uid, content, now_text()))
        db.commit()
        return web.json_response({"ok": True})
    except TransactionConflict:
        return web.json_response({"error": "Судебный реестр занят. Повтори позже."}, status=409)
    except sqlite3.Error:
        if db.in_transaction: db.rollback()
        log.exception("Mini App: не удалось добавить позицию в дело %s", case_id)
        return web.json_response({"error": "Не удалось сохранить позицию."}, status=500)


async def miniapp_justice(request):
    uid = request["telegram_user_id"]
    jail = db.execute("SELECT id,reason,created_at,expires_at FROM player_punishments WHERE user_id=? AND punishment_type='JAIL' AND active=1 ORDER BY id DESC LIMIT 1", (uid,)).fetchone()
    parole = db.execute("SELECT id,reason,status,created_at,decision_note FROM parole_applications WHERE user_id=? ORDER BY id DESC LIMIT 10", (uid,)).fetchall()
    viewer=get_player(uid)
    lawyer_candidate=_is_lawyer(viewer)
    interrogations = db.execute(
        "SELECT s.id,s.target_id,s.officer_id,s.faction,s.reason,s.status,s.created_at FROM interrogation_sessions s "
        "WHERE s.target_id=? OR s.officer_id=? OR EXISTS(SELECT 1 FROM interrogation_lawyers l WHERE l.session_id=s.id AND l.lawyer_id=?) "
        "OR (?=1 AND s.status='Открыт' AND EXISTS(SELECT 1 FROM interrogation_entries e WHERE e.session_id=s.id AND e.author_id=s.target_id AND lower(e.content) LIKE '%прошу адвоката%')) "
        "ORDER BY s.id DESC LIMIT 20",
        (uid, uid, uid, int(lawyer_candidate))
    ).fetchall()
    interrogation_items = []
    for row in interrogations:
        entries = db.execute("SELECT author_role,entry_type,content,created_at FROM interrogation_entries WHERE session_id=? ORDER BY id DESC LIMIT 8", (row["id"],)).fetchall()
        interrogation_items.append({
            "id": int(row["id"]), "faction": row["faction"], "reason": row["reason"],
            "status": row["status"], "created_at": row["created_at"],
            "role": "Сотрудник" if int(row["officer_id"]) == uid else ("Задержанный" if int(row["target_id"]) == uid else ("Адвокат" if db.execute("SELECT 1 FROM interrogation_lawyers WHERE session_id=? AND lawyer_id=?",(row["id"],uid)).fetchone() else "Адвокат может подключиться")),
            "can_write": row["status"] == "Открыт" and (int(row["officer_id"]) == uid or int(row["target_id"]) == uid or bool(db.execute("SELECT 1 FROM interrogation_lawyers WHERE session_id=? AND lawyer_id=?",(row["id"],uid)).fetchone())),
            "can_request_lawyer": int(row["target_id"]) == uid and row["status"] == "Открыт" and not db.execute("SELECT 1 FROM interrogation_entries WHERE session_id=? AND author_id=? AND lower(content) LIKE '%прошу адвоката%'",(row["id"],uid)).fetchone(),
            "can_join": lawyer_candidate and int(row["target_id"]) != uid and row["status"] == "Открыт" and bool(db.execute("SELECT 1 FROM interrogation_entries WHERE session_id=? AND author_id=? AND lower(content) LIKE '%прошу адвоката%'",(row["id"],row["target_id"])).fetchone()) and not db.execute("SELECT 1 FROM interrogation_lawyers WHERE session_id=? AND lawyer_id=?",(row["id"],uid)).fetchone(),
            "can_close": int(row["officer_id"]) == uid and row["status"] == "Открыт",
            "entries": [{"role": e["author_role"], "type": e["entry_type"], "content": e["content"], "created_at": e["created_at"]} for e in reversed(entries)]
        })
    jail_payload = None
    if jail:
        jail_payload = {"id": int(jail["id"]), "reason": jail["reason"], "created_at": jail["created_at"], "expires_at": jail["expires_at"]}
    pending_parole=[]
    if _is_judge(viewer) or is_admin(uid):
        pending_rows=db.execute("SELECT id,user_id,reason,status,created_at FROM parole_applications WHERE status='На рассмотрении' ORDER BY id DESC LIMIT 30").fetchall()
        pending_parole=[{"id":int(r["id"]),"user":player_display_name(get_player(r["user_id"])),"reason":r["reason"],"status":r["status"],"created_at":r["created_at"]} for r in pending_rows]
    return web.json_response({
        "jailed": bool(jail_payload), "jail": jail_payload,
        "parole": [{"id": int(r["id"]), "reason": r["reason"], "status": r["status"], "created_at": r["created_at"], "decision_note": r["decision_note"]} for r in parole],
        "pending_parole": pending_parole,
        "can_review_parole": _is_judge(viewer) or is_admin(uid),
        "can_start_interrogation": _is_police_or_fbi(viewer) or _is_sk_staff(viewer),
        "interrogations": interrogation_items
    })


async def miniapp_parole(request):
    uid = request["telegram_user_id"]
    try:
        payload = await request.json()
    except Exception:
        return web.json_response({"error": "Некорректный JSON."}, status=400)
    reason = str(payload.get("reason", "")).strip() if isinstance(payload, dict) else ""
    if not 20 <= len(reason) <= 500:
        return web.json_response({"error": "Причина должна содержать 20–500 символов."}, status=400)
    punishment = db.execute("SELECT id,created_at,expires_at FROM player_punishments WHERE user_id=? AND punishment_type='JAIL' AND active=1 ORDER BY id DESC LIMIT 1", (uid,)).fetchone()
    if not punishment:
        return web.json_response({"error": "Активное игровое заключение не найдено."}, status=409)
    try:
        started = datetime.fromisoformat(punishment["created_at"])
        expires = datetime.fromisoformat(punishment["expires_at"])
        total_seconds = (expires-started).total_seconds()
        elapsed_seconds = (datetime.now()-started).total_seconds()
    except (TypeError, ValueError):
        return web.json_response({"error": "Не удалось проверить срок заключения."}, status=409)
    if total_seconds <= 0 or elapsed_seconds < total_seconds * 0.5:
        remaining = max(0, int(total_seconds * 0.5 - elapsed_seconds))
        return web.json_response({"error": f"Подать на УДО можно после половины срока. Осталось примерно {max(1, remaining//60)} мин."}, status=409)
    try:
        begin_immediate()
        fresh_punishment = db.execute("SELECT id,created_at,expires_at FROM player_punishments WHERE id=? AND user_id=? AND punishment_type='JAIL' AND active=1", (punishment["id"], uid)).fetchone()
        if not fresh_punishment:
            db.rollback(); return web.json_response({"error": "Срок заключения уже завершён."}, status=409)
        fresh_started=datetime.fromisoformat(fresh_punishment["created_at"])
        fresh_expires=datetime.fromisoformat(fresh_punishment["expires_at"])
        fresh_total=(fresh_expires-fresh_started).total_seconds()
        fresh_elapsed=(datetime.now()-fresh_started).total_seconds()
        if fresh_total<=0 or fresh_elapsed<fresh_total*0.5:
            db.rollback(); return web.json_response({"error":"Подать на УДО можно только после отбытия половины срока."},status=409)
        pending = db.execute("SELECT id FROM parole_applications WHERE punishment_id=? AND status='На рассмотрении'", (punishment["id"],)).fetchone()
        if pending:
            db.rollback(); return web.json_response({"error": f"Заявление №{pending['id']} уже ожидает решения."}, status=409)
        cur = db.execute("INSERT INTO parole_applications(punishment_id,user_id,reason,status,created_at) VALUES(?,?,?,'На рассмотрении',?)", (punishment["id"], uid, reason, now_text()))
        application_id = int(cur.lastrowid)
        db.commit()
        judges = db.execute("SELECT user_id FROM players WHERE faction='Мэрия' AND rank IN ('Судья','Аттестованный судья','Апелляционный судья')").fetchall()
        judge_ids = [int(r["user_id"]) for r in judges] or [int(x) for x in ADMIN_IDS if int(x) != uid]
        if bot is not None:
            keyboard = InlineKeyboardMarkup(inline_keyboard=[[InlineKeyboardButton(text="Открыть заявление", callback_data=f"parole:view:{application_id}")]])
            for judge_id in judge_ids:
                try: await bot.send_message(judge_id, f"⚖️ Новое заявление на УДО №{application_id} от {player_display_name(get_player(uid))}.", reply_markup=keyboard)
                except Exception: log.debug("Не удалось уведомить судью об УДО", exc_info=True)
        return web.json_response({"ok": True, "application_id": application_id})
    except TransactionConflict:
        return web.json_response({"error": "Реестр УДО занят. Повтори позже."}, status=409)
    except sqlite3.Error:
        if db.in_transaction: db.rollback()
        log.exception("Mini App: не удалось подать заявление на УДО пользователя %s", uid)
        return web.json_response({"error": "Не удалось сохранить заявление на УДО."}, status=500)


async def miniapp_notifications(request):
    uid = request["telegram_user_id"]
    rows = db.execute("SELECT id,sender_id,message,created_at,is_read FROM phone_messages WHERE receiver_id=? ORDER BY id DESC LIMIT 40", (uid,)).fetchall()
    items=[]
    for row in rows:
        sender=get_player(int(row["sender_id"]))
        items.append({"id": int(row["id"]), "sender": player_display_name(sender, "Система"), "message": row["message"], "created_at": row["created_at"], "read": bool(row["is_read"])})
    return web.json_response({"items": items, "unread": sum(1 for x in items if not x["read"])})


async def miniapp_notifications_read(request):
    uid=request["telegram_user_id"]
    try:
        payload=await request.json()
    except Exception:
        payload={}
    try:
        message_id=int(payload.get("message_id",0) or 0) if isinstance(payload,dict) else 0
    except (TypeError,ValueError):
        return web.json_response({"error":"Некорректное уведомление."},status=400)
    if message_id:
        changed=db.execute("UPDATE phone_messages SET is_read=1 WHERE id=? AND receiver_id=?",(message_id,uid))
    else:
        changed=db.execute("UPDATE phone_messages SET is_read=1 WHERE receiver_id=? AND is_read=0",(uid,))
    db.commit()
    return web.json_response({"ok":True,"updated":int(changed.rowcount)})


async def miniapp_npc_document(request):
    uid=request["telegram_user_id"]
    try:
        payload=await request.json()
        npc_id=int(payload.get("npc_id",0))
    except Exception:
        return web.json_response({"error":"Некорректный запрос документа."},status=400)
    kind=str(payload.get("kind","")).strip().lower()
    if kind not in ("passport","serviceid") or npc_id<=0:
        return web.json_response({"error":"Неизвестный документ или NPC."},status=400)
    player=get_player(uid)
    if not player:
        return web.json_response({"error":"Сначала создай персонажа."},status=404)
    if active_player_travel(uid):
        return web.json_response({"error":"Во время поездки документы предъявить нельзя."},status=409)
    npc=next((row for row in _nearby_npcs(player["location"]) if int(row["id"])==npc_id),None)
    if not npc:
        return web.json_response({"error":"Этот NPC сейчас не находится рядом."},status=404)
    if kind=="passport":
        if not player["passport"]:
            return web.json_response({"error":"У тебя ещё нет оформленного паспорта."},status=409)
        document={"name":player_display_name(player),"gender":player["gender"] or "Не указан","age":player["age"],"rank":player["rank"] if player["rank"] != "Нет" else "Гражданский","faction":player["faction"] if player["faction"] != "Нет" else "Гражданский","citizenship":"RPM WEST","valid":True}
        column="passport_json"
        event=(f"{player_display_name(player)} предъявляет тебе действительный паспорт. Данные: имя — {document['name']}; пол — {document['gender']}; возраст — {document['age']}; должность — {document['rank']}; фракция — {document['faction']}; гражданство — {document['citizenship']}.")
    else:
        university_staff=university_employee(uid)
        if player["faction"] in CRIME_FACTIONS or (player["faction"] not in FACTIONS and not university_staff) or player["rank"]=="Нет":
            return web.json_response({"error":"Служебные удостоверения не выдаются криминальным фракциям."},status=403)
        document={"name":player_display_name(player),"faction":player["faction"] if player["faction"] in FACTIONS else "Университет","rank":player["rank"],"department":_department_for(uid),"valid":True}
        column="serviceid_json"
        event=(f"{player_display_name(player)} предъявляет тебе действующее служебное удостоверение. Проверенные сведения: имя — {document['name']}; организация — {document['faction']}; должность — {document['rank']}; отдел — {document['department']}.")
    db.execute("INSERT INTO npc_ai_active_chat(user_id,npc_id,started_at) VALUES(?,?,?) ON CONFLICT(user_id) DO UPDATE SET npc_id=excluded.npc_id,started_at=excluded.started_at",(uid,npc_id,now_text()))
    db.execute(
        f"INSERT INTO npc_ai_documents(user_id,npc_id,{column},updated_at) VALUES(?,?,?,?) "
        f"ON CONFLICT(user_id,npc_id) DO UPDATE SET {column}=excluded.{column},updated_at=excluded.updated_at",
        (uid,npc_id,json.dumps(document,ensure_ascii=False),now_text())
    )
    db.commit()
    reply=await _npc_ai_generate(npc,player,event,channel="предъявление документа через Mini App",memory_user_id=uid)
    return web.json_response({"ok":True,"npc":npc["name"],"reply":reply or "Документ принят."})



async def miniapp_faction_members(request):
    uid=request["telegram_user_id"]
    player=get_player(uid)
    if not player:
        return web.json_response({"faction":"Нет","items":[]})
    faction=player["faction"]
    if faction in FACTIONS:
        ranks=FACTIONS[faction]["ranks"]
    elif faction=="Университет" and university_employee(uid):
        ranks=UNIVERSITY_RANKS
    else:
        return web.json_response({"faction":"Нет","items":[]})
    admin=is_admin(uid)
    can_manage=admin or _faction_work_leader(player)
    rows=db.execute("SELECT user_id,game_id,name,rank,gender FROM players WHERE faction=?",(faction,)).fetchall()
    items=[]
    for row in rows:
        target=get_player(row["user_id"])
        idx=_rank_index(faction,row["rank"])
        items.append({
            "game_id":int(row["game_id"] or 0),"name":player_display_name(target),"rank":row["rank"],
            "is_me":int(row["user_id"])==uid,
            "can_promote":can_manage and int(row["user_id"])!=uid and idx>=0 and idx+1<len(ranks) and _can_set_rank(player,admin,target,idx+1) and (not _exam_required(faction,ranks[idx+1]) or _exam_passed(row["user_id"],faction,ranks[idx+1])),
            "can_demote":can_manage and int(row["user_id"])!=uid and idx>0 and _can_set_rank(player,admin,target,idx-1)
        })
    rank_order={rank:index for index,rank in enumerate(ranks)}
    items.sort(key=lambda item:(rank_order.get(item["rank"],-1),item["name"].casefold()),reverse=True)
    return web.json_response({"faction":faction,"items":items,"can_manage":can_manage})



async def miniapp_faction_applications(request):
    uid=request["telegram_user_id"]
    actor=get_player(uid)
    if not actor or actor["faction"] not in FACTIONS or actor["rank"] not in FACTIONS[actor["faction"]]["ranks"][-2:]:
        return web.json_response({"items":[],"can_manage":False})
    faction=actor["faction"]
    rows=db.execute(
        "SELECT a.id,a.user_id,a.status,a.created_at,a.entry_fee,p.name,p.game_id "
        "FROM faction_applications a JOIN players p ON p.user_id=a.user_id "
        "WHERE a.faction=? AND a.status NOT IN ('Принят','Отказано','Отозвана игроком','Отменена: принят в другую организацию') "
        "ORDER BY a.id DESC LIMIT 30",(faction,)
    ).fetchall()
    items=[]
    for row in rows:
        session=db.execute("SELECT id,status,score FROM faction_interview_sessions WHERE candidate_id=? AND faction=? ORDER BY id DESC LIMIT 1",(row["user_id"],faction)).fetchone()
        items.append({
            "id":int(row["id"]),"game_id":int(row["game_id"] or 0),
            "name":player_display_name(get_player(row["user_id"])),"status":row["status"],
            "created_at":row["created_at"],"entry_fee":int(row["entry_fee"] or FACTIONS[faction].get("price",0)),
            "interview_score":int(session["score"] or 0) if session else None,
            "interview_status":session["status"] if session else "Не назначено",
            "can_decide":bool(session and session["status"]=="Ожидает решения" and row["status"]=="Собеседование завершено")
        })
    return web.json_response({"faction":faction,"can_manage":True,"items":items})


async def miniapp_faction_application_decision(request):
    uid=request["telegram_user_id"]
    try: payload=await request.json(); app_id=int(payload.get("application_id",0))
    except Exception: return web.json_response({"error":"Некорректная заявка."},status=400)
    decision=str(payload.get("decision","")).strip().lower()
    if app_id<=0 or decision not in ("accept","reject"):
        return web.json_response({"error":"Укажи заявку и решение."},status=400)
    actor=get_player(uid)
    if not actor or actor["faction"] not in FACTIONS or actor["rank"] not in FACTIONS[actor["faction"]]["ranks"][-2:]:
        return web.json_response({"error":"Решать заявки могут только действующие руководители соответствующей организации."},status=403)
    faction=actor["faction"]
    app=db.execute("SELECT * FROM faction_applications WHERE id=? AND faction=?",(app_id,faction)).fetchone()
    if not app or app["status"]!="Собеседование завершено":
        return web.json_response({"error":"Заявка не найдена или собеседование ещё не завершено."},status=409)
    target=int(app["user_id"])
    if target==uid:
        return web.json_response({"error":"Нельзя принимать решение по собственной заявке."},status=403)
    session=db.execute("SELECT * FROM faction_interview_sessions WHERE candidate_id=? AND faction=? AND status='Ожидает решения' ORDER BY id DESC LIMIT 1",(target,faction)).fetchone()
    if not session:
        return web.json_response({"error":"Сессия собеседования не найдена или уже закрыта."},status=409)
    info=FACTIONS[faction]
    candidate=get_player(target)
    if not candidate:
        return web.json_response({"error":"Кандидат не найден."},status=404)
    entry_fee=int(app["entry_fee"] or info.get("price",0))
    if decision=="accept":
        blocked=db.execute("SELECT 1 FROM faction_blacklist WHERE user_id=? AND faction=? AND active=1",(target,faction)).fetchone()
        rule=db.execute("SELECT * FROM faction_hiring_rules WHERE faction=?",(faction,)).fetchone()
        if blocked: return web.json_response({"error":"Кандидат находится в чёрном списке этой организации."},status=409)
        if candidate["banned"]: return web.json_response({"error":"Заблокированный кандидат не может быть принят."},status=409)
        if candidate["faction"]==faction: return web.json_response({"error":"Кандидат уже состоит в этой организации."},status=409)
        if candidate["faction"] not in FACTIONS and candidate["faction"] not in ("Нет","Университет"):
            return web.json_response({"error":"У кандидата некорректная текущая организация."},status=409)
        if candidate["faction"] in FACTIONS and (not rule or not rule["allow_transfers"]):
            return web.json_response({"error":"Переводы в эту организацию запрещены."},status=409)
        if candidate["faction"] in ("Нет","Университет") and rule and not rule["allow_citizens"]:
            return web.json_response({"error":"Приём гражданских запрещён условиями набора."},status=409)
        exp_count,exp_days=_employment_experience(target)
        if rule and (exp_count<rule["min_previous_factions"] or exp_days<rule["min_previous_days"]):
            return web.json_response({"error":"Кандидат не соответствует требованиям по трудовому стажу."},status=409)
        missing=faction_missing_entry_requirements(target,candidate,rule)
        if missing: return web.json_response({"error":"Кандидат не выполнил требования: "+", ".join(missing)+"."},status=409)
        if not education_meets_requirement(candidate["education"],info["education"]):
            return web.json_response({"error":"У кандидата недостаточно образования."},status=409)
        if int(candidate["balance"] or 0)<entry_fee:
            return web.json_response({"error":f"У кандидата недостаточно средств для оплаты ${entry_fee:,}."},status=409)
    try:
        begin_immediate()
        fresh_actor=get_player(uid)
        if not fresh_actor or fresh_actor["faction"]!=faction or fresh_actor["faction"] not in FACTIONS or fresh_actor["rank"] not in FACTIONS[faction]["ranks"][-2:]:
            db.rollback(); return web.json_response({"error":"Полномочия изменились. Решение доступно только руководству этой организации."},status=403)
        fresh_app=db.execute("SELECT * FROM faction_applications WHERE id=? AND faction=? AND user_id=? AND status='Собеседование завершено'",(app_id,faction,target)).fetchone()
        fresh_session=db.execute("SELECT * FROM faction_interview_sessions WHERE id=? AND candidate_id=? AND faction=? AND status='Ожидает решения'",(session["id"],target,faction)).fetchone()
        fresh_candidate=get_player(target)
        if not fresh_app or not fresh_session or not fresh_candidate:
            db.rollback(); return web.json_response({"error":"Заявка или собеседование уже изменились."},status=409)
        if decision=="accept":
            fresh_rule=db.execute("SELECT * FROM faction_hiring_rules WHERE faction=?",(faction,)).fetchone()
            if fresh_candidate["banned"] or fresh_candidate["faction"]==faction:
                db.rollback(); return web.json_response({"error":"Кандидат больше не соответствует условиям приёма."},status=409)
            if fresh_candidate["faction"] not in FACTIONS and fresh_candidate["faction"] not in ("Нет","Университет"):
                db.rollback(); return web.json_response({"error":"У кандидата некорректная текущая организация."},status=409)
            if db.execute("SELECT 1 FROM faction_blacklist WHERE user_id=? AND faction=? AND active=1",(target,faction)).fetchone():
                db.rollback(); return web.json_response({"error":"Кандидат находится в чёрном списке."},status=409)
            if fresh_candidate["faction"] in FACTIONS and (not fresh_rule or not fresh_rule["allow_transfers"]):
                db.rollback(); return web.json_response({"error":"Переводы в эту организацию запрещены."},status=409)
            if fresh_candidate["faction"] in ("Нет","Университет") and fresh_rule and not fresh_rule["allow_citizens"]:
                db.rollback(); return web.json_response({"error":"Приём гражданских запрещён."},status=409)
            exp_count,exp_days=_employment_experience(target)
            if fresh_rule and (exp_count<fresh_rule["min_previous_factions"] or exp_days<fresh_rule["min_previous_days"]):
                db.rollback(); return web.json_response({"error":"Кандидат больше не соответствует требованиям по стажу."},status=409)
            missing=faction_missing_entry_requirements(target,fresh_candidate,fresh_rule)
            if missing or not education_meets_requirement(fresh_candidate["education"],info["education"]):
                db.rollback(); return web.json_response({"error":"Кандидат больше не соответствует требованиям организации."},status=409)
            fee=int(fresh_app["entry_fee"] or info.get("price",0))
            if int(fresh_candidate["balance"] or 0)<fee:
                db.rollback(); return web.json_response({"error":f"Недостаточно средств для оплаты ${fee:,}."},status=409)
            old_faction=fresh_candidate["faction"]
            rank=info["ranks"][0]
            if old_faction!="Нет": _close_faction_membership(target,old_faction,f"Перевод в {faction}",uid,now_text())
            if "university_students" in _existing_tables():
                db.execute("UPDATE university_students SET active=0 WHERE user_id=? AND active=1",(target,))
            changed=db.execute("UPDATE players SET balance=balance-?,faction=?,rank=?,labor_book=1 WHERE user_id=? AND faction=? AND balance>=? AND banned=0",(fee,faction,rank,target,old_faction,fee))
            if changed.rowcount!=1: raise sqlite3.IntegrityError("faction_application_accept_failed")
            if fee>0: db.execute("INSERT INTO bank_transactions(user_id,other_user_id,amount,transaction_type,description,created_at) VALUES(?,0,?,'faction_fee',?,?)",(target,fee,f"Вступление в «{faction}»",now_text()))
            db.execute("INSERT INTO faction_membership(user_id,faction,rank,joined_at) VALUES(?,?,?,?)",(target,faction,rank,now_text()))
            db.execute("INSERT INTO employment_history(user_id,faction,rank,action,started_at,actor_id,created_at) VALUES(?,?,?,?,?,?,?)",(target,faction,rank,"Перевод" if old_faction in FACTIONS else "Приём",now_text(),uid,now_text()))
            session_changed=db.execute("UPDATE faction_interview_sessions SET status='Принят' WHERE id=? AND status='Ожидает решения'",(session["id"],))
            app_changed=db.execute("UPDATE faction_applications SET status='Принят' WHERE id=? AND faction=? AND user_id=? AND status='Собеседование завершено'",(app_id,faction,target))
            if session_changed.rowcount!=1 or app_changed.rowcount!=1: raise sqlite3.IntegrityError("application_already_decided")
            _cancel_other_applications(target,faction,now_text())
            status="Принят"; note=f"Кандидат принят в «{faction}» на должность «{rank}»."
        else:
            session_changed=db.execute("UPDATE faction_interview_sessions SET status='Отказано' WHERE id=? AND status='Ожидает решения'",(session["id"],))
            app_changed=db.execute("UPDATE faction_applications SET status='Отказано' WHERE id=? AND faction=? AND user_id=? AND status='Собеседование завершено'",(app_id,faction,target))
            if session_changed.rowcount!=1 or app_changed.rowcount!=1: raise sqlite3.IntegrityError("application_already_decided")
            status="Отказано"; note=f"Заявка в «{faction}» отклонена руководством."
        db.commit()
        if bot is not None:
            try: await bot.send_message(target,note,reply_markup=main_keyboard(get_player(target)) if decision=="accept" else None)
            except Exception: log.debug("Не удалось уведомить кандидата о решении по заявке",exc_info=True)
        return web.json_response({"ok":True,"status":status,"message":note})
    except TransactionConflict:
        return web.json_response({"error":"Кадровый реестр занят. Повтори позже."},status=409)
    except sqlite3.Error:
        if db.in_transaction: db.rollback()
        log.exception("Mini App: ошибка решения по заявке %s",app_id)
        return web.json_response({"error":"Не удалось сохранить решение по заявке."},status=500)

async def miniapp_faction_rank(request):
    uid=request["telegram_user_id"]
    try: payload=await request.json(); game_id=int(payload.get("game_id",0))
    except Exception: return web.json_response({"error":"Укажи игровой ID сотрудника."},status=400)
    action=str(payload.get("action","")).strip().lower()
    reason=str(payload.get("reason","Изменение должности через Mini App")).strip()[:200]
    if game_id<=0 or action not in ("promote","demote"):
        return web.json_response({"error":"Некорректное кадровое действие."},status=400)
    actor=get_player(uid); target=get_player_by_game_id(game_id)
    if not target or not actor:
        return web.json_response({"error":"Персонаж не найден."},status=404)
    if int(target["user_id"])==uid:
        return web.json_response({"error":"Нельзя менять должность самому себе."},status=409)
    if target["faction"] not in FACTIONS and not university_employee(target["user_id"]):
        return web.json_response({"error":"Персонаж не состоит в организации."},status=409)
    faction=target["faction"]
    ranks=UNIVERSITY_RANKS if faction=="Университет" else FACTIONS[faction]["ranks"]
    idx=_rank_index(faction,target["rank"])
    new_idx=idx+(1 if action=="promote" else -1)
    if idx<0 or new_idx<0 or new_idx>=len(ranks):
        return web.json_response({"error":"Для этой должности нет следующего уровня."},status=409)
    if not _can_set_rank(actor,is_admin(uid),target,new_idx):
        return web.json_response({"error":"Менять должности можно только в пределах своих полномочий."},status=403)
    new_rank=ranks[new_idx]
    if action=="promote" and _exam_required(faction,new_rank) and not _exam_passed(target["user_id"],faction,new_rank):
        return web.json_response({"error":f"Сотрудник должен сдать экзамен на должность «{new_rank}»."},status=409)
    old_rank=target["rank"]
    if not _apply_rank_change(int(target["user_id"]),faction,old_rank,new_rank,uid,reason,authority_user_id=uid):
        return web.json_response({"error":"Изменение не выполнено: полномочия или требования изменились."},status=409)
    if action=="promote":
        db.execute("UPDATE promotion_requests SET status='Принят',decided_by=?,decided_at=? WHERE user_id=? AND faction=? AND from_rank=? AND to_rank=? AND status='Ожидает'",(uid,now_text(),target["user_id"],faction,old_rank,new_rank))
        db.commit()
    if is_admin(uid): audit_admin_action(uid,int(target["user_id"]),action.upper(),f"{faction}|{old_rank}->{new_rank}")
    if bot is not None:
        try: await bot.send_message(int(target["user_id"]),f"{'🎉 Тебя повысили' if action=='promote' else '⚠️ Тебя понизили'} в «{faction}»: {old_rank} → {new_rank}. Причина: {reason}")
        except Exception: log.debug("Не удалось уведомить сотрудника об изменении должности",exc_info=True)
    return web.json_response({"ok":True,"game_id":game_id,"old_rank":old_rank,"new_rank":new_rank})


async def miniapp_npc_history(request):
    uid=request["telegram_user_id"]
    try: npc_id=int(request.query.get("npc_id",0))
    except (TypeError,ValueError): return web.json_response({"error":"Некорректный NPC."},status=400)
    if npc_id<=0: return web.json_response({"error":"NPC не найден."},status=404)
    exists=db.execute("SELECT id,name,faction,rank FROM faction_npcs WHERE id=? AND active=1",(npc_id,)).fetchone()
    if not exists: return web.json_response({"error":"NPC не найден."},status=404)
    rows=db.execute("SELECT role,content,created_at FROM npc_ai_dialogue WHERE user_id=? AND npc_id=? ORDER BY id DESC LIMIT 40",(uid,npc_id)).fetchall()
    return web.json_response({"npc":exists["name"],"items":[{"role":r["role"],"content":r["content"],"created_at":r["created_at"]} for r in reversed(rows)]})


async def miniapp_court_start(request):
    uid=request["telegram_user_id"]
    if not _is_judge(get_player(uid)):
        return web.json_response({"error":"Открыть судебное заседание может только судья."},status=403)
    try: payload=await request.json(); case_id=int(payload.get("case_id",0))
    except Exception: return web.json_response({"error":"Некорректное дело."},status=400)
    if case_id<=0: return web.json_response({"error":"Некорректный номер дела."},status=400)
    try:
        begin_immediate()
        judge=get_player(uid)
        if not _is_judge(judge): db.rollback(); return web.json_response({"error":"Полномочия судьи изменились."},status=403)
        case=db.execute("SELECT * FROM court_cases WHERE id=? AND status='Открыто'",(case_id,)).fetchone()
        if not case: db.rollback(); return web.json_response({"error":"Открытое дело не найдено."},status=404)
        changed=db.execute("UPDATE court_cases SET status='Слушание',judge_id=? WHERE id=? AND status='Открыто'",(uid,case_id))
        if changed.rowcount!=1: raise sqlite3.IntegrityError("court_case_already_started")
        db.execute("INSERT INTO court_entries(case_id,author_id,entry_type,content,created_at) VALUES(?,?,'Судебное заседание','Судья открыл судебное заседание.',?)",(case_id,uid,now_text()))
        db.commit()
        if bot is not None:
            for target in (int(case["client_id"]),int(case["lawyer_id"] or 0)):
                if target>0:
                    try: await bot.send_message(target,f"⚖️ Судебное заседание по делу №{case_id} начато.")
                    except Exception: log.debug("Не удалось уведомить сторону о начале суда",exc_info=True)
        return web.json_response({"ok":True})
    except TransactionConflict: return web.json_response({"error":"Судебный реестр занят."},status=409)
    except sqlite3.Error:
        if db.in_transaction: db.rollback()
        log.exception("Mini App: не удалось начать судебное заседание №%s",case_id)
        return web.json_response({"error":"Не удалось начать заседание."},status=500)


async def miniapp_court_verdict(request):
    uid=request["telegram_user_id"]
    if not _is_judge(get_player(uid)):
        return web.json_response({"error":"Решение по делу может вынести только судья."},status=403)
    try: payload=await request.json(); case_id=int(payload.get("case_id",0))
    except Exception: return web.json_response({"error":"Некорректное дело."},status=400)
    verdict=str(payload.get("verdict","")).strip().casefold()
    reason=str(payload.get("reason","")).strip()
    if case_id<=0 or verdict not in ("оправдать","виновен") or not 10<=len(reason)<=2000:
        return web.json_response({"error":"Укажи дело, итог «оправдать» или «виновен» и обоснование от 10 до 2000 символов."},status=400)
    try:
        begin_immediate()
        if not _is_judge(get_player(uid)):
            db.rollback(); return web.json_response({"error":"Полномочия судьи изменились."},status=403)
        case=db.execute("SELECT * FROM court_cases WHERE id=? AND status='Слушание' AND judge_id=?",(case_id,uid)).fetchone()
        if not case: db.rollback(); return web.json_response({"error":"Слушание не найдено или его ведёт другой судья."},status=404)
        status_note="Суд оправдал персонажа." if verdict=="оправдать" else "Суд признал персонажа виновным."
        db.execute("UPDATE court_cases SET status='Закрыто',verdict=?,decision_text=?,closed_at=? WHERE id=? AND status='Слушание' AND judge_id=?",(verdict,reason,now_text(),case_id,uid))
        db.execute("INSERT INTO court_entries(case_id,author_id,entry_type,content,created_at) VALUES(?,?,'Решение суда',?,?)",(case_id,uid,f"Решение: {verdict}. Обоснование: {reason}",now_text()))
        db.execute("UPDATE legal_charges SET status=? WHERE id IN (SELECT charge_id FROM court_case_charges WHERE case_id=?) AND status='Выдвинуто'",("Снято судом" if verdict=="оправдать" else "Подтверждено судом",case_id))
        jury=db.execute("SELECT SUM(CASE WHEN vote='guilty' THEN 1 ELSE 0 END) AS guilty,SUM(CASE WHEN vote='innocent' THEN 1 ELSE 0 END) AS innocent FROM court_jury_members WHERE case_id=?",(case_id,)).fetchone()
        if jury and ((jury["guilty"] or 0)+(jury["innocent"] or 0)):
            db.execute("INSERT INTO court_entries(case_id,author_id,entry_type,content,created_at) VALUES(?,?,'Мнение присяжных',?,?)",(case_id,uid,f"Совещательное голосование: виновен — {jury['guilty'] or 0}; не виновен — {jury['innocent'] or 0}. Окончательное решение принято судьёй.",now_text()))
        db.commit()
        if bot is not None:
            for target in (int(case["client_id"]),int(case["lawyer_id"] or 0)):
                if target>0:
                    try: await bot.send_message(target,f"⚖️ Суд вынес решение по делу №{case_id}: {verdict}. Обоснование: {reason}")
                    except Exception: log.debug("Не удалось уведомить сторону о решении суда",exc_info=True)
        return web.json_response({"ok":True,"status":"Закрыто","verdict":verdict,"note":status_note})
    except TransactionConflict: return web.json_response({"error":"Судебный реестр занят."},status=409)
    except sqlite3.Error:
        if db.in_transaction: db.rollback()
        log.exception("Mini App: не удалось вынести решение по делу №%s",case_id)
        return web.json_response({"error":"Не удалось сохранить решение суда."},status=500)


async def miniapp_parole_decision(request):
    uid=request["telegram_user_id"]
    if not _is_judge(get_player(uid)) and not is_admin(uid):
        return web.json_response({"error":"Рассматривать заявления на УДО могут судьи и администрация."},status=403)
    try: payload=await request.json(); app_id=int(payload.get("application_id",0))
    except Exception: return web.json_response({"error":"Некорректное заявление."},status=400)
    decision=str(payload.get("decision","")).strip().lower()
    if app_id<=0 or decision not in ("approve","reject"):
        return web.json_response({"error":"Некорректное решение."},status=400)
    try:
        begin_immediate()
        if not _is_judge(get_player(uid)) and not is_admin(uid):
            db.rollback(); return web.json_response({"error":"Полномочия изменились."},status=403)
        row=db.execute("SELECT * FROM parole_applications WHERE id=? AND status='На рассмотрении'",(app_id,)).fetchone()
        if not row: db.rollback(); return web.json_response({"error":"Заявление уже обработано."},status=404)
        punishment=db.execute("SELECT * FROM player_punishments WHERE id=? AND user_id=? AND punishment_type='JAIL' AND active=1",(row["punishment_id"],row["user_id"])).fetchone()
        if not punishment:
            status="Закрыто: срок завершён"; note="Срок заключения завершился до рассмотрения."
            db.execute("UPDATE parole_applications SET status=?,decided_by=?,decided_at=?,decision_note=? WHERE id=? AND status='На рассмотрении'",(status,uid,now_text(),note,app_id))
        elif decision=="approve":
            db.execute("UPDATE player_punishments SET active=0 WHERE id=? AND active=1",(punishment["id"],))
            status="Одобрено"; note="Суд одобрил условно-досрочное освобождение."
            db.execute("UPDATE parole_applications SET status=?,decided_by=?,decided_at=?,decision_note=? WHERE id=? AND status='На рассмотрении'",(status,uid,now_text(),note,app_id))
        else:
            status="Отклонено"; note="Суд отказал в условно-досрочном освобождении."
            db.execute("UPDATE parole_applications SET status=?,decided_by=?,decided_at=?,decision_note=? WHERE id=? AND status='На рассмотрении'",(status,uid,now_text(),note,app_id))
        db.commit()
        if bot is not None:
            try: await bot.send_message(int(row["user_id"]),f"⚖️ По заявлению на УДО №{app_id}: {note}")
            except Exception: log.debug("Не удалось уведомить заявителя об УДО",exc_info=True)
        return web.json_response({"ok":True,"status":status,"note":note})
    except TransactionConflict: return web.json_response({"error":"Реестр УДО занят."},status=409)
    except sqlite3.Error:
        if db.in_transaction: db.rollback()
        log.exception("Mini App: не удалось решить заявление на УДО №%s",app_id)
        return web.json_response({"error":"Не удалось сохранить решение."},status=500)


async def miniapp_interrogation_start(request):
    uid=request["telegram_user_id"]
    officer=get_player(uid)
    if not (_is_police_or_fbi(officer) or _is_sk_staff(officer)):
        return web.json_response({"error":"Открывать допросы могут сотрудники ЦПД, ФБР и Следственного комитета."},status=403)
    try:
        payload=await request.json(); game_id=int(payload.get("game_id",0))
    except Exception:
        return web.json_response({"error":"Укажи корректный игровой ID задержанного."},status=400)
    reason=str(payload.get("reason","")).strip()
    if game_id<=0 or not 5<=len(reason)<=500:
        return web.json_response({"error":"Укажи игровой ID и основание допроса (5–500 символов)."},status=400)
    target=get_player_by_game_id(game_id)
    if not target:
        return web.json_response({"error":"Персонаж с таким игровым ID не найден."},status=404)
    target_id=int(target["user_id"])
    if target_id==uid:
        return web.json_response({"error":"Нельзя открыть допрос собственного персонажа."},status=400)
    try:
        begin_immediate()
        cur=db.execute("INSERT INTO interrogation_sessions(target_id,officer_id,faction,reason,created_at) VALUES(?,?,?,?,?)",(target_id,uid,officer["faction"],reason,now_text()))
        session_id=int(cur.lastrowid)
        db.execute("INSERT INTO interrogation_entries(session_id,author_id,author_role,content,created_at) VALUES(?,?,'Сотрудник',?,?)",(session_id,uid,f"Начало допроса. Основание: {reason}",now_text()))
        db.commit()
    except TransactionConflict:
        return web.json_response({"error":"Реестр допросов занят. Повтори позже."},status=409)
    except sqlite3.Error:
        if db.in_transaction: db.rollback()
        log.exception("Mini App: не удалось открыть допрос")
        return web.json_response({"error":"Не удалось открыть протокол допроса."},status=500)
    if bot is not None:
        try:
            await bot.send_message(target_id,f"📋 Для твоего персонажа открыт RP-допрос №{session_id}. Организация: {officer['faction']}. Основание: {reason}. Открой раздел «Сервисы → ЦПД и КПЗ», чтобы запросить адвоката и вести протокол.")
        except Exception:
            log.debug("Не удалось уведомить участника о начале допроса",exc_info=True)
    return web.json_response({"ok":True,"session_id":session_id})


async def miniapp_interrogation_close(request):
    uid=request["telegram_user_id"]
    try: payload=await request.json(); session_id=int(payload.get("session_id",0))
    except Exception: return web.json_response({"error":"Некорректный протокол."},status=400)
    try:
        begin_immediate()
        session=db.execute("SELECT * FROM interrogation_sessions WHERE id=? AND status='Открыт'",(session_id,)).fetchone()
        if not session or int(session["officer_id"])!=uid:
            db.rollback(); return web.json_response({"error":"Закрыть протокол может только открывший его сотрудник."},status=403)
        db.execute("UPDATE interrogation_sessions SET status='Закрыт',closed_at=? WHERE id=? AND status='Открыт'",(now_text(),session_id))
        db.commit()
    except TransactionConflict: return web.json_response({"error":"Протокол занят."},status=409)
    except sqlite3.Error:
        if db.in_transaction: db.rollback()
        log.exception("Mini App: не удалось закрыть допрос №%s",session_id)
        return web.json_response({"error":"Не удалось закрыть протокол."},status=500)
    if bot is not None:
        try: await bot.send_message(int(session["target_id"]),f"📋 RP-допрос №{session_id} завершён. Протокол сохранён.")
        except Exception: log.debug("Не удалось уведомить участника о закрытии допроса",exc_info=True)
    return web.json_response({"ok":True})


async def miniapp_interrogation_entry(request):
    uid=request["telegram_user_id"]
    try: payload=await request.json(); session_id=int(payload.get("session_id",0))
    except Exception: return web.json_response({"error":"Некорректный протокол."},status=400)
    content=str(payload.get("content","")).strip()
    if session_id<=0 or not 5<=len(content)<=2000:
        return web.json_response({"error":"Запись должна содержать 5–2000 символов."},status=400)
    session=db.execute("SELECT * FROM interrogation_sessions WHERE id=? AND status='Открыт'",(session_id,)).fetchone()
    lawyer=db.execute("SELECT 1 FROM interrogation_lawyers WHERE session_id=? AND lawyer_id=?",(session_id,uid)).fetchone()
    if not session or (uid not in (int(session["target_id"]),int(session["officer_id"])) and not lawyer):
        return web.json_response({"error":"Ты не участник открытого протокола."},status=403)
    role="Сотрудник" if int(session["officer_id"])==uid else ("Допрашиваемый" if int(session["target_id"])==uid else "Адвокат")
    try:
        begin_immediate()
        fresh=db.execute("SELECT * FROM interrogation_sessions WHERE id=? AND status='Открыт'",(session_id,)).fetchone()
        lawyer=db.execute("SELECT 1 FROM interrogation_lawyers WHERE session_id=? AND lawyer_id=?",(session_id,uid)).fetchone()
        if not fresh or (uid not in (int(fresh["target_id"]),int(fresh["officer_id"])) and not lawyer):
            db.rollback(); return web.json_response({"error":"Доступ к протоколу изменился."},status=403)
        db.execute("INSERT INTO interrogation_entries(session_id,author_id,author_role,content,created_at) VALUES(?,?,?,?,?)",(session_id,uid,role,content,now_text()))
        db.commit()
        return web.json_response({"ok":True})
    except TransactionConflict: return web.json_response({"error":"Протокол занят."},status=409)
    except sqlite3.Error:
        if db.in_transaction: db.rollback()
        log.exception("Mini App: не удалось добавить запись в допрос №%s",session_id)
        return web.json_response({"error":"Не удалось сохранить запись."},status=500)


async def miniapp_interrogation_request_lawyer(request):
    uid=request["telegram_user_id"]
    try: payload=await request.json(); session_id=int(payload.get("session_id",0))
    except Exception: return web.json_response({"error":"Некорректный протокол."},status=400)
    try:
        begin_immediate()
        session=db.execute("SELECT * FROM interrogation_sessions WHERE id=? AND target_id=? AND status='Открыт'",(session_id,uid)).fetchone()
        if not session: db.rollback(); return web.json_response({"error":"Открытый протокол не найден."},status=404)
        already_requested=db.execute("SELECT 1 FROM interrogation_entries WHERE session_id=? AND author_id=? AND lower(content) LIKE '%прошу адвоката%'",(session_id,uid)).fetchone()
        if already_requested:
            db.rollback(); return web.json_response({"error":"Запрос адвоката уже внесён в протокол."},status=409)
        db.execute("INSERT INTO interrogation_entries(session_id,author_id,author_role,content,created_at) VALUES(?,?,'Участник','Прошу адвоката для участия в допросе.',?)",(session_id,uid,now_text()))
        db.commit()
        if bot is not None:
            try: await bot.send_message(int(session["officer_id"]),f"Участник допроса №{session_id} запросил адвоката.")
            except Exception: log.debug("Не удалось уведомить сотрудника о запросе адвоката",exc_info=True)
        return web.json_response({"ok":True})
    except TransactionConflict: return web.json_response({"error":"Протокол занят."},status=409)
    except sqlite3.Error:
        if db.in_transaction: db.rollback()
        log.exception("Mini App: ошибка запроса адвоката по допросу №%s",session_id)
        return web.json_response({"error":"Не удалось запросить адвоката."},status=500)


async def miniapp_interrogation_join(request):
    uid=request["telegram_user_id"]
    if not _is_lawyer(get_player(uid)):
        return web.json_response({"error":"Подключиться к допросу может только действующий адвокат."},status=403)
    try: payload=await request.json(); session_id=int(payload.get("session_id",0))
    except Exception: return web.json_response({"error":"Некорректный протокол."},status=400)
    try:
        begin_immediate()
        if not _is_lawyer(get_player(uid)):
            db.rollback(); return web.json_response({"error":"Полномочия адвоката изменились."},status=403)
        session=db.execute("SELECT * FROM interrogation_sessions WHERE id=? AND status='Открыт'",(session_id,)).fetchone()
        if not session: db.rollback(); return web.json_response({"error":"Открытый протокол не найден."},status=404)
        requested=db.execute("SELECT id FROM interrogation_entries WHERE session_id=? AND author_id=? AND lower(content) LIKE '%прошу адвоката%'",(session_id,session["target_id"])).fetchone()
        if not requested: db.rollback(); return web.json_response({"error":"Участник ещё не запросил адвоката."},status=409)
        db.execute("INSERT OR IGNORE INTO interrogation_lawyers(session_id,lawyer_id,joined_at) VALUES(?,?,?)",(session_id,uid,now_text()))
        if db.execute("SELECT changes()").fetchone()[0] != 1:
            db.rollback(); return web.json_response({"error":"Ты уже подключён к этому протоколу."},status=409)
        db.execute("INSERT INTO interrogation_entries(session_id,author_id,author_role,content,created_at) VALUES(?,?,'Адвокат','Адвокат подключился к защите.',?)",(session_id,uid,now_text()))
        db.commit()
        return web.json_response({"ok":True})
    except TransactionConflict: return web.json_response({"error":"Протокол занят."},status=409)
    except sqlite3.Error:
        if db.in_transaction: db.rollback()
        log.exception("Mini App: адвокат не смог подключиться к допросу №%s",session_id)
        return web.json_response({"error":"Не удалось подключить адвоката."},status=500)


async def miniapp_university_lecture(request):
    uid=request["telegram_user_id"]
    try: payload=await request.json()
    except Exception: return web.json_response({"error":"Некорректный запрос."},status=400)
    subject=str(payload.get("subject","")).strip() if isinstance(payload,dict) else ""
    if subject not in SUBJECTS: return web.json_response({"error":"Выбери предмет из учебной программы."},status=400)
    player=get_player(uid)
    if not player or not is_student(uid): return web.json_response({"error":"Провести учебную пару можно только для зачисленного студента."},status=403)
    if player["location"]!="Университет" or active_player_travel(uid): return web.json_response({"error":"Для занятия нужно находиться в кампусе университета."},status=409)
    teachers=[n for n in _nearby_npcs(player["location"]) if n["faction"]=="Университет" and n["rank"] in ("Преподаватель","Заместитель декана","Декан")]
    if not teachers: return web.json_response({"error":"Сейчас рядом нет преподавателя. Попробуй позже."},status=404)
    teacher=teachers[0]
    prompt=(f"Проведи для студента полноценную RP-лекцию по предмету «{subject}». "
            "Объясни тему последовательно: короткое вступление, 3–5 учебных тезисов, понятный пример, "
            "небольшой вопрос студенту для проверки понимания и домашнее задание. "
            "Не утверждай, что студент сдал экзамен или получил баллы; результаты зачёта фиксируются отдельной учебной системой.")
    reply=await _npc_ai_generate(teacher,player,prompt,channel="университетская лекция через Mini App",memory_user_id=uid)
    if not reply: return web.json_response({"error":"Преподаватель сейчас не смог провести занятие."},status=503)
    db.execute("INSERT INTO university_lecture_sessions(user_id,npc_id,subject,lecture_text,created_at) VALUES(?,?,?,?,?)",(uid,int(teacher["id"]),subject,reply,now_text()))
    db.commit()
    return web.json_response({"ok":True,"teacher":teacher["name"],"subject":subject,"lecture":reply,"note":"Лекция сохранена в истории NPC. Баллы и экзаменационные результаты не начисляются автоматически."})

async def miniapp_work_report(request):
    uid = request["telegram_user_id"]
    try: payload = await request.json()
    except Exception: return web.json_response({"error": "Некорректный JSON."}, status=400)
    try: session_id = int(payload.get("session_id", 0))
    except (TypeError, ValueError): return web.json_response({"error": "Некорректное поручение."}, status=400)
    body = str(payload.get("report", "")).strip()
    if len(body) < 80: return web.json_response({"error": "Отчёт должен содержать минимум 80 символов."}, status=400)
    player = _work_member(uid)
    row = db.execute("SELECT * FROM faction_work_sessions WHERE id=? AND user_id=? AND status='В работе'", (session_id, uid)).fetchone()
    if not player or not row or row["faction"] != player["faction"]:
        return web.json_response({"error": "Поручение не найдено или уже обработано."}, status=404)
    if int(row["stage_index"] or 0) < len(_faction_work_steps(row["faction"], row["task_key"])):
        return web.json_response({"error": "Сначала пройди все этапы поручения по порядку."}, status=409)
    try: elapsed = (datetime.now() - datetime.fromisoformat(row["created_at"])).total_seconds()
    except Exception: elapsed = 0
    if elapsed < 300: return web.json_response({"error": "Для сдачи отчёта требуется минимум 5 минут после получения поручения."}, status=409)
    try:
        begin_immediate()
        cur = db.execute("UPDATE faction_work_sessions SET report=?,status='На проверке' WHERE id=? AND user_id=? AND faction=? AND status='В работе'", (body[:3000], session_id, uid, player["faction"]))
        if cur.rowcount != 1: raise sqlite3.IntegrityError("work_report_already_submitted")
        db.commit()
    except TransactionConflict:
        return web.json_response({"error": "Система занята другой операцией. Повтори чуть позже."}, status=409)
    except sqlite3.Error:
        if db.in_transaction: db.rollback()
        return web.json_response({"error": "Отчёт уже отправлен или система занята."}, status=409)
    ranks = _faction_work_leader_ranks(player["faction"])
    leaders = db.execute("SELECT user_id FROM players WHERE faction=? AND rank IN (?,?) AND user_id!=?", (player["faction"], *ranks, uid)).fetchall()
    reviewer_ids = [int(r["user_id"]) for r in leaders] or [int(x) for x in ADMIN_IDS if int(x) != uid]
    for reviewer_id in reviewer_ids:
        try:
            kb = InlineKeyboardMarkup(inline_keyboard=[[InlineKeyboardButton(text="✅ Принять", callback_data=f"fwork:review:{session_id}:accept"), InlineKeyboardButton(text="❌ Отклонить", callback_data=f"fwork:review:{session_id}:reject")]])
            await bot.send_message(reviewer_id, f"Отчёт Mini App №{session_id} · {player['faction']} · {player_display_name(player)}\n{body[:1800]}", reply_markup=kb)
        except Exception: log.exception("Не удалось уведомить проверяющего Mini App")
    return web.json_response({"ok": True, "status": "На проверке"})


def create_miniapp_server():
    app = web.Application(middlewares=[miniapp_auth_middleware])
    app.router.add_get("/", miniapp_index)
    app.router.add_get("/api/me", miniapp_me)
    app.router.add_get("/api/bank", miniapp_bank)
    app.router.add_get("/api/faction/members", miniapp_faction_members)
    app.router.add_post("/api/faction/rank", miniapp_faction_rank)
