# 43. ЗАПУСК БОТА
# =========================================================



CRIME_PRODUCTION_COST = 1000
CRIME_PRODUCTION_OUTPUT = 25


def _crime_production_profile(faction):
    if faction == "Бар":
        return {"key": "bar_fermentation", "input": "Крахмал", "intro": "Купи сырьё и помести его в игровую бочку. Чем дольше идёт ферментация, тем меняется напиток; при слишком долгом ожидании партия прокиснет."}
    if faction == "The Crips":
        return {"key": "crips_grow", "input": "Игровой саженец", "intro": "Запусти абстрактный игровой цикл выращивания и дождись готовности партии. Здесь только внутриигровой таймер и результат, без реальных инструкций."}
    return None


def _production_result(faction, started_at, now=None):
    now = now or datetime.now()
    try:
        elapsed = max(0, int((now - datetime.fromisoformat(started_at)).total_seconds() // 60))
    except (TypeError, ValueError):
        return "Испорченная партия", 0, 0, True, "Не удалось прочитать время запуска."
    if faction == "Бар":
        if elapsed < 30:
            return "Ферментация", 0, 0, False, f"Идёт ферментация: {elapsed}/30 минут до первой стадии."
        if elapsed < 60:
            return "Ранний напиток", 25, 30, False, "Первая стадия готова: 25 бутылок по $30."
        if elapsed < 90:
            return "Пиво", 25, 40, False, "Оптимальная стадия: 25 бутылок пива по $40."
        if elapsed < 120:
            return "Крепкий напиток", 25, 45, False, "Поздняя стадия: 25 бутылок по $45; партия скоро прокиснет."
        return "Прокисшая партия", 0, 0, True, "Партия прокисла из-за слишком долгого ожидания."
    if elapsed < 60:
        return "Рост партии", 0, 0, False, f"Игровой цикл продолжается: {elapsed}/60 минут."
    if elapsed < 120:
        return "Готовая партия", 25, 40, False, "Партия готова: 25 игровых единиц по $40."
    if elapsed < 180:
        return "Качественная партия", 25, 45, False, "Поздняя игровая стадия: 25 единиц по $45."
    return "Испорченная партия", 0, 0, True, "Партия испорчена из-за слишком долгого ожидания."


async def _show_crime_production(target, user_id):
    player = get_player(user_id)
    profile = _crime_production_profile(player["faction"]) if player else None
    if not profile:
        await target.answer("Производство доступно только бару и The Crips.")
        return
    active = db.execute(
        "SELECT * FROM crime_production_batches WHERE user_id=? AND faction=? AND status='В процессе' ORDER BY id DESC LIMIT 1",
        (user_id, player["faction"])
    ).fetchone()
    rows = []
    if active:
        rows = [
            [InlineKeyboardButton(text="⏱ Проверить готовность", callback_data="fprod:status")],
            [InlineKeyboardButton(text="📦 Забрать партию", callback_data="fprod:collect")]
        ]
        state_text = f"Активная партия №{active['id']} запущена: {active['started_at']}."
    else:
        rows = [[InlineKeyboardButton(text=f"🛒 Купить сырьё и начать — ${CRIME_PRODUCTION_COST:,}", callback_data="fprod:start")]]
        state_text = "Активной партии нет."
    await target.answer(
        f"🏭 ПРОИЗВОДСТВО · {player['faction']}\n{profile['intro']}\n"
        f"Сырьё: {profile['input']} · запуск ${CRIME_PRODUCTION_COST:,}\n"
        f"Потенциальный выпуск: {CRIME_PRODUCTION_OUTPUT} единиц.\n{state_text}",
        reply_markup=InlineKeyboardMarkup(inline_keyboard=rows)
    )


@dp.callback_query(F.data.startswith("fprod:"))
async def crime_production_callback(callback: CallbackQuery):
    user_id = callback.from_user.id
    player = get_player(user_id)
    if not player or player["faction"] not in ("Бар", "The Crips"):
        await callback.answer("Нет доступа к производству.", show_alert=True)
        return
    action = callback.data.split(":", 1)[1]
    if action == "start":
        try:
            begin_immediate()
            active = db.execute("SELECT id FROM crime_production_batches WHERE user_id=? AND status='В процессе' LIMIT 1", (user_id,)).fetchone()
            current = get_player(user_id)
            if active:
                db.rollback()
                await callback.answer("У тебя уже есть активная партия.", show_alert=True)
                return
            if not current or current["faction"] != player["faction"]:
                db.rollback()
                await callback.answer("Организация изменилась. Открой меню заново.", show_alert=True)
                return
            paid = db.execute("UPDATE players SET balance=balance-? WHERE user_id=? AND balance>=?", (CRIME_PRODUCTION_COST, user_id, CRIME_PRODUCTION_COST))
            if paid.rowcount != 1:
                db.rollback()
                await callback.answer("Недостаточно игровых денег.", show_alert=True)
                return
            profile = _crime_production_profile(player["faction"])
            db.execute(
                "INSERT INTO crime_production_batches(user_id,faction,product_key,started_at,status) VALUES(?,?,?,?,'В процессе')",
                (user_id, player["faction"], profile["key"], now_text())
            )
            db.execute(
                "INSERT INTO bank_transactions(user_id,other_user_id,amount,transaction_type,description,created_at) VALUES(?,0,?,'store_purchase',?,?)",
                (user_id, CRIME_PRODUCTION_COST, f"Сырьё для производства: {player['faction']}", now_text())
            )
            db.commit()
        except (sqlite3.Error, TransactionConflict):
            if db.in_transaction:
                db.rollback()
            log.exception("Ошибка запуска фракционного производства")
            await callback.answer("Не удалось запустить производство.", show_alert=True)
            return
        await callback.answer("Партия запущена.")
        await _show_crime_production(callback.message, user_id)
        return

    batch = db.execute(
        "SELECT * FROM crime_production_batches WHERE user_id=? AND faction=? AND status='В процессе' ORDER BY id DESC LIMIT 1",
        (user_id, player["faction"])
    ).fetchone()
    if not batch:
        await callback.answer("Активной партии нет.", show_alert=True)
        return
    result_name, output_qty, unit_price, spoiled, note = _production_result(player["faction"], batch["started_at"])
    if action == "status":
        await callback.answer(note, show_alert=True)
        await callback.message.answer(f"🏭 Партия №{batch['id']}\nСостояние: {result_name}\n{note}")
        return
    if action == "collect":
        if output_qty <= 0 and not spoiled:
            await callback.answer(note, show_alert=True)
            return
        try:
            begin_immediate()
            current = get_player(user_id)
            if not current or current["faction"] != player["faction"]:
                db.rollback()
                await callback.answer("Ты покинул организацию.", show_alert=True)
                return
            current_batch = db.execute(
                "SELECT id FROM crime_production_batches WHERE id=? AND user_id=? AND faction=? AND status='В процессе'",
                (batch["id"], user_id, player["faction"])
            ).fetchone()
            if not current_batch:
                db.rollback()
                await callback.answer("Партия уже обработана.", show_alert=True)
                return
            if spoiled:
                db.execute(
                    "UPDATE crime_production_batches SET status='Испорчена',result_name=?,completed_at=? WHERE id=? AND status='В процессе'",
                    (result_name, now_text(), batch["id"])
                )
                db.commit()
                await callback.answer(note, show_alert=True)
                await _show_crime_production(callback.message, user_id)
                return
            total = output_qty * unit_price
            credited = db.execute("UPDATE players SET balance=balance+? WHERE user_id=? AND balance<=?", (total, user_id, MAX_BALANCE-total))
            if credited.rowcount != 1:
                raise sqlite3.IntegrityError("production_balance_limit")
            completed_at = now_text()
            db.execute(
                "UPDATE crime_production_batches SET status='Завершена',result_name=?,output_qty=?,unit_price=?,completed_at=? WHERE id=? AND status='В процессе'",
                (result_name, output_qty, unit_price, completed_at, batch["id"])
            )
            task_key = "bar_fermentation" if player["faction"] == "Бар" else "crips_grow"
            task_title = "Производство напитков" if player["faction"] == "Бар" else "Производственный цикл группировки"
            session = db.execute(
                """INSERT INTO faction_work_sessions(
                    user_id,faction,department,task_key,task_title,task_description,status,report,reward,created_at,completed_at,stage_index
                ) VALUES(?,?, '', ?, ?, ?, 'Выполнено', ?, ?, ?, ?, 4)""",
                (user_id, player["faction"], task_key, task_title, "Автоматически засчитано по завершении производственной партии.", f"Партия №{batch['id']}: {result_name}, {output_qty} ед.", total, completed_at, completed_at)
            )
            db.execute(
                "INSERT INTO faction_work_log(user_id,faction,department,task_key,task_title,reward,created_at,session_id) VALUES(?,?, '', ?, ?, ?, ?, ?)",
                (user_id, player["faction"], task_key, task_title, total, completed_at, session.lastrowid)
            )
            db.execute(
                "INSERT INTO bank_transactions(user_id,other_user_id,amount,transaction_type,description,created_at) VALUES(?,0,?,'work_reward',?,?)",
                (user_id, total, f"Реализация партии: {result_name}", now_text())
            )
            db.commit()
        except (sqlite3.Error, TransactionConflict):
            if db.in_transaction:
                db.rollback()
            log.exception("Ошибка сбора фракционной партии")
            await callback.answer("Не удалось завершить партию.", show_alert=True)
            return
        await callback.answer("Партия реализована.")
        await callback.message.answer(
            f"✅ Партия №{batch['id']} завершена.\nПродукт: {result_name}\n"
            f"Количество: {output_qty}\nЦена за единицу: ${unit_price}\nНачислено: ${total:,}."
        )
        await _show_crime_production(callback.message, user_id)
        return
    await callback.answer("Неизвестное действие.", show_alert=True)


