CRIME_FACTIONS = {"The Crips", "Русская мафия", "Бар"}
ARSENAL_CATALOG = {
    "pistol": ("Пистолет (арсенал)", 90),
    "heavy_pistol": ("Тяжёлый пистолет (арсенал)", 150),
    "shotgun": ("Дробовик (арсенал)", 220),
    "smg": ("Пистолет-пулемёт (арсенал)", 300),
    "rifle": ("Винтовка (арсенал)", 450),
}


def _hour_slot(now=None):
    now = now or datetime.now()
    return now.strftime("%Y-%m-%d-%H")


def _arsenal_offers(faction, now=None):
    """Каждый час доступна часть каталога; одинаковый ассортимент для всей фракции."""
    slot = _hour_slot(now)
    seed = int(hashlib.sha256(f"{faction}:{slot}".encode("utf-8")).hexdigest()[:16], 16)
    keys = list(ARSENAL_CATALOG)
    random.Random(seed).shuffle(keys)
    return keys[:3]


def _is_weekend(now=None):
    now = now or datetime.now()
    return now.weekday() >= 5


